/* Voltio · cada concepto tiene varias formas de explicarse.
   Si fallas un ejercicio, aparece la siguiente explicación y una pregunta para comprobarla. */
const mcq = (q, o, e, x = {}) => ({ t: 'mc', q, o, a: 0, e, ...x });
const CONCEPTS = {
  /* --- Curso base (m0–m7): una destreza por concepto --- */
  ba_pow10: { name: 'Qué vale una potencia de 10', alts: [
    { title: 'Cuenta los ceros', text: '10ⁿ con n positivo es un 1 seguido de n ceros: 10⁴ = 10 000. Con n negativo, la coma se mueve n posiciones a la izquierda desde el 1: 10⁻² = 0,01 y 10⁻³ = 0,001. Y 10⁰ = 1.', q: mcq('¿Cuánto vale 10⁻³?', ['0,001', '−1000', '0,0001', '−3'], 'Exponente negativo: el 1 queda en la tercera posición tras la coma.') },
    { title: 'Multiplicar o dividir entre 10', text: 'Piensa en 10ⁿ como “empezar en 1 y multiplicar por 10 n veces”: 10³ = 1 × 10 × 10 × 10 = 1000. Si el exponente es negativo, en vez de multiplicar <b>divides</b> entre 10 esas veces: 10⁻² = 1 ÷ 10 ÷ 10 = 0,01.\nUn exponente negativo nunca da un número negativo: da un número pequeño.', q: mcq('¿Cuánto vale 10⁻¹?', ['0,1', '−10', '−0,1', '10'], '1 dividido entre 10 una vez.') }
  ] },
  ba_pow10op: { name: 'Multiplicar y dividir potencias de 10', alts: [
    { title: 'Suma o resta exponentes', text: 'Al <b>multiplicar</b> potencias de 10 se <b>suman</b> los exponentes: 10³ × 10⁻⁵ = 10⁻². Al <b>dividir</b> se <b>resta</b> el de abajo al de arriba: 10² ÷ 10⁻³ = 10⁵.\nCuidado con los signos: restar un negativo es sumar.', q: mcq('¿Cuánto es 10⁴ ÷ 10⁻²?', ['10⁶', '10²', '10⁻⁸', '10⁻²'], '4 − (−2) = 6.') },
    { title: 'Compruébalo con ceros', text: 'Si dudas, escríbelo con ceros: 10³ × 10² = 1000 × 100 = 100 000, que tiene cinco ceros: 10⁵. Por eso los exponentes se suman. Y 10⁶ ÷ 10² = 1 000 000 ÷ 100 = 10 000 = 10⁴: al dividir se quitan ceros, así que se restan.', q: mcq('¿Cuánto es 10² × 10³?', ['10⁵', '10⁶', '10¹', '10⁻¹'], '100 × 1000 = 100 000: cinco ceros.') },
    { title: 'Los negativos, como deudas', text: 'Un exponente negativo son “ceros que debes”. 10⁻³ × 10⁵: debes 3 y tienes 5, te quedan 2 → 10². 10⁻² × 10⁻⁴: debes 2 y luego 4 más → 10⁻⁶.\nEl error típico es multiplicar los exponentes (−2 × −4 = 8): se suman.', q: mcq('¿Cuánto es 10⁻² × 10⁻⁴?', ['10⁻⁶', '10⁸', '10²', '10⁻⁸'], 'Se suman: −2 + (−4) = −6.') }
  ] },
  ba_sci: { name: 'Notación científica', alts: [
    { title: 'Una cifra delante de la coma', text: 'En notación científica el número se escribe como una sola cifra (del 1 al 9) delante de la coma, sus decimales y × 10ⁿ. Mueve la coma hasta dejar una cifra delante y cuenta los saltos: 4700 → 4,7 (tres saltos a la izquierda) → <b>4,7 × 10³</b>.', q: mcq('¿Cómo se escribe 68 000 en notación científica?', ['6,8 × 10⁴', '68 × 10³', '6,8 × 10³', '0,68 × 10⁵'], 'La coma se mueve cuatro posiciones: 10⁴. 68 × 10³ vale lo mismo, pero eso es notación de ingeniería.') },
    { title: 'Números pequeños, exponente negativo', text: 'Si el número es menor que 1, la coma se mueve a la <b>derecha</b> hasta dejar una cifra delante y el exponente sale negativo: 0,00022 → 2,2 (cuatro saltos) → <b>2,2 × 10⁻⁴</b>.\nComprobación rápida: un número pequeño lleva exponente negativo; uno grande, positivo.', q: mcq('¿Cómo se escribe 0,0033 en notación científica?', ['3,3 × 10⁻³', '3,3 × 10³', '3,3 × 10⁻²', '0,33 × 10⁻²'], 'Tres saltos a la derecha hasta dejar 3,3.') }
  ] },
  ba_prefval: { name: 'Qué vale cada prefijo', alts: [
    { title: 'La escalera de mil', text: 'Los prefijos van de 1000 en 1000:\n<b>p</b> 10⁻¹² · <b>n</b> 10⁻⁹ · <b>µ</b> 10⁻⁶ · <b>m</b> 10⁻³ · (unidad) · <b>k</b> 10³ · <b>M</b> 10⁶ · <b>G</b> 10⁹.\nLos de debajo de la unidad dividen; k, M y G multiplican.', q: mcq('¿Cuánto vale el prefijo “n”?', ['10⁻⁹', '10⁻⁶', '10⁹', '10⁻¹²'], 'nano: mil veces menos que micro.') },
    { title: 'Mayúscula o minúscula', text: 'Los dos que más se confunden: <b>m</b> (mili) es una milésima y <b>M</b> (mega) es un millón; entre uno y otro hay un factor de mil millones. Regla: los prefijos grandes (M, G) van en mayúscula y los pequeños en minúscula. La excepción habitual es k (kilo): minúscula aunque multiplica.', q: mcq('¿Qué es 2 MΩ?', ['2 000 000 Ω', '0,002 Ω', '2000 Ω', '20 Ω'], 'M mayúscula: mega, un millón.') },
    { title: 'Con ejemplos de tu mesa', text: 'Asocia cada prefijo a algo real: un condensador cerámico de 100 <b>n</b>F, un electrolítico de 100 <b>µ</b>F, la corriente de un LED, 20 <b>m</b>A, una resistencia de 10 <b>k</b>Ω, el reloj de 16 <b>M</b>Hz de una Arduino. Entre cada prefijo y el siguiente hay un salto de 1000.', q: mcq('¿Qué prefijo vale 10⁻⁶?', ['µ (micro)', 'm (mili)', 'n (nano)', 'M (mega)'], 'Micro: una millonésima.') }
  ] },
  ba_estimate: { name: 'Estimar el orden de magnitud', alts: [
    { title: 'Redondea y divide', text: 'Redondea los datos a números cómodos y haz la cuenta de cabeza: 12 V / 2,2 kΩ ≈ 12 / 2000 = 0,006 A ≈ <b>6 mA</b>. No buscas el valor exacto, sino saber si son microamperios, miliamperios o amperios.', q: mcq('Sin calculadora: 9 V entre 4,7 kΩ…', ['Unos 2 mA', 'Unos 2 A', 'Unos 20 mA', 'Unos 0,2 mA'], '9 / 5000 ≈ 0,0018 A ≈ 2 mA.') },
    { title: 'Voltios entre kiloohmios dan miliamperios', text: 'Un atajo muy útil: <b>V / kΩ = mA</b>. 5 V entre 10 kΩ son 0,5 mA (cientos de µA); 9 V entre 1 kΩ, 9 mA; 12 V entre 100 Ω (0,1 kΩ), 120 mA. Si la calculadora te da otra cosa, revisa los prefijos.', q: mcq('5 V entre 100 kΩ, ¿orden de magnitud de la corriente?', ['Decenas de µA', 'Decenas de mA', 'Unos pocos mA', 'Amperios'], '5 / 100 = 0,05 mA = 50 µA.') },
    { title: 'Sospecha de lo raro', text: 'Antes de fiarte de un resultado, pregúntate si tiene sentido. Una resistencia de LED disipa milivatios, no vatios; un LED lleva miliamperios, no amperios. Si el resultado se sale por un factor de 1000, casi seguro has usado 1 en vez de 1000 (kΩ como Ω) o al revés.', q: mcq('Calculas que la resistencia de tu LED disipa 25 W. ¿Qué es lo más probable?', ['Un error de prefijo: serán unos 25 mW', 'Que necesitas una resistencia de 25 W', 'Que el LED está roto', 'Que la pila es muy grande'], 'Mil veces más de lo razonable: error de unidades.') }
  ] },
  ba_sigfig: { name: 'Cifras significativas', alts: [
    { title: 'Cuáles cuentan', text: 'Cuenta desde la primera cifra que no es cero. Los ceros de la <b>izquierda</b> no cuentan: solo colocan la coma (0,0047 tiene dos). Los ceros entre cifras sí (1,05 tiene tres). Los ceros <b>finales tras la coma</b> también: 4,70 tiene tres, porque dicen que se midió hasta las centésimas.', q: mcq('¿Cuántas cifras significativas tiene 0,00250?', ['3', '6', '2', '5'], 'Los ceros iniciales no cuentan; el cero final sí: 2, 5 y 0.') },
    { title: 'Cifras que significan algo', text: 'Las cifras significativas dicen cuánto te fías de un número. Si la resistencia es del 5 %, escribir 4,7123 kΩ es presumir de una precisión que no tienes. Regla práctica: da el resultado con tantas cifras como el dato menos preciso, normalmente 2 o 3.', q: mcq('Calculas 9 V / 470 Ω = 0,019148936 A. ¿Cómo lo escribes?', ['19 mA', '19,148936 mA', '0,019148936 A', '19 A'], 'Dos o tres cifras bastan: los datos no dan para más.') },
    { title: 'La notación lo deja claro', text: 'Con ceros al final de un número entero hay ambigüedad: ¿“4700” tiene dos cifras o cuatro? La notación científica o la de ingeniería lo resuelven: 4,7 × 10³ tiene dos; 4,700 × 10³ tiene cuatro. Solo cuentan las cifras de delante del × 10ⁿ.', q: mcq('¿Cuántas cifras significativas tiene 3,30 × 10³?', ['3', '2', '4', '6'], 'Solo cuentan 3, 3 y 0; la potencia de 10 no.') }
  ] },
  ba_tolerance: { name: 'Tolerancia: intervalo de valores posibles', alts: [
    { title: 'Resta y suma el porcentaje', text: 'La tolerancia dice cuánto puede apartarse un componente de su valor nominal. Calcula ese porcentaje del valor y réstalo y súmalo: 1 kΩ ±5 % → 5 % de 1000 = 50 Ω → entre <b>950 y 1050 Ω</b>. El valor real puede ser cualquiera dentro de ese intervalo.', q: mcq('Una resistencia de 2,2 kΩ ±10 %. ¿Entre qué valores puede estar?', ['1,98 kΩ y 2,42 kΩ', '2,19 kΩ y 2,21 kΩ', '2,2 kΩ y 2,42 kΩ', '1,2 kΩ y 3,2 kΩ'], '10 % de 2200 = 220 Ω: se resta y se suma.') },
    { title: 'Se arrastra al resultado', text: 'Si una resistencia puede variar un ±5 %, lo que calcules con ella (una corriente, una tensión) también puede variar más o menos un ±5 %. Si calculas 9,0 mA con una resistencia del 5 %, lo realista es “entre unos 8,6 y 9,5 mA”. Y si mides 6,3 V donde esperabas 6 V, esa diferencia del 5 % encaja con resistencias del 5 %.', q: mcq('Calculas 4,0 mA con una resistencia del ±5 %. ¿Qué intervalo es realista?', ['Entre unos 3,8 y 4,2 mA', 'Exactamente 4,000 mA', 'Entre 2 y 6 mA', 'Entre 3,99 y 4,01 mA'], '5 % de 4 mA = 0,2 mA.') },
    { title: 'Bandas y porcentajes', text: 'La última banda de una resistencia indica la tolerancia: dorada ±5 %, plateada ±10 %, marrón ±1 %. Un ±1 % no da “otro valor”, da <b>menos dispersión</b>: con 10 kΩ ±1 % el valor real está entre 9,9 y 10,1 kΩ; con ±10 %, entre 9 y 11 kΩ.', q: mcq('10 kΩ con banda dorada (±5 %). ¿Qué valor es imposible para esa resistencia?', ['11 kΩ', '9,6 kΩ', '10,4 kΩ', '10 kΩ'], 'El intervalo va de 9,5 a 10,5 kΩ.') }
  ] },
  ba_accuracy: { name: 'Exactitud de un instrumento', alts: [
    { title: 'Un margen sobre la lectura', text: 'Ningún aparato es perfecto. “Exactitud ±1 %” significa que el valor real puede estar un 1 % por encima o por debajo de lo que marca. Si lees 4,73 V, el 1 % son unos 0,05 V: anota <b>4,73 V ± 0,05 V</b>, es decir, entre 4,68 y 4,78 V.', q: mcq('Un multímetro de ±2 % marca 10,0 V. ¿Entre qué valores está la tensión real?', ['Entre 9,8 y 10,2 V', 'Entre 9,98 y 10,02 V', 'Exactamente 10,0 V', 'Entre 8 y 12 V'], '2 % de 10 V = 0,2 V.') },
    { title: 'Porcentaje más dígitos', text: 'Las hojas de los multímetros dan la exactitud como “±(0,5 % + 2 dígitos)”: un porcentaje de la lectura más unas unidades del último dígito. Con 5,00 V en el rango de 20 V: el 0,5 % son 0,025 V y 2 dígitos son 0,02 V; en total, unos ±0,045 V. Es cuánto puede desviarse la lectura del valor real.', q: mcq('¿Qué indica “±(1 % + 3 dígitos)” en un multímetro?', ['Cuánto puede desviarse la lectura del valor real', 'Cuántos decimales muestra', 'La tensión máxima que aguanta', 'La velocidad de medida'], 'Es la exactitud: el margen de error de la lectura.') }
  ] },
  ba_solve: { name: 'Despejar una fórmula', alts: [
    { title: 'La balanza', text: 'Una ecuación es una balanza equilibrada: lo que hagas a un lado, házselo al otro. De V = I × R, para dejar I sola divides los dos lados entre R: <b>I = V / R</b>. Para quitar algo que multiplica, divides; para quitar algo que divide, multiplicas.', q: mcq('De P = V × I, despeja V', ['V = P / I', 'V = P × I', 'V = I / P', 'V = P − I'], 'Divide los dos lados entre I.') },
    { title: 'Prueba con números', text: 'Si dudas entre dos despejes, prueba con números fáciles. Con V = I × R, I = 2 y R = 3 dan V = 6. ¿I = V / R? 6 / 3 = 2 ✓. ¿I = R / V? 3 / 6 = 0,5 ✗. El que devuelve el número de partida es el bueno.', q: mcq('τ = R × C. ¿Cuánto vale C?', ['C = τ / R', 'C = R / τ', 'C = τ × R', 'C = τ − R'], 'Con R = 2 y C = 5, τ = 10, y 10 / 2 = 5 ✓.') },
    { title: 'Cuadrados y raíces', text: 'Si la incógnita está al cuadrado, primero déjala sola y luego haz la raíz. De P = I² × R: divide entre R → I² = P / R → <b>I = √(P / R)</b>. Si la incógnita divide, como R en P = V² / R, multiplica los dos lados por R y luego divide entre P: <b>R = V² / P</b>.', q: mcq('De P = V² / R, ¿cuánto vale V?', ['√(P × R)', 'P × R', '√(P / R)', 'P / R'], 'Multiplica por R → V² = P × R; luego la raíz.') }
  ] },
  ba_units: { name: 'Unidades y análisis dimensional', alts: [
    { title: 'Unidades que se simplifican', text: 'Trata las unidades como letras que se multiplican y se dividen. Ω = V / A, así que V / Ω = V / (V / A) = <b>A</b>. Y W = V · A. Con unas pocas equivalencias (V = J/C, A = C/s, Ω = V/A, F = C/V) sabes qué sale de cualquier fórmula sin poner números.', q: mcq('¿Qué da A × Ω?', ['Voltios', 'Vatios', 'Amperios', 'Segundos'], 'A × (V / A) = V: es la ley de Ohm.') },
    { title: 'Una comprobación gratis', text: 'Si una fórmula debe dar vatios, sus unidades tienen que acabar en vatios. P = V / R da V / Ω = A: imposible que sea potencia. P = V² / R da V · (V / Ω) = V · A = W ✓. Así pillas una fórmula mal recordada sin probar ningún número.', q: mcq('Alguien escribe I = V × R. ¿Qué da la derecha?', ['V · Ω, que no son amperios: la fórmula está mal', 'Amperios', 'Vatios', 'Segundos'], 'I = V / R sí da amperios.') },
    { title: 'Unidades sorpresa: segundos', text: 'Algunas combinaciones dan tiempo: Ω · F = (V/A) · (C/V) = C/A = <b>s</b>, y H / Ω = s. Por eso τ = R · C y τ = L / R salen en segundos. Si una constante de tiempo te sale en otra unidad, revisa la fórmula.', q: mcq('¿Qué unidad da kΩ × µF?', ['Milisegundos', 'Segundos', 'Microsegundos', 'Hercios'], '10³ × 10⁻⁶ = 10⁻³ s.') }
  ] },
  ba_wh: { name: 'mAh, Wh y julios', alts: [
    { title: 'Carga no es energía', text: 'Los <b>mAh</b> miden carga: corriente × tiempo (1 mAh = 3,6 C). Los <b>Wh</b> miden energía: potencia × tiempo (1 Wh = 3600 J). Para pasar de carga a energía multiplica por la tensión: 2000 mAh a 3,7 V = 2 Ah × 3,7 V = <b>7,4 Wh</b>.', q: mcq('Una batería de 7,4 V y 1000 mAh. ¿Energía?', ['7,4 Wh', '1000 Wh', '0,74 Wh', '7400 Wh'], '1 Ah × 7,4 V.') },
    { title: 'Compara con Wh', text: 'Una batería de 3,7 V y 3000 mAh y otra de 12 V y 1000 mAh: ¿cuál guarda más? Por los mAh parece la primera, pero en energía la primera tiene 11,1 Wh y la segunda 12 Wh. Los mAh solo sirven para comparar baterías de la <b>misma tensión</b>; para todo lo demás, Wh.', q: mcq('¿Qué cifra usas para comparar una batería de 3,7 V con una de 12 V?', ['Los Wh', 'Los mAh', 'Los voltios', 'El peso'], 'Energía = carga × tensión.') },
    { title: 'Del kWh al julio', text: 'Un vatio es un julio cada segundo, así que 1 Wh = 1 W durante 3600 s = <b>3600 J</b>, y 1 kWh = 3,6 millones de julios. El kWh de la factura y el Wh de una batería miden lo mismo: energía. El mAh, en cambio, mide carga.', q: mcq('¿Cuántos julios son 2 Wh?', ['7200 J', '3600 J', '120 J', '2000 J'], '2 × 3600.') }
  ] },
  ba_percent: { name: 'Calcular un porcentaje', alts: [
    { title: 'Multiplica y divide entre 100', text: 'El 20 % de algo son 20 partes de cada 100: multiplica por 20 y divide entre 100. 20 % de 5 V = 5 × 20 / 100 = <b>1 V</b>. Es lo mismo que multiplicar por 0,2.', q: mcq('¿Cuánto es el 25 % de 12 V?', ['3 V', '0,48 V', '25 V', '4,8 V'], '12 × 25 / 100.') },
    { title: 'Porcentajes de cabeza', text: '10 % = dividir entre 10 (la coma se mueve un lugar). 50 % = la mitad. 25 % = la mitad de la mitad. 5 % = la mitad del 10 %. Ejemplo: el 10 % de 3,3 V es 0,33 V y el 5 %, 0,165 V.', q: mcq('¿Cuánto es el 10 % de 9 V?', ['0,9 V', '0,09 V', '9 V', '90 V'], 'Dividir entre 10.') }
  ] },
  ba_logaxis: { name: 'Escalas logarítmicas', alts: [
    { title: 'Cada marca multiplica', text: 'En un eje logarítmico, cada paso igual multiplica por lo mismo: 1, 10, 100, 1000. Cada ×10 es una <b>década</b>; para contarlas, cuenta los ×10 (de 10 Hz a 100 kHz hay 4). A medio camino entre dos valores está el que multiplica igual a cada lado: entre 10 y 1000, el 100.', q: mcq('¿Cuántas décadas hay de 1 Hz a 1 kHz?', ['3', '1000', '2', '999'], '1 → 10 → 100 → 1000.') },
    { title: 'La posición es el logaritmo', text: 'Lo que se reparte por igual en el eje es el logaritmo. Dentro de una década, un valor queda a log(valor / inicio) del camino: el 2 al 30 % (log 2 ≈ 0,30), el 5 al 70 %. El punto medio entre 10 y 1000 está en log = 2, es decir, en 100. Y cada década ocupa lo mismo en el eje.', q: mcq('En la década de 10 Hz a 100 Hz, ¿dónde queda 50 Hz?', ['A un 70 % del camino', 'A la mitad', 'A un 30 % del camino', 'Al 90 %'], 'log(5) ≈ 0,70.') }
  ] },
  ba_loggraph: { name: 'Rectas en gráficas logarítmicas', alts: [
    { title: 'Qué significa una recta', text: 'En una gráfica logarítmica, una recta no significa “proporcional”. Con <b>los dos ejes</b> logarítmicos (log–log), una recta es una ley de potencias: pendiente −1 es inversamente proporcional (×10 en un eje, ÷10 en el otro) y +1, proporcional. Con <b>solo el eje vertical</b> logarítmico (semilog), una recta es una exponencial: cada paso igual en horizontal multiplica la otra magnitud por lo mismo.', q: mcq('En log–log, una recta sube una década por cada década. ¿Qué relación es?', ['Directamente proporcional', 'Inversamente proporcional', 'Exponencial', 'Constante'], 'Pendiente +1: ×10 → ×10.') },
    { title: 'Con números', text: 'Log–log con pendiente −1: de 1 kHz a 10 kHz la amplitud pasa de 1 V a 0,1 V, y de 10 a 100 kHz, a 0,01 V: inversamente proporcional. Semilog: la corriente de un diodo pasa de 1 µA a 10 µA y a 100 µA con saltos iguales de tensión (unas decenas de milivoltios cada uno): eso es crecer de forma exponencial.', q: mcq('Corriente en escala logarítmica y tensión en escala lineal: sale una recta. La corriente…', ['Crece de forma exponencial con la tensión', 'Es proporcional a la tensión', 'Es constante', 'Baja con la tensión'], 'Recta en semilog = exponencial.') }
  ] },
  ba_log10: { name: 'Logaritmo en base 10', alts: [
    { title: 'El exponente que falta', text: 'log₁₀(x) responde a una pregunta: ¿10 elevado a cuánto da x? log(1000) = 3 porque 10³ = 1000. log(1) = 0 porque 10⁰ = 1. Y log(0,01) = −2 porque 10⁻² = 0,01.', q: mcq('¿Cuánto vale log₁₀(0,001)?', ['−3', '3', '0,001', '−1000'], '10⁻³ = 0,001.') },
    { title: 'Cuenta ceros', text: 'Para potencias de 10, el logaritmo es contar ceros: log(100) = 2, log(10 000) = 4. Si el número es menor que 1, cuenta cuántas posiciones hay que mover la coma para llegar a 1 y ponle signo menos: log(0,1) = −1. Entre 1 y 10, el logaritmo está entre 0 y 1.', q: mcq('¿Cuánto vale log₁₀(100 000)?', ['5', '100 000', '4', '6'], 'Cinco ceros.') }
  ] },
  /* ba:m0 fin */
  ba_materials: { name: 'Conductores, aislantes y semiconductores', alts: [
    { title: 'Cuántos electrones libres', text: 'Todo depende de cuántos electrones libres tiene el material. <b>Conductores</b> (cobre, aluminio, plata, oro): muchísimos. <b>Aislantes</b> (plástico, goma, vidrio, aire seco): casi ninguno. <b>Semiconductores</b> (silicio, germanio): pocos y controlables; por eso los diodos, transistores y chips se hacen de silicio.', q: mcq('¿En qué grupo está el silicio?', ['Semiconductor', 'Conductor', 'Aislante', 'Imán'], 'Conduce a medias y se puede controlar: la base de los chips.') },
    { title: 'Para qué se usa cada uno', text: 'Un cable lo resume: cobre dentro para llevar la corriente y plástico fuera para que no llegue a ti ni a otros cables. Ojo con el agua: el agua del grifo lleva sales disueltas que la hacen conductora, así que electricidad y agua, nunca juntas. Y con los semiconductores se fabrican los componentes que controlan la corriente.', q: mcq('¿Por qué el agua del grifo es peligrosa cerca de la electricidad?', ['Conduce por las sales disueltas', 'Es un aislante perfecto', 'Es un semiconductor', 'Solo conduce si está caliente'], 'Las sales la hacen conductora.') }
  ] },
  ba_drift: { name: 'Por qué la corriente llega al instante', alts: [
    { title: 'Como canicas en un tubo', text: 'Imagina un tubo lleno de canicas. Si empujas una por un extremo, sale otra casi al instante por el otro, aunque cada canica se mueva despacio. En un cable pasa igual: los electrones ya están ahí; la pila solo empuja la fila.', q: mcq('¿Por qué la luz se enciende al instante aunque los electrones se muevan despacio?', ['Porque el cable ya está lleno de electrones y el empuje se transmite por toda la fila', 'Porque los electrones viajan a la velocidad de la luz', 'Porque la pila lanza electrones muy rápidos', 'Porque la bombilla tiene electrones guardados'], 'Lo que viaja rápido es el empuje, no cada electrón.') },
    { title: 'La ola del estadio', text: 'En la ola de un estadio nadie corre: cada persona solo se levanta y se sienta, pero la ola da la vuelta en segundos. En un cable, cada electrón avanza milímetros por segundo, pero el empuje de la pila se transmite por todo el cable casi a la velocidad de la luz. Por eso la bombilla se enciende al momento.', q: mcq('¿Qué viaja rápido por el cable al cerrar el interruptor?', ['El empuje, que mueve a la vez a todos los electrones', 'Cada electrón, a la velocidad de la luz', 'Los protones', 'La energía de la bombilla hacia la pila'], 'Los electrones avanzan despacio; el empuje llega enseguida.') }
  ] },
  ba_convdir: { name: 'Sentido convencional de la corriente', alts: [
    { title: 'Sentido convencional', text: 'Por convenio, la corriente se dibuja saliendo del + y entrando por el −. Los electrones van al revés, pero eso no cambia ningún cálculo: todos los esquemas usan el sentido convencional.', q: mcq('En un esquema, la corriente se dibuja…', ['Del + al − por fuera de la pila', 'Del − al + por fuera de la pila', 'En ambos sentidos a la vez', 'Solo dentro de la pila'], 'Es el sentido convencional.') },
    { title: 'Un acuerdo antiguo', text: 'Cuando se definió la corriente aún no se conocían los electrones, y se eligió que fuera del + al −. Luego se vio que los electrones van al revés, pero el convenio se quedó: en esquemas, flechas y fórmulas, la corriente <b>sale por el polo +</b>, recorre el circuito y vuelve por el −.', q: mcq('¿Por qué polo sale la corriente convencional de una pila?', ['Por el +', 'Por el −', 'Por los dos a la vez', 'Depende del circuito'], 'Del + al − por fuera de la pila.') }
  ] },
  ba_vdiff: { name: 'La tensión es entre dos puntos', alts: [
    { title: 'Como un desnivel', text: 'La tensión es como un desnivel: no tiene sentido decir “cuánta altura” sin decir respecto a qué. Por eso el multímetro usa dos puntas, y por eso un pájaro con las dos patas en el mismo cable no nota nada. Cuando decimos “este punto está a 5 V” queremos decir “5 V respecto a masa”.', q: mcq('¿Por qué un voltímetro necesita dos puntas?', ['Porque mide la diferencia entre dos puntos', 'Por si una falla', 'Para que pase más corriente', 'Para medir más rápido'], 'La tensión siempre compara un punto con otro.') },
    { title: 'Resta las tensiones', text: 'Si conoces las tensiones de dos puntos respecto a masa, la tensión entre ellos es la <b>resta</b>: A a 9 V y B a 4 V → entre A y B hay 5 V. Masa es solo el punto que elegimos como 0 V, igual que el nivel del mar para las alturas.', q: mcq('A está a 12 V y B a 3,3 V respecto a masa. ¿Tensión entre A y B?', ['8,7 V', '15,3 V', '12 V', '3,3 V'], '12 − 3,3.') }
  ] },
  ba_cells: { name: 'Pilas en serie y sus tensiones', alts: [
    { title: 'En serie se suman', text: 'Unir pilas en serie (el + de una con el − de la siguiente) es apilar escalones: las tensiones se suman. Cuatro AA de 1,5 V dan 6 V. Si pones una del revés (+ con +), empuja en contra y se resta: dos de 1,5 V así dan 0 V.', q: mcq('Tres pilas de 1,5 V en serie, una de ellas del revés. ¿Tensión total?', ['1,5 V', '4,5 V', '3 V', '0 V'], '1,5 + 1,5 − 1,5.') },
    { title: 'Tensiones que conviene saber', text: 'Pila AA o AAA: 1,5 V. Pila cuadrada: 9 V (por dentro, seis celdas de 1,5 V en serie). Celda de litio: 3,7 V nominales (4,2 V llena). USB: 5 V. Casi todas las baterías son celdas en serie que se suman: dos de litio dan 7,4 V; seis de 1,5 V, 9 V.', q: mcq('Dos celdas de litio de 3,7 V en serie dan…', ['7,4 V', '3,7 V', '4,2 V', '1,85 V'], '3,7 + 3,7.') },
    { title: 'También con fuentes', text: 'Con una fuente de laboratorio doble pasa lo mismo: si unes el − de una salida con el + de la otra, entre los extremos tienes la suma. Y si tomas ese punto de unión como masa, tienes +V y −V respecto a él: así se alimentan muchos amplificadores operacionales con ±12 V.', q: mcq('Dos salidas de 12 V en serie, con el punto de unión como masa. ¿Qué tienes?', ['+12 V y −12 V respecto a masa', '+24 V en los dos extremos', '0 V', '+6 V y −6 V'], 'Entre extremos hay 24 V; respecto al centro, ±12 V.') }
  ] },
  ba_wqv: { name: 'Energía, carga y tensión', alts: [
    { title: 'Julios por culombio', text: 'Un voltio es un julio por culombio: cada culombio que atraviesa una pila de 9 V recibe 9 J. Para cualquier cantidad de carga: <b>W = Q · V</b>. 2 C por una pila de 1,5 V reciben 3 J.', q: mcq('¿Cuánta energía reciben 4 C al atravesar una pila de 9 V?', ['36 J', '2,25 J', '13 J', '0,44 J'], 'W = 4 × 9.') },
    { title: 'El electronvoltio', text: 'Para un solo electrón se usa el <b>electronvoltio</b> (eV): la energía que gana al cruzar 1 V. En un LED, cada electrón que cruza la unión puede soltar como mucho esa energía en forma de un fotón. Por eso un LED azul (unos 3 V) da fotones más energéticos que uno rojo (unos 1,8 V): más energía por carga exige más tensión.', q: mcq('¿Qué LED necesita más tensión, y por qué?', ['El azul: sus fotones llevan más energía', 'El rojo: su luz es más intensa', 'Los dos igual', 'Depende de la resistencia'], 'Más energía por fotón, más tensión por electrón.') }
  ] },
  ba_pcalc: { name: 'Calcular la potencia', alts: [
    { title: 'Julios cada segundo', text: 'La potencia es la energía por segundo, en vatios (1 W = 1 J/s). Si cada segundo pasan I culombios y cada uno recibe V julios, la potencia es <b>P = V · I</b>. 9 V y 0,1 A: 0,9 W, es decir, 0,9 julios cada segundo.', q: mcq('5 V y 200 mA. ¿Potencia?', ['1 W', '25 W', '0,04 W', '1000 W'], '5 × 0,2.') },
    { title: 'Tres fórmulas, elige por los datos', text: 'P = V · I es la base. Si tienes I y R: <b>P = I² · R</b>. Si tienes V y R: <b>P = V² / R</b>. Pasa antes todo a A, V y Ω. Ejemplo: 20 mA por 220 Ω → 0,02² × 220 = 0,088 W = 88 mW.', q: mcq('9 V sobre 1 kΩ. ¿Potencia?', ['81 mW', '9 mW', '9 W', '81 W'], '81 / 1000 = 0,081 W.') },
    { title: 'El cuadrado manda', text: 'En P = I² · R y en P = V² / R la corriente o la tensión van al cuadrado: el doble de corriente por la misma resistencia da <b>cuatro</b> veces más potencia, y el triple, nueve. Pasa lo mismo con el rizado en la ESR de un condensador: P = I² · ESR, con 2 A y 0,1 Ω → 0,4 W.', q: mcq('Por una resistencia pasa el triple de corriente. Su potencia…', ['Se multiplica por 9', 'Se triplica', 'No cambia', 'Se divide entre 3'], '3² = 9.') }
  ] },
  ba_rint: { name: 'Resistencia interna de una pila', alts: [
    { title: 'Una resistencia escondida', text: 'Una pila real es una pila ideal con una pequeña resistencia en serie dentro. Sin corriente no cae nada en ella y marca su tensión en vacío; cuando le pides corriente, parte de la tensión se queda dentro: <b>V = Vvacío − I · Rint</b>. En un cortocircuito, esa resistencia (más la de los cables) es lo único que limita la corriente.', q: mcq('Una pila de 9 V con 2 Ω internos entrega 0,5 A. ¿Qué tensión da?', ['8 V', '9 V', '10 V', '4,5 V'], '9 − 0,5 × 2.') },
    { title: 'Gastada = más resistencia', text: 'Al gastarse, la resistencia interna de una pila sube. Por eso una pila vieja puede marcar 9 V en vacío y caer a 7 V en cuanto la conectas a un motor: para comprobar una pila, mídela con carga. Y en un cortocircuito, la resistencia interna y la de los cables son lo único que frena la corriente: por eso la pila se calienta.', q: mcq('Una pila marca 1,5 V en vacío y 1,1 V con carga. ¿Por qué?', ['La corriente provoca caída en su resistencia interna', 'El multímetro falla', 'La carga genera tensión', 'La pila es de 1,1 V'], 'Parte de la tensión se queda dentro de la pila.') }
  ] },
  ba_circuit: { name: 'Abierto, cerrado y cortocircuito', alts: [
    { title: 'Un camino en bucle', text: 'La corriente necesita un camino de ida y vuelta a la pila. Si se corta en cualquier punto (<b>circuito abierto</b>), se para en todas partes: un interruptor abierto o un cable suelto apagan todo lo que está en serie. Si encuentra un atajo sin resistencia (<b>cortocircuito</b>), circula muchísima corriente; el <b>fusible</b> es un punto débil a propósito que se funde y abre el circuito.', q: mcq('Un LED en serie con un interruptor abierto…', ['Se apaga: el camino está cortado', 'Brilla más', 'Provoca un cortocircuito', 'Brilla a medias'], 'Cualquier corte en serie apaga todo.') },
    { title: 'El puente levadizo', text: 'Un interruptor no “manda” la electricidad: abre o cierra el camino, como un puente levadizo. Abierto = puente levantado: no pasa nadie. Un fusible es un puente que se rompe solo si pasa demasiado tráfico, para proteger lo demás.', q: mcq('¿Para qué sirve un fusible?', ['Para fundirse y abrir el circuito si pasa demasiada corriente', 'Para aumentar la corriente', 'Para guardar carga', 'Para medir la tensión'], 'Un punto débil a propósito.') }
  ] },
  ba_labpsu: { name: 'Fuente de laboratorio: CV y CC', alts: [
    { title: 'Dos mandos, dos modos', text: 'Fijas una tensión y un límite de corriente. Si la carga pide menos que el límite, la fuente da la tensión fijada (<b>CV</b>, tensión constante). Si pediría más, la fuente baja la tensión justo lo necesario para no pasar del límite (<b>CC</b>, corriente constante). Su amperímetro marca la corriente total que sale hacia tu circuito.', q: mcq('Fijas 5 V y 100 mA y conectas 10 Ω. ¿Qué pasa?', ['Entra en CC: da 100 mA y 1 V', 'Da 5 V y 500 mA', 'Da 5 V y 100 mA', 'Se apaga'], 'A 5 V pasarían 500 mA: limita a 100 mA y V = 0,1 × 10 = 1 V.') },
    { title: 'Un seguro contra errores', text: 'El límite de corriente es un seguro: ajústalo un poco por encima de lo que esperas que consuma el circuito. Si te equivocas al montar, la fuente solo da lo fijado y no se quema nada. Si nada más encender entra en CC y la tensión se hunde, algo consume de más (un corto o un componente al revés): apaga y revisa antes de subir el límite.', q: mcq('Esperas 30 mA, el límite está en 50 mA y la fuente entra en CC al encender. ¿Qué haces?', ['Apagar y buscar un corto o algo al revés', 'Subir el límite a 2 A', 'Nada, es normal', 'Cambiar de fuente'], 'El límite acaba de salvarte un componente.') },
    { title: 'Cómo prepararla', text: 'Rutina: salida desactivada; ajusta la tensión sin carga; cortocircuita los bornes y ajusta el límite; quita el corto, conecta el circuito y activa la salida mirando la corriente. Recuerda que el amperímetro de la fuente ve el total: para la corriente de una rama concreta, multímetro en serie.', q: mcq('¿Cómo ajustas el límite de corriente de la fuente?', ['Con los bornes cortocircuitados, mirando su amperímetro', 'Con el circuito conectado y la tensión al máximo', 'Midiendo con el multímetro en paralelo', 'No se puede ajustar'], 'En cortocircuito, la fuente da justo el límite.') }
  ] },
  ba_body: { name: 'Corriente por el cuerpo', alts: [
    { title: 'Ohm también vale para ti', text: 'Tu cuerpo es una resistencia: con la piel seca, de mano a mano, decenas o cientos de kΩ; mojada o con heridas, puede bajar a 1 kΩ. La corriente es <b>I = V / R</b>: 9 V / 100 kΩ = 0,09 mA (no la notas); 230 V / 1 kΩ = 230 mA (mortal).', q: mcq('Con la piel seca hay unos 50 kΩ. ¿Qué corriente pasaría con 12 V?', ['0,24 mA', '240 mA', '4,2 mA', '0,6 A'], '12 / 50 000 = 0,00024 A.') },
    { title: 'Qué corriente es peligrosa', text: 'Orientativamente: 1 mA apenas se nota; unos 10 mA contraen los músculos y pueden impedir soltar; unas decenas de mA cruzando el pecho pueden provocar fibrilación. Con baja tensión, tu resistencia te protege; con los 230 V de la red, no: pasan decenas o cientos de mA. Por eso la red no se toca sin formación.', q: mcq('¿Por qué es mortal la red de 230 V y no una pila de 9 V?', ['Con 230 V tu resistencia deja pasar decenas o cientos de mA', 'Porque la red tiene más amperios guardados', 'Porque la continua no hace daño', 'Porque la pila lleva fusible'], 'La tensión empuja, tu resistencia limita y la corriente hace el daño.') }
  ] },
  ba_shockpath: { name: 'Camino de la corriente y diferencial', alts: [
    { title: 'Lo que cruza el pecho', text: 'El daño depende de por dónde pasa la corriente: de mano a mano o de mano a pie cruza el pecho y puede alterar el ritmo del corazón. Por eso, cerca de algo peligroso, se trabaja con una sola mano. Y el <b>diferencial</b> de casa corta en milisegundos si detecta que una parte de la corriente se escapa por otro camino, por ejemplo a través de ti.', q: mcq('¿Qué detecta el diferencial?', ['Que la corriente que va no es igual a la que vuelve: hay una fuga', 'Que la tensión es demasiado alta', 'Que un aparato consume mucho', 'Que hace calor'], 'Una fuga de unos 30 mA basta para que corte.') },
    { title: 'Ida y vuelta', text: 'La corriente de un aparato va por un cable y vuelve por el otro. El diferencial compara las dos: si no coinciden, algo (quizá una persona) está llevando corriente a tierra, y corta. El magnetotérmico, en cambio, protege los cables de un exceso de corriente, no a las personas. Por la misma idea de “camino”, una mano siempre lejos del circuito.', q: mcq('¿Por qué se trabaja con una sola mano cerca de alta tensión?', ['Para que la corriente no pueda ir de una mano a la otra cruzando el pecho', 'Para ir más rápido', 'Porque la otra sujeta la linterna', 'Por costumbre'], 'El recorrido más peligroso pasa por el corazón.') }
  ] },
  ba_stored: { name: 'Energía que queda guardada', alts: [
    { title: 'Desenchufado no es seguro', text: 'Una batería de litio en cortocircuito suelta decenas de amperios y puede arder; un condensador grande de una fuente o de un flash puede guardar cientos de voltios mucho después de desenchufar. Antes de tocar: desconecta, espera, mide, descarga con una resistencia si hace falta y vuelve a medir.', q: mcq('Desenchufas una fuente para repararla. ¿Qué haces antes de tocar dentro?', ['Medir y descargar los condensadores grandes con una resistencia', 'Nada: ya está desenchufada', 'Cortocircuitarlos con un destornillador', 'Esperar dos segundos'], 'Pueden guardar tensión peligrosa durante mucho rato.') },
    { title: 'Cuántos julios', text: 'Un condensador guarda E = ½ · C · V²: uno de 470 µF a 400 V, casi 38 J, y el de un flash a 300 V, varios julios que salen de golpe. Una batería no necesita estar enchufada a nada: si unas llaves, monedas o una pulsera unen sus polos, la cortocircuitan. Llévalas con los polos tapados.', q: mcq('Llevas una celda 18650 suelta en el bolsillo con monedas. ¿Riesgo?', ['Un cortocircuito: calor e incluso fuego', 'Ninguno: solo son 3,7 V', 'Que se descargue un poco', 'Ninguno si está cargada'], 'Las monedas pueden unir sus polos.') }
  ] },
  /* ba:m1 fin */
  ba_ohmprop: { name: 'Ley de Ohm: proporciones', alts: [
    { title: 'Juntas o al revés', text: 'Con la resistencia fija, tensión y corriente van juntas: el triple de tensión, el triple de corriente. Con la tensión fija, resistencia y corriente van al revés: la mitad de resistencia, el doble de corriente. Si quieres más corriente sin tocar la pila, baja la resistencia.', tune: { viz: 'ohm', params: { V: { label: 'Pila', val: 4, min: 1, max: 12, step: 1, unit: 'V', dec: 0 }, R: { label: 'Resistencia', val: 1000, fmt: 'R', min: 100, max: 10000 } } }, q: mcq('Con 1 kΩ circulan 3 mA. ¿Cuánto circula con 2 kΩ y la misma pila?', ['1,5 mA', '6 mA', '3 mA', '0,3 mA'], 'Doble resistencia, mitad de corriente.') },
    { title: 'Presión y manguera', text: 'La pila es la presión y la resistencia, lo estrecha que es la manguera. Más presión con la misma manguera: más caudal, en la misma proporción. Una manguera que frena el doble (el doble de resistencia) con la misma presión: la mitad de caudal.', q: mcq('Misma resistencia y la tensión pasa de 3 V a 12 V. La corriente…', ['Se multiplica por 4', 'Se divide entre 4', 'No cambia', 'Se multiplica por 16'], 'Cuatro veces más tensión, cuatro veces más corriente.') }
  ] },
  ba_ohm: { name: 'Calcular con la ley de Ohm', alts: [
    { title: 'El triángulo', text: 'Dibuja un triángulo con V arriba e I y R abajo. Tapa la magnitud que buscas: lo que queda te dice la operación. Tapando V queda I × R; tapando I queda V / R; tapando R queda V / I.', svg: '<svg viewBox="0 0 200 150" class="viz"><path d="M100 15L185 135H15Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="M45 85H155M100 85V135" stroke="currentColor" stroke-width="3"/><text x="100" y="72" text-anchor="middle" font-size="30" font-weight="800" fill="currentColor">V</text><text x="70" y="122" text-anchor="middle" font-size="26" font-weight="800" fill="currentColor">I</text><text x="130" y="122" text-anchor="middle" font-size="26" font-weight="800" fill="currentColor">R</text></svg>', q: mcq('Tapando la R en el triángulo, ¿qué fórmula queda?', ['R = V / I', 'R = V × I', 'R = I / V', 'R = V − I'], 'V arriba, I abajo: V entre I.') },
    { title: 'Paso a paso con unidades', text: 'El error más común es mezclar prefijos. Receta: 1) pasa todo a V, A y Ω; 2) aplica la fórmula; 3) vuelve al prefijo cómodo. Ejemplo: 9 V entre 4,7 kΩ → 9 / 4700 = 0,0019 A = 1,9 mA.', q: mcq('5 V entre 2,2 kΩ. ¿Corriente?', ['2,27 mA', '2,27 A', '0,44 mA', '11 mA'], '5 / 2200 = 0,00227 A = 2,27 mA.') },
    { title: 'El error de los mil', text: 'Si te sale una corriente de amperios en un circuito con LEDs, o de microamperios donde esperabas miliamperios, casi siempre es un prefijo: usaste 1 en vez de 1000 Ω, o mA como A. Comprobación rápida: voltios entre kiloohmios dan miliamperios (5 V / 1 kΩ = 5 mA).', q: mcq('9 V entre 470 Ω. Te sale 19 A. ¿Cuál es el valor correcto?', ['Unos 19 mA', 'Unos 19 µA', 'Unos 4,2 A', '19 A'], '9 / 470 = 0,019 A = 19 mA.') }
  ] },
  ba_ivgraph: { name: 'Gráficas tensión–corriente', alts: [
    { title: 'La pendiente es 1/R', text: 'Con V en horizontal e I en vertical, una resistencia da una recta por el origen. Cuanto más inclinada, más corriente con la misma tensión: <b>menos</b> resistencia. En cualquier punto de la recta, R = V / I: si pasa por (4 V, 2 mA), R = 4 / 0,002 = 2000 Ω. Si en vez de una recta sale una curva, como en un LED, el componente no es lineal.', q: mcq('Una recta pasa por (6 V, 3 mA). ¿Resistencia?', ['2 kΩ', '18 Ω', '0,5 kΩ', '2 Ω'], '6 / 0,003 = 2000 Ω.') },
    { title: 'Recta o curva', text: 'Si un componente cumple la ley de Ohm, su gráfica es una recta: es <b>lineal</b> y su resistencia no cambia. Un LED o un diodo dan una curva: casi nada de corriente hasta un codo y luego una subida brusca; su “resistencia” cambia con la tensión. Entre dos rectas, la más inclinada es la de menos resistencia, y R = V / I en cualquier punto.', q: mcq('Dos rectas por el origen: la A muy inclinada y la B casi plana. ¿Cuál tiene más resistencia?', ['La B', 'La A', 'Las dos igual', 'No se puede saber'], 'Plana: poca corriente aunque subas mucho la tensión.') }
  ] },
  ba_prating: { name: 'Elegir la potencia de una resistencia', alts: [
    { title: 'Calcula y deja margen', text: 'Calcula lo que disipa (P = V² / R o P = I² · R) y elige una resistencia que aguante <b>al menos el doble</b>. Las normales son de ¼ W (250 mW). 9 V sobre 330 Ω: 81 / 330 ≈ 0,25 W: justo en el límite, mejor una de ½ W.', q: mcq('12 V directamente sobre 2,2 kΩ. ¿Vale una de ¼ W?', ['Sí: disipa unos 65 mW', 'No: disipa 5,5 W', 'No: disipa 0,65 W', 'Sí: disipa 5 mW'], '144 / 2200 ≈ 0,065 W.') },
    { title: 'El calor busca salida', text: 'Toda la potencia de una resistencia se convierte en calor. Si es más de lo que su tamaño puede evacuar, se calienta, cambia de valor y acaba quemada. La potencia nominal (¼ W, ½ W, 1 W…) es ese máximo: elige la siguiente que duplique lo calculado. Una resistencia de LED con 70 mW va sobrada con ¼ W.', q: mcq('Una resistencia disipará 200 mW. ¿Cuál eliges?', ['½ W', '¼ W', '1/8 W', '1/16 W'], '¼ W sería justo: elige al menos el doble.') }
  ] },
  ba_kwh: { name: 'Energía = potencia × tiempo (kWh)', alts: [
    { title: 'Vatios por horas', text: 'La energía es potencia por tiempo. Un aparato de 100 W durante 8 h gasta 800 Wh = 0,8 kWh. La factura cobra por kWh: a 0,20 €/kWh, 0,8 × 0,20 = <b>0,16 €</b>. Pasa los W a kW (÷1000) antes de multiplicar por el precio.', q: mcq('Un aparato de 2000 W funciona 2 h, con la luz a 0,15 €/kWh. ¿Coste?', ['0,60 €', '600 €', '0,30 €', '6 €'], '2 kW × 2 h = 4 kWh; 4 × 0,15.') },
    { title: 'Potencia no es energía', text: 'Un secador de 2000 W gasta mucho cada segundo, pero si solo funciona 3 minutos (0,05 h) consume 100 Wh: lo mismo que un LED de 10 W encendido 10 horas. Lo que pagas es la energía (W × h), no la potencia.', q: mcq('¿Qué gasta más: 1000 W durante 6 minutos o 25 W durante 4 horas?', ['Lo mismo: 100 Wh cada uno', 'El de 1000 W', 'El de 25 W', 'No se puede saber'], '1000 × 0,1 = 100 Wh; 25 × 4 = 100 Wh.') }
  ] },
  ba_nodal: { name: 'Análisis nodal', alts: [
    { title: 'Corriente entre dos nudos', text: 'La corriente por una resistencia que une dos nudos es <b>(Va − Vb) / R</b> y va del nudo de más tensión al de menos. Si los dos nudos están a la misma tensión, no pasa corriente, aunque detrás haya una fuente. Con esto y “lo que entra en un nudo = lo que sale” se resuelve cualquier red de resistencias.', q: mcq('Entre un nudo a 9 V y otro a 5 V hay 1 kΩ. ¿Corriente?', ['4 mA, del de 9 V al de 5 V', '14 mA', '4 mA, del de 5 V al de 9 V', '9 mA'], '(9 − 5) / 1000.') },
    { title: 'Lo que entra = lo que sale', text: 'Método: elige masa, llama VA, VB… a cada nudo de tensión desconocida y escribe en cada uno que lo que entra es igual a lo que sale, con (V − VA) / R en cada rama. Una ecuación por nudo desconocido. Ejemplo: 12 V y 6 V llegan a A por 1 kΩ cada una y de A sale 1 kΩ a masa: (12 − VA) + (6 − VA) = VA → <b>VA = 6 V</b>.', q: mcq('Un circuito tiene 5 nudos y uno es masa. ¿Cuántas ecuaciones de nudo, como mucho?', ['4', '5', '1', '10'], 'Una por cada nudo de tensión desconocida.') },
    { title: 'Lo que hacen los simuladores', text: 'Los simuladores tipo SPICE no adivinan: escriben estas mismas ecuaciones de nudos, para miles de nudos, y las resuelven con matrices. Haz la cuenta a mano en un caso sencillo: nudo A unido a 10 V por 1 kΩ y a masa por 1 kΩ → (10 − VA) / 1k = VA / 1k → VA = 5 V. Con superposición debe salir lo mismo.', q: mcq('Nudo A unido a 12 V por 2 kΩ y a masa por 1 kΩ. ¿VA?', ['4 V', '6 V', '8 V', '12 V'], '(12 − VA)/2 = VA/1 → VA = 4 V.') }
  ] },
  ba_div: { name: 'Calcular un divisor de tensión', alts: [
    { title: 'Una escalera', text: 'Imagina que la pila es una escalera de 9 escalones y las resistencias reparten los escalones según su tamaño. Con 2 kΩ arriba y 1 kΩ abajo, la de abajo se lleva 1 de cada 3 escalones: 3 V. La salida se toma en la unión entre R1 y R2, respecto a masa.', q: mcq('12 V, R1 = 3 kΩ arriba y R2 = 1 kΩ abajo. ¿Vsal?', ['3 V', '9 V', '4 V', '6 V'], 'R2 es 1/4 del total: 12 / 4 = 3 V.') },
    { title: 'La fórmula', text: '<b>Vsal = Vent × R2 / (R1 + R2)</b>, con R2 la resistencia de abajo (la que va a masa) y la salida en el punto entre las dos. 9 V con R1 = 10 kΩ y R2 = 4,7 kΩ: 9 × 4,7 / 14,7 ≈ 2,88 V. Si R1 = R2, la mitad; un potenciómetro con el cursor en el centro hace lo mismo.', q: mcq('5 V con R1 = 1 kΩ arriba y R2 = 4 kΩ abajo. ¿Vsal?', ['4 V', '1 V', '1,25 V', '5 V'], '5 × 4 / 5.') },
    { title: 'Estima antes', text: 'La tensión se reparte en proporción a las resistencias: la de abajo se lleva su fracción del total. Si R2 es mayor que R1, la salida pasa de la mitad; si es menor, se queda por debajo; si son iguales, justo la mitad. Para 3,3 V desde 5 V, R2 tiene que ser unas dos veces R1.', q: mcq('R1 = 10 kΩ arriba y R2 = 20 kΩ abajo. Sin calcular, la salida…', ['Es más de la mitad de la entrada', 'Es menos de la mitad', 'Es la mitad', 'Es cero'], 'R2 es 2/3 del total.') }
  ] },
  ba_superpos: { name: 'Superposición', alts: [
    { title: 'De una en una', text: 'Con varias fuentes, calcula el efecto de cada una con las demás “apagadas” (pila → cable; fuente de corriente → hueco abierto) y suma los resultados. Solo vale con componentes <b>lineales</b> (no con LEDs ni transistores) y solo para tensiones y corrientes: las potencias no se suman así, porque van al cuadrado.', q: mcq('Al aplicar superposición, ¿qué haces con una pila que no estás analizando?', ['La sustituyes por un cable', 'La quitas y dejas el hueco abierto', 'La duplicas', 'La das la vuelta'], 'Una pila apagada da 0 V: es un cable.') },
    { title: 'Apagar fuentes', text: 'Para analizar una fuente sola, apaga las demás: una <b>pila</b> apagada da 0 V, así que se cambia por un <b>cable</b>; una <b>fuente de corriente</b> apagada da 0 A, así que se cambia por un <b>hueco abierto</b>. Calcula cada caso y suma tensiones o corrientes; la potencia, al final, con el total. Con un diodo o un LED no funciona.', q: mcq('¿Qué dejas en el lugar de una fuente de corriente “apagada”?', ['Un circuito abierto', 'Un cable', 'Una resistencia de 1 kΩ', 'Una pila de 0 V'], 'Una fuente de 0 A no deja pasar nada.') },
    { title: 'Con números', text: 'Dos pilas, 12 V y 6 V, llegan a un nudo por 1 kΩ cada una, y del nudo sale 1 kΩ a masa. Solo la de 12 V (la otra, un cable): 12 × 500 / 1500 = 4 V. Solo la de 6 V: 2 V. Total: 6 V, lo mismo que con el análisis nodal. Si hubiera un LED, no valdría: no es lineal.', q: mcq('Una fuente sola produce 3 V en un nudo y la otra, sola, 1,5 V. ¿Tensión con las dos?', ['4,5 V', '1,5 V', '3 V', 'No se puede sumar'], 'En un circuito lineal, los efectos se suman.') }
  ] },
  ba_norton: { name: 'Norton y la conversión Thévenin ↔ Norton', alts: [
    { title: 'La misma caja, otra foto', text: 'Norton resume la red como una fuente de corriente <b>IN</b> con <b>RN</b> en paralelo. Se pasa de una a otra así: RN = Rth; IN = Vth / Rth (la corriente de cortocircuito); y al revés, Vth = IN · RN (la tensión en vacío). Desde fuera no se distinguen.', q: mcq('Vth = 12 V y Rth = 4 kΩ. ¿Equivalente Norton?', ['3 mA con 4 kΩ en paralelo', '3 mA con 4 kΩ en serie', '48 mA con 4 kΩ en paralelo', '12 mA con 1 kΩ en paralelo'], 'IN = 12 / 4000.') },
    { title: 'La fuente de corriente', text: 'Una fuente de corriente ideal da siempre la misma corriente y ajusta su tensión a lo que haga falta (su resistencia interna sería infinita). Es el modelo natural de cosas como un fotodiodo o un transistor en zona activa. Sin carga, toda IN pasa por RN: Vth = IN · RN.', q: mcq('Fuente Norton de 2 mA con 5 kΩ en paralelo. ¿Tensión en vacío?', ['10 V', '2,5 V', '0,4 V', '2 V'], '0,002 × 5000.') }
  ] },
  ba_maxpow: { name: 'Máxima transferencia de potencia', alts: [
    { title: 'En medio está el máximo', text: 'Con una fuente de resistencia interna Rth, una carga muy pequeña recibe mucha corriente pero poca tensión, y una muy grande, mucha tensión pero poca corriente. El máximo de potencia en la carga está en <b>RL = Rth</b>: Pmax = V² / (4 · Rth).', q: mcq('Fuente de 12 V con 6 Ω internos. ¿Potencia máxima en una carga?', ['6 W', '24 W', '12 W', '2 W'], '144 / 24.') },
    { title: 'Adaptar o no adaptar', text: 'Con RL = Rth la mitad de la potencia se queda dentro de la fuente: rendimiento del 50 %. Se busca con señales débiles y valiosas (antenas de 50 Ω, sensores). Para alimentar cosas se hace lo contrario: Rth mucho menor que RL. Un amplificador de audio tiene Rth muy baja y una carga mínima: con un altavoz de menos ohmios entrega más corriente y puede calentarse.', q: mcq('¿Por qué no se alimenta un motor con RL = Rth de la batería?', ['Se perdería la mitad de la energía dentro de la batería', 'Porque el motor no giraría', 'Porque es ilegal', 'Porque daría el doble de tensión'], 'Para alimentar interesa el rendimiento.') },
    { title: 'Con números', text: 'Fuente de 10 V con Rth = 10 Ω. Con RL = 10 Ω: I = 0,5 A y P = 0,25 × 10 = 2,5 W. Con RL = 40 Ω: I = 0,2 A y P = 1,6 W. Con RL = 2,5 Ω: I = 0,8 A y P = 1,6 W. Por los dos lados baja: el pico está en RL = Rth.', q: mcq('Fuente de 6 V con Rth = 3 Ω. ¿Con qué carga entrega más potencia?', ['3 Ω', '1 Ω', '30 Ω', '0 Ω'], 'RL = Rth.') }
  ] },
  ba_bridge: { name: 'Puente de Wheatstone', alts: [
    { title: 'Dos divisores frente a frente', text: 'Un puente son dos divisores alimentados por la misma fuente. Si los dos dan la misma tensión (mismas proporciones arriba y abajo), entre sus puntos medios hay 0 V: está equilibrado. 1 kΩ/1 kΩ y 2 kΩ/2 kΩ dan los dos la mitad: 0 V entre ellos. Si un sensor cambia, aparece una pequeña tensión.', q: mcq('9 V: a la izquierda 1 kΩ arriba y 2 kΩ abajo; a la derecha 2 kΩ arriba y 4 kΩ abajo. ¿Tensión entre puntos medios?', ['0 V', '3 V', '6 V', '9 V'], 'Los dos dan 6 V.') },
    { title: 'Medir cerca de cero', text: 'Si un sensor de un divisor cambia un 0,1 %, la salida pasa de 2,500 V a unos 2,501 V: difícil de ver encima de 2,5 V. En un puente equilibrado, la salida pasa de 0 a algo más de 1 mV, y ese milivoltio se puede amplificar sin arrastrar los 2,5 V. Por eso las galgas y otros sensores de cambios pequeños van en puente.', q: mcq('¿Por qué se usa un puente con sensores que cambian muy poco?', ['Porque la salida parte de 0 V y el pequeño cambio se puede amplificar', 'Porque consume menos', 'Porque no necesita alimentación', 'Porque mide corriente'], 'Medir alrededor de cero es más fácil.') }
  ] },
  ba_symbols: { name: 'Símbolos de esquema', alts: [
    { title: 'Dibujos que se explican solos', text: 'Muchos símbolos dibujan lo que hacen: el LED es un diodo con flechitas que salen (emite luz); la LDR, una resistencia con flechas que entran (recibe luz); el potenciómetro, una resistencia con una flecha que la toca (el cursor). En la pila, la raya larga es el + y la corta el −.', q: mcq('Un diodo con flechas que salen hacia fuera es…', ['Un LED', 'Un fotodiodo', 'Un zener', 'Una resistencia'], 'Las flechas hacia fuera indican que emite luz.') },
    { title: 'Fíjate en los detalles', text: 'Pequeños detalles cambian el componente: el condensador con una placa curva o un + es <b>electrolítico</b> y tiene polaridad; el diodo con la barra doblada es un <b>zener</b>; el interruptor tiene una palanca, y el pulsador, un botón que une dos contactos. La masa (GND) son rayas cada vez más cortas, y el NPN lleva la flecha del emisor hacia fuera.', q: mcq('¿Qué indica el + junto a un condensador en un esquema?', ['Que es polarizado (electrolítico)', 'Que es muy grande', 'Que es variable', 'Que va siempre a +5 V'], 'Tiene una pata positiva y otra negativa.') }
  ] },
  ba_bbnodes: { name: 'Del esquema a la protoboard', alts: [
    { title: 'Un nudo, una columna', text: 'Cada <b>nudo</b> del esquema (cada punto donde se unen patas) será una columna de la protoboard. Numera los nudos en el esquema, asigna una columna a cada uno y pincha ahí todas las patas de ese nudo. La linterna (pila, interruptor, resistencia y LED en bucle) tiene 4 nudos.', q: mcq('Una pata de la resistencia y el ánodo del LED comparten nudo. ¿Dónde los pinchas?', ['En la misma columna', 'En columnas contiguas', 'En la fila de +', 'Da igual'], 'Mismo nudo = misma columna.') },
    { title: 'Cuenta y monta con calma', text: 'Para contar nudos, recorre el circuito y cuenta los puntos de unión entre componentes: n componentes en un solo bucle tienen n nudos. Monta siempre sin alimentación, siguiendo los nudos; revisa cada uno contra el esquema y solo entonces conecta la pila y mide.', q: mcq('Pila, resistencia y LED en serie (tres componentes en bucle). ¿Cuántos nudos?', ['3', '2', '6', '1'], 'Uno entre cada par de componentes vecinos.') }
  ] },
  /* ba:m3 fin */
  ba_period: { name: 'Periodo y frecuencia', alts: [
    { title: 'T = 1 / f', text: 'El periodo T es lo que dura un ciclo y la frecuencia f, cuántos ciclos caben en un segundo: <b>T = 1 / f</b>. La red europea va a 50 Hz: cada ciclo dura 1 / 50 = 0,02 s = <b>20 ms</b>. Para tenerlo en milisegundos: T (ms) = 1000 / f (Hz).', q: mcq('Una señal de 500 Hz. ¿Periodo?', ['2 ms', '0,5 ms', '500 ms', '20 ms'], '1000 / 500.') },
    { title: 'Cuántos caben en un segundo', text: 'Si algo se repite 1000 veces por segundo (1 kHz), cada repetición dura una milésima: 1 ms. Si se repite 2 veces, medio segundo. Más frecuencia, periodo más corto, en la misma proporción. La red de Europa hace 50 ciclos por segundo; la de América, 60.', q: mcq('Un periodo de 4 ms. ¿Frecuencia?', ['250 Hz', '4 Hz', '4000 Hz', '25 Hz'], '1 / 0,004 s.') }
  ] },
  ba_coupling: { name: 'Acoplo AC y DC del osciloscopio', alts: [
    { title: 'Quitar la continua', text: 'En <b>DC</b> ves la señal entera, continua incluida. En <b>AC</b> el osciloscopio pone un condensador en serie que quita la continua: solo ves lo que varía. Así puedes ver 50 mV de rizado sobre 5 V con pocos mV/div sin que la traza se salga. Pero ese condensador también se come lo muy lento.', q: mcq('Quieres ver el pequeño rizado de una fuente de 12 V. ¿Qué acoplo?', ['AC, con pocos mV/div', 'DC con 5 V/div', 'Da igual', 'Ninguno'], 'AC quita los 12 V fijos.') },
    { title: 'El acoplo AC es un paso alto', text: 'El condensador de acoplo, con la resistencia de entrada, forma un filtro paso alto de unos pocos hercios. Las señales lentas no pasan bien: una cuadrada de 1 Hz se ve con las partes planas cayendo hacia cero. Usa AC para ver un rizado pequeño sobre mucha continua, y DC para todo lo lento.', q: mcq('Con acoplo AC, una cuadrada de 0,5 Hz se ve…', ['Deformada: las partes planas caen hacia cero', 'Perfecta', 'Invertida', 'Más rápida'], 'El paso alto no deja pasar lo muy lento.') }
  ] },
  ba_probe: { name: 'Sondas ×1 y ×10', alts: [
    { title: 'La sonda también cuenta', text: 'Una sonda ×10 divide la señal entre 10 y carga mucho menos el circuito (unos 10 MΩ y 10–15 pF, frente a 1 MΩ y del orden de 100 pF en ×1). El osciloscopio tiene que saberlo: con el canal en ×1 y la sonda en ×10, todo marcará diez veces menos. En ×1, esa capacidad grande forma un RC con un punto de alta impedancia y los flancos salen lentos.', q: mcq('Esperas 5 V y el osciloscopio marca 0,5 V. Usas una sonda ×10. ¿Qué sospechas primero?', ['Que el canal está configurado como ×1', 'Que la señal está rota', 'Que el disparo está mal', 'Que el acoplo está en DC'], 'Revisa el factor de sonda del canal.') },
    { title: 'Dividir para molestar menos', text: 'La sonda ×10 lleva 9 MΩ en serie que, con el 1 MΩ de la entrada, dividen entre 10. Pierdes señal, pero cargas menos el circuito. El canal, configurado en ×10, multiplica por 10 al mostrar: si la pantalla marca 3 V, a la entrada del aparato llegan 0,3 V.', q: mcq('Sonda ×10, canal en ×10, la pantalla marca 2 V. ¿Qué llega a la entrada del osciloscopio?', ['0,2 V', '20 V', '2 V', '0,02 V'], 'La sonda divide; el canal lo compensa en pantalla.') },
    { title: 'Compensar la sonda', text: 'La sonda ×10 (que divide entre 10 y carga poco) tiene un condensador ajustable que debe equilibrar la capacidad de la entrada. Con la cuadrada de prueba del osciloscopio: esquinas con picos hacia fuera = sobrecompensada; esquinas redondeadas = subcompensada; cuadrada plana = bien. Mal compensada falsea amplitudes y flancos.', q: mcq('Al compensar, la cuadrada sale con las esquinas redondeadas. ¿Diagnóstico?', ['Subcompensada', 'Sobrecompensada', 'Bien compensada', 'Sonda en ×1'], 'Le falta capacidad de compensación.') }
  ] },
  ba_rise: { name: 'Tiempo de subida', alts: [
    { title: 'Del 10 % al 90 %', text: 'El tiempo de subida (tr) es lo que tarda un flanco en ir del 10 % al 90 % de su valor final. En un RC vale <b>tr ≈ 2,2 · R · C</b> (2,2 veces τ): con 10 kΩ y 0,1 µF, τ = 1 ms y tr ≈ 2,2 ms. Para un aparato con ancho de banda BW, tr ≈ 0,35 / BW.', q: mcq('Un RC con 1 kΩ y 1 µF. ¿Tiempo de subida?', ['2,2 ms', '1 ms', '0,35 ms', '22 ms'], 'τ = 1 ms; tr ≈ 2,2τ.') },
    { title: 'El ancho de banda limita', text: 'Todo sistema con un ancho de banda BW se comporta como un RC: no puede subir más rápido que <b>tr ≈ 0,35 / BW</b>. Un osciloscopio de 100 MHz tiene unos 3,5 ns propios: un flanco más rápido lo verá más lento de lo que es. Para un RC, 2,2 · RC y 0,35 / BW dan lo mismo.', q: mcq('Un osciloscopio de 50 MHz. ¿Tiempo de subida propio aproximado?', ['7 ns', '0,7 ns', '70 ns', '17,5 ns'], '0,35 / 50 MHz = 7 ns.') }
  ] },
  ba_polarity: { name: 'Polaridad del electrolítico', alts: [
    { title: 'La franja marca el −', text: 'Los electrolíticos tienen polaridad: la pata <b>corta</b> y el lado de la <b>franja</b> (con signos −) son el negativo. En el esquema se dibujan con una placa curva o un +. Conectados al revés pueden calentarse, hincharse e incluso reventar.', q: mcq('¿Cómo reconoces la pata negativa de un electrolítico?', ['Es la corta, del lado de la franja', 'Es la larga', 'Es la que tiene un +', 'No tiene polaridad'], 'La franja con signos − marca el negativo.') },
    { title: 'Por qué importa', text: 'El aislante de un electrolítico es una capa finísima de óxido que solo se mantiene con la tensión en el sentido correcto. Al revés esa capa se destruye, pasa corriente, se calienta y los gases pueden hacerlo reventar. Por eso el + del esquema (o la placa curva) y la franja − del componente importan.', q: mcq('En un circuito, el + del electrolítico va hacia…', ['El punto de mayor tensión', 'Masa, siempre', 'Donde quieras', 'El punto de menor tensión'], 'Positivo con positivo.') }
  ] },
  ba_capdc: { name: 'El condensador en continua', alts: [
    { title: 'Un depósito pequeño', text: 'Un condensador guarda carga entre dos placas separadas por un aislante. Se llena y se vacía muy rápido, y en continua, una vez lleno, no deja pasar corriente. Su capacidad (µF) es el tamaño del depósito.', q: mcq('En continua y ya cargado, un condensador se comporta como…', ['Un circuito abierto', 'Un cable', 'Una pila infinita', 'Una resistencia de 0 Ω'], 'Bloquea la continua.') },
    { title: 'Corriente solo mientras cambia', text: 'Por un condensador solo pasa corriente mientras su tensión cambia: al conectarlo se carga y, cuando llega a la tensión de la pila, la corriente se para. En continua y ya cargado es un <b>circuito abierto</b>.', q: mcq('Un condensador cargado en un circuito de continua. ¿Corriente?', ['Prácticamente ninguna', 'La máxima', 'La misma que una resistencia', 'Alterna'], 'Sin cambios de tensión no hay corriente.') }
  ] },
  ba_capcomb: { name: 'Condensadores en paralelo y en serie', alts: [
    { title: 'Al revés que las resistencias', text: 'En <b>paralelo</b> las capacidades se <b>suman</b> (es como más superficie de placa): 47 µF + 22 µF = 69 µF. En <b>serie</b> se combinan como resistencias en paralelo: 1/C = 1/C1 + 1/C2; dos iguales, la mitad. Justo al revés que las resistencias.', q: mcq('22 µF y 47 µF en paralelo. ¿Total?', ['69 µF', '15 µF', '47 µF', '1034 µF'], 'En paralelo se suman.') },
    { title: 'Serie: menos capacidad, más tensión', text: 'Dos condensadores en serie es como separar más las placas: la capacidad baja (dos de 10 µF dan 5 µF; 22 y 47 µF, producto partido por suma, unos 15 µF), pero la tensión se reparte entre los dos y el conjunto aguanta más. En paralelo, en cambio, se suman.', q: mcq('Dos de 100 µF en serie. ¿Capacidad total?', ['50 µF', '200 µF', '100 µF', '10 000 µF'], 'Dos iguales en serie: la mitad.') }
  ] },
  ba_caplife: { name: 'Vida de un electrolítico', alts: [
    { title: '×2 cada 10 °C menos', text: 'La vida de un electrolítico se da a su temperatura máxima (por ejemplo, 2000 h a 105 °C). Regla aproximada: se duplica por cada 10 °C menos. A 85 °C (dos saltos): 2000 × 2² = 8000 h; a 65 °C (cuatro saltos): 2000 × 2⁴ = 32 000 h.', q: mcq('5000 h a 105 °C. ¿Vida aproximada a 85 °C?', ['20 000 h', '10 000 h', '2500 h', '50 000 h'], 'Dos saltos de 10 °C: × 4.') },
    { title: 'El calor lo seca', text: 'El electrolito líquido se evapora poco a poco, y más deprisa cuanto más caliente está: un electrolítico junto a un disipador dura mucho menos. Cuenta los saltos de 10 °C entre la temperatura de la hoja de datos y la real, y duplica una vez por salto.', q: mcq('1000 h a 105 °C, trabajando a 75 °C. ¿Vida?', ['8000 h', '3000 h', '2000 h', '30 000 h'], 'Tres saltos: × 8.') }
  ] },
  ba_exp: { name: 'La función e^(−x)', alts: [
    { title: 'Valores para recordar', text: 'e ≈ 2,718. e^(−1) ≈ 0,37, e^(−2) ≈ 0,14, e^(−3) ≈ 0,05, e^(−5) ≈ 0,007. Cada vez que el exponente baja 1, el valor se divide entre 2,718.', q: mcq('¿Cuánto vale aproximadamente e^(−2)?', ['0,14', '0,37', '0,05', '−2,7'], '0,37 / 2,718 ≈ 0,14.') },
    { title: 'Lo que queda', text: 'e^(−t/τ) es la fracción que <b>queda</b> en una descarga (o la que <b>falta</b> en una carga) tras un tiempo t. Por eso tras 1τ falta el 37 % y tras 3τ falta un 5 %. Si te preguntan e^(−3), piensa “lo que queda tras 3τ”: 0,05.', q: mcq('¿Cuánto vale aproximadamente e^(−1)?', ['0,37', '0,63', '2,72', '0,5'], '1 / 2,718.') }
  ] },
  ba_taurl: { name: 'Constante de tiempo L / R', alts: [
    { title: 'Con números: τ = L / R', text: 'Al conectar una bobina y una resistencia a una pila, la corriente sube como la tensión de un condensador: 63 % tras τ y casi toda tras 5τ. Pero aquí <b>τ = L / R</b>: más resistencia, más rápido. Corriente final: I = V / R.', q: mcq('100 mH con 100 Ω. ¿τ?', ['1 ms', '10 s', '10 ms', '0,1 ms'], '0,1 / 100 = 0,001 s.') },
    { title: 'Al revés que en RC', text: 'En RC, τ = R · C: más resistencia, más lento. En RL, <b>τ = L / R</b>: más resistencia, más <b>rápido</b>. 10 mH con 10 Ω → 1 ms; 1 mH con 10 Ω → 0,1 ms = 100 µs. Pasa L a henrios antes de dividir.', q: mcq('10 mH con 1 kΩ en serie. ¿τ?', ['10 µs', '10 s', '10 ms', '0,1 µs'], '0,01 / 1000 = 0,00001 s.') }
  ] },
  ba_coilsat: { name: 'Saturación de una bobina', alts: [
    { title: 'El núcleo se llena', text: 'Un núcleo de ferrita solo admite cierto campo magnético. Por encima de la corriente de saturación (Isat), la inductancia se desploma y la corriente se dispara: el convertidor puede romperse. Elige siempre Isat por encima del <b>pico</b> de corriente, no de la media.', q: mcq('Una bobina tiene Isat = 2 A y por ella pasan picos de 2,5 A. ¿Qué pasa?', ['Se satura: la inductancia cae y la corriente se dispara', 'Nada', 'Gana inductancia', 'Baja la corriente'], 'Isat debe quedar por encima del pico.') },
    { title: 'Dos corrientes en la hoja de datos', text: 'Las bobinas de potencia dan dos límites: la corriente de <b>saturación</b> (a la que la inductancia ya ha caído un porcentaje que indica el fabricante, a menudo un 20–30 %) y la <b>térmica</b> (la que la calienta unos grados fijados). La que manda en los picos es la de saturación: pasarla dispara la corriente.', q: mcq('¿Qué corriente debe superar el pico que pasa por la bobina de un convertidor?', ['La de saturación', 'Ninguna', 'La media del circuito', 'La de la pila'], 'Por encima de Isat la inductancia se desploma.') }
  ] },
  ba_db: { name: 'Decibelios', alts: [
    { title: '20 · log de la relación', text: 'En tensión: <b>dB = 20 · log₁₀(Vsal / Vent)</b>. ×10 → 20 dB; ×100 → 40 dB; ×1000 → 60 dB; ×2 → unos 6 dB. Si la salida es más pequeña que la entrada, el logaritmo es negativo: ÷2 → −6 dB, ÷10 → −20 dB.', q: mcq('Una señal sale 1000 veces mayor en tensión. ¿Cuántos dB?', ['60 dB', '30 dB', '1000 dB', '3 dB'], '20 × 3.') },
    { title: 'Sumar en vez de multiplicar', text: 'Los dB convierten multiplicaciones en sumas: ×10 son 20 dB, así que ×100 = ×10 × ×10 = 20 + 20 = 40 dB, y ×20 = ×10 × ×2 ≈ 20 + 6 = 26 dB. Atenuar a la mitad son −6 dB; a la décima, −20 dB.', q: mcq('Una señal sale con 0,1 veces su tensión de entrada. ¿dB?', ['−20 dB', '−10 dB', '20 dB', '−1 dB'], '20 × log(0,1) = −20.') }
  ] },
  ba_rms: { name: 'Pico, pico a pico y eficaz', alts: [
    { title: 'Tres formas de dar el tamaño', text: 'De una senoide puedes dar el <b>pico</b> Vp (de 0 a lo más alto), el <b>pico a pico</b> Vpp = 2 · Vp, o el <b>eficaz</b> Vrms = Vp / √2 ≈ 0,707 · Vp: la continua que calentaría lo mismo una resistencia. Los 230 V de la red son eficaces: el pico es unos 325 V.', q: mcq('Una senoide de 100 V de pico. ¿Valor eficaz?', ['Unos 71 V', '141 V', '200 V', '50 V'], '100 × 0,707.') },
    { title: 'Lo que marca el multímetro', text: 'En V~, un multímetro te da el valor <b>eficaz</b>: por eso en un enchufe marca 230 V y no 325. Del eficaz al pico, multiplica por √2 ≈ 1,41; del pico al pico a pico, por 2. Una senoide de 10 V de pico son 20 Vpp y 7,07 Vrms.', q: mcq('Un multímetro en V~ marca 12 V en una senoide. ¿Pico?', ['Unos 17 V', '12 V', '8,5 V', '24 V'], '12 × 1,41.') }
  ] },
  ba_xc: { name: 'Reactancia del condensador', alts: [
    { title: 'Xc = 1 / (2πfC)', text: 'En alterna el condensador se carga y descarga sin parar y deja pasar corriente. Su oposición es <b>Xc = 1 / (2π · f · C)</b>: a más frecuencia o más capacidad, menos reactancia. El doble de frecuencia, la mitad de Xc. Con f = 0 (continua), Xc es infinita: bloquea.', q: mcq('Reactancia de 1 µF a 1 kHz', ['Unos 159 Ω', 'Unos 6283 Ω', '1 kΩ', 'Unos 0,16 Ω'], '1 / (6,283 × 1000 × 0,000001).') },
    { title: 'Por qué baja con la frecuencia', text: 'Cuanto más rápido cambia la tensión, más carga entra y sale del condensador cada segundo: más corriente con la misma tensión, es decir, menos oposición. Xc es inversamente proporcional a f: ×10 en frecuencia, ÷10 en Xc. En continua (f = 0), nada de corriente: reactancia infinita.', q: mcq('Un condensador presenta 1 kΩ a 100 Hz. ¿Y a 1 kHz?', ['100 Ω', '10 kΩ', '1 kΩ', '1 Ω'], 'Diez veces más frecuencia, diez veces menos.') }
  ] },
  ba_xl: { name: 'Reactancia de la bobina', alts: [
    { title: 'XL = 2πfL', text: 'La oposición de una bobina en alterna es <b>XL = 2π · f · L</b>: proporcional a la frecuencia. ×10 en frecuencia, ×10 en XL; en continua (f = 0) es un cable. Al revés que el condensador: la bobina bloquea lo rápido y deja pasar lo lento. Como toda reactancia, no se calienta: guarda energía y la devuelve en cada ciclo.', q: mcq('Reactancia de 10 mH a 1 kHz', ['Unos 63 Ω', 'Unos 10 Ω', 'Unos 6,3 kΩ', 'Unos 16 Ω'], '6,283 × 1000 × 0,01.') },
    { title: 'Choques y ferritas', text: 'Como XL crece con la frecuencia, una bobina en serie deja pasar la continua y frena el ruido de alta frecuencia: es un <b>choque</b>, y el cilindro de ferrita de un cable hace eso. Por lo mismo, la impedancia de un altavoz “de 8 Ω” sube a frecuencias altas. Para despejar f: f = XL / (2π · L). Y no disipa: devuelve la energía en cada ciclo.', q: mcq('¿A qué frecuencia tiene 1 mH una reactancia de 63 Ω?', ['Unos 10 kHz', 'Unos 100 Hz', 'Unos 63 kHz', 'Unos 1 MHz'], '63 / (6,283 × 0,001) ≈ 10 000 Hz.') }
  ] },
  ba_phasor: { name: 'Desfase en bobinas y condensadores', alts: [
    { title: 'Flechas que giran', text: 'Un fasor es una flecha que gira a la frecuencia de la señal; la senoide que ves en el osciloscopio es su sombra. En la bobina, la tensión va 90° por delante de la corriente; en el condensador, 90° por detrás. Sumar fasores es sumar flechas, no números.', q: mcq('En un condensador, la tensión respecto a la corriente va…', ['90° retrasada', '90° adelantada', 'En fase', 'A 180°'], 'Primero entra la corriente y después sube la tensión.') },
    { title: 'CIVIL', text: 'Regla para recordarlo: <b>CIVIL</b>. En C (condensador), la I va antes que la V: la corriente adelanta 90°. En L (bobina), la V va antes que la I: la tensión adelanta 90°. En una resistencia van juntas (0°).', q: mcq('En una bobina en alterna…', ['La tensión va 90° por delante de la corriente', 'La corriente va 90° por delante', 'Van en fase', 'Van a 180°'], 'CIVIL: en L, la V antes que la I.') }
  ] },
  ba_f0: { name: 'Frecuencia de resonancia LC', alts: [
    { title: 'El columpio', text: 'Un columpio tiene su ritmo propio: si empujas justo a ese ritmo, sube mucho con poco esfuerzo. Un circuito LC también: la energía pasa del condensador a la bobina y vuelve, a <b>f₀ = 1 / (2π√(LC))</b>. Así se sintoniza una emisora.', tune: { viz: 'lcResonance', params: { L: { label: 'L', val: 220, list: [10, 22, 47, 100, 220, 470, 1000], unit: 'µH', dec: 0 }, C: { label: 'C (variable)', val: 120, min: 10, max: 1000, step: 5, unit: 'pF', dec: 0 }, R: { label: 'R', val: 47, list: [10, 22, 47, 100, 220, 470, 1000], fmt: 'R' } } }, q: mcq('Aumentas el condensador de un circuito LC. La frecuencia de resonancia…', ['Baja', 'Sube', 'No cambia', 'Se duplica'], 'Más L o más C: el vaivén es más lento.') },
    { title: 'Con números', text: '<b>f₀ = 1 / (2π · √(L · C))</b>. 1 mH y 1 µF: √(10⁻⁹) ≈ 3,16 × 10⁻⁵; por 2π, 1,99 × 10⁻⁴; f₀ ≈ 5 kHz. Errores típicos: olvidar la raíz o el 2π. Para sintonizar más alto, menos L o menos C.', q: mcq('L = 100 µH y C = 100 nF. ¿f₀ aproximada?', ['Unos 50 kHz', 'Unos 5 kHz', 'Unos 500 kHz', 'Unos 316 kHz'], '√(10⁻¹¹) ≈ 3,16 × 10⁻⁶; × 2π ≈ 2 × 10⁻⁵ → 50 kHz.') }
  ] },
  ba_q: { name: 'Factor Q y ancho de banda', alts: [
    { title: 'Lo afilado del pico', text: 'Q dice lo estrecho y alto que es el pico de resonancia. En un RLC serie, <b>Q = XL / R</b> en resonancia, y el ancho de banda (entre los puntos de −3 dB) es <b>BW = f₀ / Q</b>. Menos R → más Q → más selectivo. En un filtro, Q ≈ 0,707 da la respuesta más plana sin pico.', q: mcq('Paso banda a 1 MHz con Q = 50. ¿Ancho de banda?', ['20 kHz', '50 MHz', '50 kHz', '2 kHz'], '1 MHz / 50.') },
    { title: 'Q multiplica la tensión', text: 'En resonancia serie, la tensión en el condensador (y en la bobina) es unas Q veces la de entrada: con Q = 50 y 1 V, unos 50 V. Útil en una radio, peligroso en potencia. Con números: XL = 2 kΩ y R = 10 Ω dan Q = 200; a 10,7 MHz con Q = 20, BW = 535 kHz. Q bajo (≈ 0,7): sin pico.', q: mcq('XL = 1 kΩ y R = 20 Ω en resonancia. ¿Q?', ['50', '20 000', '0,02', '1020'], '1000 / 20.') }
  ] },
  ba_restype: { name: 'Resonancia serie y paralelo', alts: [
    { title: 'Donde las reactancias se anulan', text: 'XL sube con la frecuencia y XC baja. A f₀ son iguales y, en serie, se cancelan: solo queda R y la corriente es máxima. En paralelo (circuito tanque) pasa lo contrario: la impedancia es máxima.', q: mcq('En resonancia serie, la impedancia total es…', ['Solo R', 'Infinita', 'XL + XC', 'XL · XC'], 'XL y XC se cancelan.') },
    { title: 'Serie deja pasar, paralelo bloquea', text: 'En resonancia, un LC en <b>serie</b> es casi un cable (solo queda R): la corriente es máxima. Un LC en <b>paralelo</b> hace lo contrario: la energía va y viene entre L y C y desde fuera casi no entra corriente; su impedancia es máxima (infinita si fuera ideal).', q: mcq('Un LC en serie, en resonancia, entre un generador y una carga. ¿Qué hace a f₀?', ['Deja pasar: su impedancia es mínima', 'Bloquea: su impedancia es máxima', 'Invierte la señal', 'Nada distinto'], 'En serie, XL y XC se anulan.') }
  ] },
  ba_pf: { name: 'Potencia activa, aparente y factor de potencia', alts: [
    { title: 'Tres potencias', text: '<b>Aparente</b> S = Vrms · Irms (VA): lo que tienen que aguantar cables y transformadores. <b>Activa</b> P = S · cos φ (W): lo que de verdad se convierte en calor, luz o movimiento. El factor de potencia cos φ vale 1 en una resistencia pura y menos con bobinas o condensadores.', q: mcq('230 V y 2 A con cos φ = 0,5. ¿Potencia activa?', ['230 W', '460 W', '920 W', '115 W'], '460 VA × 0,5.') },
    { title: 'VA no son vatios', text: 'Multiplicar tensión por corriente eficaces da VA, no vatios. Un SAI de “1000 VA / 600 W” tiene dos límites y hay que respetar los dos. Con mal factor de potencia circula más corriente para la misma potencia útil: más pérdidas en la red, por eso a la compañía no le gusta.', q: mcq('Un motor a 230 V consume 4 A con cos φ = 0,8. ¿Potencia aparente?', ['920 VA', '736 VA', '1150 VA', '288 VA'], 'S = 230 × 4; la activa sería 736 W.') }
  ] },
  ba_xfmr: { name: 'Transformadores', alts: [
    { title: 'Relación de vueltas', text: 'La tensión se reparte según las vueltas: <b>Vs / Vp = Ns / Np</b>. 1000 vueltas en el primario y 50 en el secundario, con 230 V: 230 × 50 / 1000 = 11,5 V. Funciona solo con alterna, y entre primario y secundario no hay conexión eléctrica.', q: mcq('Primario de 2000 vueltas a 230 V y secundario de 100. ¿Tensión de salida?', ['11,5 V', '4600 V', '23 V', '115 V'], '230 × 100 / 2000.') },
    { title: 'Solo con cambios', text: 'Un transformador funciona por inducción: la alterna del primario crea un campo magnético que cambia, y ese cambio induce tensión en el secundario (Vs / Vp = Ns / Np). Con una pila no hay cambio y no sale nada. Además, entre las bobinas no hay conexión: <b>aislamiento galvánico</b>, una gran ventaja de seguridad.', q: mcq('¿Por qué un transformador no funciona con continua?', ['Porque solo un campo que cambia induce tensión', 'Porque la pila es pequeña', 'Porque la continua no tiene polaridad', 'Sí funciona'], 'Inducción = cambio.') }
  ] },
  /* ba:m7 fin */
  /* --- Curso base ampliado --- */
  engnum: { name: 'Notación de ingeniería', alts: [
    { title: 'Saltos de tres', text: 'La notación de ingeniería es la científica con una condición: el exponente siempre es múltiplo de 3. Así cada exponente tiene su prefijo: 10⁻⁶ es µ y 10³ es k.\n0,000 047 F = 47 × 10⁻⁶ F = <b>47 µF</b>.', q: mcq('¿Cómo se escribe 0,0022 A con prefijo?', ['2,2 mA', '2,2 µA', '22 mA', '0,22 mA'], '0,0022 = 2,2 × 10⁻³ → mili.') },
    { title: 'Cuenta grupos de tres cifras', text: 'Para pasar un número a notación de ingeniería, sepáralo en grupos de tres cifras desde la coma, como en 2 200 000. Cada grupo es un salto de prefijo: dos grupos completos a la izquierda → mega: <b>2,2 MΩ</b>. Con decimales, igual: 0,000 150 → dos grupos tras la coma → micro: <b>150 µ</b>. Delante del prefijo debe quedar un número entre 1 y 999.', q: mcq('¿Cómo se escribe 0,000 47 F con prefijo?', ['470 µF', '47 µF', '4,7 mF', '4,7 µF'], '0,000 47 = 470 × 10⁻⁶: micro.') },
    { title: 'Por qué múltiplos de 3', text: 'Científica: 2,2 × 10⁻⁷ F. Ingeniería: 220 × 10⁻⁹ F. Es el mismo número, pero el segundo se lee directamente: 10⁻⁹ es nano, así que son <b>220 nF</b>. Para pasar de una a otra, mueve la coma de una en una, ajustando el exponente, hasta que sea múltiplo de 3 y delante quede entre 1 y 999.', q: mcq('¿Cuál de estas está en notación de ingeniería?', ['47 × 10³ Ω', '4,7 × 10⁴ Ω', '0,47 × 10⁵ Ω', '470 × 10² Ω'], 'Solo 10³ es múltiplo de 3: 47 kΩ.') }
  ] },
  esafety: { name: 'Seguridad eléctrica', alts: [
    { title: 'Lo que hace daño es la corriente', text: 'El peligro lo marca la <b>corriente que atraviesa tu cuerpo</b>, y esa corriente la pone la tensión venciendo la resistencia de tu piel. Con la piel seca, 9 V apenas mueven unos microamperios. Con los 230 V de la red pueden pasar decenas de miliamperios por el pecho: suficiente para parar el corazón.', q: mcq('¿Por qué puedes tocar los dos polos de una pila de 9 V pero nunca los de un enchufe?', ['Con 9 V tu piel deja pasar una corriente mínima; con 230 V, una peligrosa', 'Porque la continua nunca hace daño', 'Porque el enchufe guarda más amperios', 'Porque la pila lleva fusible'], 'La tensión empuja, tu resistencia limita y la corriente hace el daño.') },
    { title: 'Energía guardada', text: 'No solo la red: una batería de litio en cortocircuito suelta decenas de amperios y puede arder, y un condensador grande de una fuente o de un flash puede seguir cargado con cientos de voltios después de desenchufar. Antes de tocar: desconecta, espera, mide y descarga con una resistencia.', q: mcq('Desenchufas una fuente de red para repararla. ¿Qué haces antes de meter la mano?', ['Medir y descargar los condensadores grandes con una resistencia', 'Nada: ya está desenchufada', 'Cortocircuitarlos con un destornillador', 'Esperar dos segundos'], 'Pueden guardar tensión peligrosa durante mucho rato. Se descargan de forma controlada.') }
  ] },
  network: { name: 'Thévenin, Norton y superposición', alts: [
    { title: 'Una caja negra', text: 'Vista desde dos bornes, cualquier red de pilas y resistencias se comporta como una pila con una resistencia en serie (Thévenin) o como una fuente de corriente con una resistencia en paralelo (Norton). Dos medidas la resumen: la tensión en vacío y la corriente en cortocircuito. <b>Rth = Vvacío / Icorto</b>.', q: mcq('Una salida da 6 V en vacío y 30 mA en cortocircuito. ¿Rth?', ['200 Ω', '180 Ω', '5 Ω', '0,2 Ω'], '6 / 0,03 = 200 Ω.') },
    { title: 'De una en una', text: 'Superposición: con varias fuentes, calcula el efecto de cada una con las demás “apagadas” (pila → cable; fuente de corriente → hueco abierto) y suma los resultados. Funciona porque las resistencias son lineales.', q: mcq('Al aplicar superposición, ¿qué haces con una pila que no estás analizando?', ['La sustituyes por un cable', 'La quitas y dejas el hueco abierto', 'La duplicas', 'La das la vuelta'], 'Una pila apagada da 0 V: es un cable.') }
  ] },
  scope: { name: 'Disparo del osciloscopio', alts: [
    { title: 'Una foto que necesita disparador', text: 'El osciloscopio dibuja la señal una y otra vez. Para que la imagen quede quieta, cada barrido debe empezar en el mismo punto de la onda: eso es el <b>disparo</b>. Eliges un nivel y un flanco; si el nivel queda fuera de la señal, no dispara y la imagen corre.', tune: { viz: 'scopeTrigger', params: { lvl: { label: 'Nivel de disparo', val: 3, min: -3, max: 3, step: 0.1, unit: 'V', dec: 1 }, tdiv: { label: 'Tiempo/div', val: 0.5, list: [0.05, 0.1, 0.2, 0.5, 1, 2], unit: 'ms', dec: 2 } } }, q: mcq('Una senoide de 2 V de pico corre sin parar por la pantalla. El nivel de disparo está en 3 V. ¿Qué haces?', ['Bajar el nivel dentro de la señal, por ejemplo a 0 V', 'Subir la escala de tiempo', 'Cambiar la sonda', 'Subir el nivel a 5 V'], 'Si la señal nunca cruza el nivel, no hay disparo.') },
    { title: 'Auto, Normal y Single', text: 'Primero, el nivel de disparo tiene que estar dentro de la señal; luego elige una base de tiempos que deje ver unos pocos ciclos. El modo decide qué pasa cuando no hay disparo: <b>Auto</b> dibuja igualmente (la imagen corre); <b>Normal</b> solo dibuja al disparar y deja la última captura; <b>Single</b> captura una vez y se para, perfecto para un suceso único como el rebote de un pulsador, disparando en el flanco que esperas.', q: mcq('Quieres capturar el único pulso que da un sensor al pasar una mano. ¿Qué modo de disparo?', ['Single', 'Auto', 'Ninguno: no se puede', 'Normal con el nivel fuera de la señal'], 'Una captura única del suceso.') }
  ] },
  inductor: { name: 'Bobina', alts: [
    { title: 'Un volante de inercia', text: 'Una bobina es la inercia de la electricidad: cuesta arrancar la corriente y cuesta pararla. Su tensión depende de lo rápido que cambia la corriente: <b>V = L · ΔI / Δt</b>. Corriente constante → 0 V; cambio brusco → pico enorme.', tune: { viz: 'rlCurrent', params: { L: { label: 'L', val: 100, list: [1, 10, 47, 100, 470, 1000], unit: 'mH', dec: 0 }, R: { label: 'R', val: 100, list: [10, 22, 47, 100, 220, 470, 1000], fmt: 'R' }, V: { val: 5, fixed: true } } }, q: mcq('Por una bobina ideal pasa una corriente continua constante. ¿Qué tensión cae en ella?', ['Cero', 'Muchísima', 'La de la pila', 'Depende del color'], 'Sin cambio de corriente no hay tensión inducida.') },
    { title: 'Con números: τ = L / R', text: 'Al conectar una bobina y una resistencia a una pila, la corriente sube como la tensión de un condensador: 63 % tras τ y casi toda tras 5τ. Pero aquí <b>τ = L / R</b>: más resistencia, más rápido. Corriente final: I = V / R.', q: mcq('100 mH con 100 Ω. ¿τ?', ['1 ms', '10 s', '10 ms', '0,1 ms'], '0,1 / 100 = 0,001 s.') }
  ] },
  impedance: { name: 'Impedancia', alts: [
    { title: 'El triángulo', text: 'En alterna, una resistencia y una reactancia en serie no se suman sin más: sus tensiones están desfasadas 90°. Se combinan como los catetos de un triángulo rectángulo: <b>Z = √(R² + X²)</b>. El ángulo φ es el desfase entre tensión y corriente.', tune: { viz: 'zTriangle', params: { R: { label: 'R', val: 300, min: 0, max: 1000, step: 10, unit: 'Ω', dec: 0 }, X: { label: 'X (+ bobina, − condensador)', val: 400, min: -1000, max: 1000, step: 10, unit: 'Ω', dec: 0 } } }, q: mcq('R = 30 Ω y X = 40 Ω en serie. ¿Z?', ['50 Ω', '70 Ω', '10 Ω', '1200 Ω'], '√(900 + 1600) = 50.') },
    { title: 'Las tensiones no suman', text: 'En un RC en serie con R = Xc = 1 kΩ, la impedancia es √(1000² + 1000²) ≈ 1414 Ω. Con 10 V eficaces, I ≈ 7,1 mA y en cada uno caen unos 7,1 V: no suman 10 porque están desfasadas 90°. El desfase entre la tensión total y la corriente es <b>φ = arctan(X / R)</b>: aquí, 45°.', q: mcq('R = 40 Ω y X = 30 Ω en serie. ¿Desfase entre tensión y corriente?', ['Unos 37°', '90°', 'Unos 53°', '0°'], 'arctan(30 / 40) ≈ 36,9°.') }
  ] },
  resonance: { name: 'Resonancia', alts: [
    { title: 'El columpio', text: 'Un columpio tiene su ritmo propio: si empujas justo a ese ritmo, sube mucho con poco esfuerzo. Un circuito LC también: la energía pasa del condensador a la bobina y vuelve, a <b>f₀ = 1 / (2π√(LC))</b>. Así se sintoniza una emisora.', tune: { viz: 'lcResonance', params: { L: { label: 'L', val: 220, list: [10, 22, 47, 100, 220, 470, 1000], unit: 'µH', dec: 0 }, C: { label: 'C (variable)', val: 120, min: 10, max: 1000, step: 5, unit: 'pF', dec: 0 }, R: { label: 'R', val: 47, list: [10, 22, 47, 100, 220, 470, 1000], fmt: 'R' } } }, q: mcq('Aumentas el condensador de un circuito LC. La frecuencia de resonancia…', ['Baja', 'Sube', 'No cambia', 'Se duplica'], 'Más L o más C: el vaivén es más lento.') },
    { title: 'Donde las reactancias se anulan', text: 'XL sube con la frecuencia y XC baja. A una frecuencia son iguales y, en serie, se cancelan: solo queda R y la corriente es máxima. <b>Q = XL / R</b> dice lo afilado del pico: ancho de banda = f₀ / Q.', q: mcq('En resonancia serie, la impedancia total es…', ['Solo R', 'Infinita', 'XL + XC', 'XL · XC'], 'XL y XC se cancelan.') }
  ] },
  thermal: { name: 'Calor y resistencia térmica', alts: [
    { title: 'Ohm, pero con calor', text: 'El calor fluye como la corriente: la potencia hace de corriente (W), la diferencia de temperatura de tensión (°C) y la resistencia térmica (°C/W) frena el paso. <b>ΔT = P · Rθ</b>. Las resistencias en serie (unión → cápsula → disipador → aire) se suman.', q: mcq('Rθ total de 20 °C/W y 3 W. ¿Cuánto sube la temperatura sobre la del ambiente?', ['60 °C', '6,7 °C', '23 °C', '0,15 °C'], '3 × 20 = 60 °C.') },
    { title: 'Para qué un disipador', text: 'Un TO-220 al aire tiene unos 50–65 °C/W según el fabricante: con 2 W subiría más de 100 °C. Un disipador ofrece al calor un camino más fácil (pocos °C/W). El límite lo pone la temperatura máxima de la unión, normalmente 125–150 °C.', q: mcq('¿Qué hace un disipador?', ['Baja la resistencia térmica hasta el aire', 'Reduce la potencia que disipa el chip', 'Sube la tensión de salida', 'Aísla del calor'], 'La potencia es la misma; sale con menos subida de temperatura.') }
  ] },
  mosfet: { name: 'MOSFET', alts: [
    { title: 'Umbral no es encendido', text: 'Con Vgs(th) el MOSFET apenas <b>empieza</b> a conducir (microamperios o pocos miliamperios). Para conducir de verdad necesita la tensión a la que la hoja de datos garantiza Rds(on): 10 V, 4,5 V o 2,5 V según el modelo.', q: mcq('Hoja de datos: Vgs(th) = 2 V y Rds(on) garantizada solo a 10 V. ¿Basta 3,3 V para 5 A?', ['No es seguro: no hay Rds(on) garantizada a esa tensión', 'Sí, supera el umbral', 'No, necesita exactamente 2 V', 'Sí, la puerta no importa'], 'El umbral es donde empieza a conducir, no donde conduce bien.') },
    { title: 'Un condensador que hay que llenar', text: 'La puerta es un condensador: para conmutar hay que meter y sacar su carga (Qg, en nC) deprisa. <b>I = Q / t</b>. Un pin débil tarda y el MOSFET pasa tiempo a medio conducir, calentándose. Un driver da amperios durante nanosegundos.', q: mcq('Un MOSFET se calienta con PWM rápido aunque su Rds(on) es bajísima. ¿Qué sospechas?', ['Que la puerta se carga despacio y pasa mucho tiempo a medias', 'Que Rds(on) es demasiado baja', 'Que la frecuencia es demasiado baja', 'Que la puerta consume mucha corriente en continua'], 'Pérdidas de conmutación: hace falta un driver.') }
  ] },
  hyst: { name: 'Histéresis', alts: [
    { title: 'Un termostato', text: 'Un termostato no enciende a 20,0 °C y apaga a 20,0 °C: estaría conmutando sin parar. Enciende a 19 °C y apaga a 21 °C. Un Schmitt trigger hace lo mismo con tensiones: un umbral para subir y otro para bajar.', tune: { viz: 'schmittHyst', params: { R1: { label: 'R1', val: 1000, list: [1000, 2200, 4700, 10000, 22000, 47000], fmt: 'R' }, R2: { label: 'R2', val: 100000, list: [10000, 22000, 47000, 100000, 220000], fmt: 'R' } } }, q: mcq('¿Para qué sirve la histéresis?', ['Para que el ruido cerca del umbral no haga oscilar la salida', 'Para amplificar más', 'Para ahorrar energía', 'Para invertir la señal'], 'La salida solo cambia si la entrada cruza con claridad.') },
    { title: 'Con números', text: 'En el Schmitt no inversor con Vref = Vcc / 2, la salida empuja a IN+ a través de R2: la histéresis vale <b>Vcc · R1 / R2</b>, centrada en Vref. Más R1 o menos R2, más separados los umbrales.', q: mcq('Vcc = 5 V, R1 = 10 kΩ y R2 = 100 kΩ. ¿Histéresis?', ['0,5 V', '5 V', '0,05 V', '50 V'], '5 × 10 / 100.') }
  ] },
  quant: { name: 'Cuantización', alts: [
    { title: 'Una escalera', text: 'Un ADC o un DAC trabajan en escalones: con n bits hay 2ⁿ escalones entre 0 y Vref. Un escalón (1 LSB) = Vref / 2ⁿ. Todo lo que cae dentro del mismo escalón da el mismo número: es el error de cuantización, de hasta medio escalón.', q: mcq('10 bits y 5 V de referencia. ¿Cuánto vale un escalón?', ['Unos 4,9 mV', '0,5 V', '10 mV', '1 mV'], '5 / 1024 ≈ 4,88 mV.') },
    { title: 'Más bits no es más exactitud', text: 'Los bits dan resolución (escalones finos), no exactitud: si la referencia se desvía un 1 %, todas las lecturas se desvían un 1 % aunque tengas 16 bits. Y el ruido puede comerse los últimos bits.', q: mcq('ADC de 12 bits con una referencia que puede variar un 2 %. Tus lecturas…', ['Pueden estar un 2 % desviadas aunque parezcan muy finas', 'Son exactas al 0,02 %', 'Son siempre correctas', 'Solo fallan con 8 bits'], 'Resolución y exactitud son cosas distintas.') }
  ] },
  smps: { name: 'Fuentes conmutadas', alts: [
    { title: 'Trocear y alisar', text: 'Un buck trocea la entrada con un transistor y la alisa con una bobina y un condensador. La media de la tensión troceada es Vent · D, así que <b>Vsal ≈ D · Vent</b>. La bobina mantiene la corriente mientras el transistor está abierto, a través de un diodo o de otro transistor.', q: mcq('Buck ideal de 12 V a 3 V. ¿Ciclo de trabajo?', ['25 %', '4 %', '75 %', '36 %'], '3 / 12.') },
    { title: 'El rizado se elige', text: 'La corriente de la bobina sube y baja en cada ciclo: <b>ΔI = (Vent − Vsal) · D / (L · f)</b>. Se suele elegir un ΔI del 20 al 40 % de la corriente de salida. Más frecuencia o más inductancia, menos rizado; y la bobina debe aguantar el pico sin saturarse.', q: mcq('Doblas la frecuencia de conmutación de un buck. El rizado de corriente…', ['Se reduce a la mitad', 'Se duplica', 'No cambia', 'Se cuadruplica'], 'ΔI es inversamente proporcional a f.') }
  ] },
  libat: { name: 'Baterías de litio', alts: [
    { title: 'Corriente y luego tensión', text: 'Una celda de litio se carga en dos fases: <b>corriente constante</b> (CC) hasta llegar a 4,2 V y luego <b>tensión constante</b> (CV) a 4,2 V mientras la corriente va bajando. Se termina cuando la corriente cae a una fracción (≈ 1/10). Pasar de 4,2 V la degrada y puede ser peligroso.', q: mcq('Durante la fase CV, la corriente de carga…', ['Va bajando', 'Sube', 'Es constante', 'Cambia de sentido'], 'La tensión está fija y la celda cada vez admite menos.') },
    { title: 'Cargar no es proteger', text: 'El cargador (como el TP4056) controla la carga. La protección (o BMS) corta si la tensión baja demasiado, si sube demasiado o si hay sobrecorriente o cortocircuito. Son cosas distintas: el cargador no te salva de vaciar la celda del todo.', q: mcq('Una celda sin protección alimenta un circuito hasta quedarse en 2 V. ¿Qué pasa?', ['Se daña por descarga profunda y recargarla puede ser peligroso', 'Nada: se recarga igual', 'Gana capacidad', 'Vuelve sola a 4,2 V'], 'Por eso se usa protección contra descarga profunda.') }
  ] },
  /* --- Curso base m8: semiconductores y diodos (conceptos estrechos) --- */
  bb_polprot: { name: 'Protección contra polaridad invertida', alts: [
    { title: 'Una puerta que solo abre en un sentido', text: 'Un diodo en serie con la alimentación deja pasar la corriente si la pila está bien puesta y la bloquea si la conectas al revés: el circuito se salva. El precio es su caída en directa, que se pierde siempre: unos <b>0,7 V</b> con un diodo de silicio (1N4007) y unos <b>0,2–0,45 V</b> con un Schottky.', q: mcq('Proteges con un 1N4007 un circuito alimentado a 5 V. ¿Qué tensión le llega?', ['Unos 4,3 V', '5 V', '5,7 V', '0,7 V'], 'El diodo se queda con unos 0,7 V.') },
    { title: 'Comparar pérdidas', text: 'De más a menos pérdida: diodo de silicio (≈ 0,7 V), <b>Schottky</b> (≈ 0,3 V) y <b>MOSFET de canal P</b> en el positivo, que solo cae <b>I · Rds(on)</b>, a menudo unos milivoltios. Con 3,3 V, perder 0,7 V es más de un 20 %: por eso en baja tensión se usa Schottky o MOSFET.', q: mcq('Pasa 1 A por un MOSFET P con Rds(on) = 0,03 Ω que protege contra la polaridad invertida. ¿Cuánto cae?', ['30 mV', '0,7 V', '0,3 V', '3 V'], 'I · Rds(on) = 1 × 0,03 = 0,03 V.') }
  ] },
  bb_ledr: { name: 'Resistencia de un LED', alts: [
    { title: 'La receta', text: '1) Resta a la fuente la tensión del LED (rojo ~1,8 V, verde ~2,1 V, azul o blanco ~3 V). 2) Divide lo que queda entre la corriente, en amperios: <b>R = (Vfuente − VLED) / I</b>. 3) Elige el valor comercial siguiente hacia arriba. Con LEDs en serie, resta la suma de sus tensiones.', q: mcq('5 V, LED rojo (1,8 V) y 10 mA. ¿Resistencia?', ['320 Ω', '500 Ω', '180 Ω', '680 Ω'], '(5 − 1,8) / 0,01 = 320 Ω → 330 Ω comercial.') },
    { title: 'Una resistencia para cada uno', text: 'La resistencia es la que fija la corriente: por encima de su tensión, el LED la dejaría dispararse. Por eso cada LED (o cada rama de LEDs en serie) lleva su propia resistencia; con varios en paralelo y una sola, el de menor tensión se lleva casi toda la corriente. Tres rojos en serie a 12 V y 15 mA: (12 − 3 × 1,8) / 0,015 = 440 Ω.', q: mcq('Dos LEDs blancos (3 V) en serie con 9 V y 20 mA. ¿Resistencia?', ['150 Ω', '300 Ω', '450 Ω', '600 Ω'], '(9 − 6) / 0,02 = 150 Ω.') }
  ] },
  bb_protect: { name: 'Fusibles, PTC y TVS', alts: [
    { title: 'Cada amenaza, su protección', text: '<b>Sobrecorriente</b>: un fusible (se funde y hay que cambiarlo) o un <b>PTC</b> rearmable (se calienta, su resistencia sube y se recupera al enfriarse; típico en USB). <b>Picos de tensión</b> y descargas electrostáticas: diodos <b>TVS</b>, que conducen en nanosegundos y llevan el pico a masa.', q: mcq('Un puerto USB debe protegerse de cortocircuitos sin tener que cambiar piezas. ¿Qué pones?', ['Un fusible PTC rearmable', 'Un fusible de vidrio', 'Un TVS', 'Un LED'], 'El PTC se rearma solo al enfriarse.') },
    { title: 'En serie o en paralelo', text: 'Lo que corta la corriente va <b>en serie</b>: fusible y PTC. Lo que desvía picos va <b>en paralelo</b>, a masa: un TVS no hace nada a la tensión normal y, si llega un pico (al tocar un conector cargado de electricidad estática), conduce y lo absorbe antes de que alcance el chip. Por eso las líneas de datos USB llevan TVS (o una matriz de TVS) a masa.', q: mcq('Un TVS que protege una entrada se conecta…', ['En paralelo, entre la línea y masa', 'En serie con la línea', 'En serie con la alimentación', 'No se conecta: va dentro del chip'], 'Desvía el pico a masa.') }
  ] },
  /* m8–m10 (diodos, transistores, integrados y 555): sus conceptos están en src/base/m08.js, m09.js y m10.js */
  bb_isrc: { name: 'Fuentes de corriente', alts: [
    { title: 'El emisor sigue a la base', text: 'Con un NPN: fija la base con un zener (Vz) y pon Re en el emisor. El emisor queda a Vz − 0,65 V, así que <b>I = (Vz − 0,65) / Re</b>, y el colector da esa corriente sea cual sea la carga, mientras al transistor le quede tensión para no saturarse (su margen de trabajo). Si la carga pide más tensión de la disponible, se satura y la corriente baja.', q: mcq('Zener de 4,7 V en la base y Re = 100 Ω. ¿Corriente?', ['Unos 40 mA', '47 mA', '6,5 mA', '53 mA'], '(4,7 − 0,65) / 100 ≈ 40 mA.') },
    { title: 'Atajos: LM317 y espejo', text: 'El <b>LM317</b> mantiene 1,25 V entre OUT y ADJ: con una resistencia entre ellas, <b>I = 1,25 V / R</b> (3,6 Ω → unos 350 mA). Otra fuente clásica es el <b>espejo de corriente</b>: dos transistores iguales con las bases unidas; lo que pasa por el primero se copia en el segundo. Hay espejos dentro de casi todos los operacionales y chips analógicos.', q: mcq('LM317 como fuente de corriente de 100 mA. ¿Resistencia?', ['12,5 Ω', '125 Ω', '1,25 Ω', '0,08 Ω'], '1,25 / 0,1 = 12,5 Ω.') }
  ] },
  bb_motor: { name: 'Motores: rueda libre y puente H', alts: [
    { title: 'La bobina no quiere parar', text: 'Motores, relés y solenoides son bobinas: al cortar su corriente generan un pico de tensión que puede romper el transistor. El <b>diodo de rueda libre</b>, en paralelo con la bobina y con el <b>cátodo al +</b>, no conduce normalmente; al cortar, da un camino a esa corriente hasta que se apaga. En un puente H, nunca cierres los dos interruptores del mismo lado.', q: mcq('El diodo de rueda libre de un relé se pone…', ['En paralelo con la bobina, cátodo al +', 'En serie con la bobina', 'En paralelo, ánodo al +', 'Entre base y emisor'], 'En inversa en funcionamiento normal; solo actúa con el pico.') },
    { title: 'Cuatro interruptores en H', text: 'Un <b>puente H</b> son cuatro interruptores, dos por lado, con el motor en el centro. Cerrando arriba a la izquierda y abajo a la derecha gira en un sentido; con la otra diagonal, en el otro. Si cierras los dos del <b>mismo lado</b>, unes + con masa: cortocircuito. Los chips de puente H (DRV8833, L298) lo impiden y traen los diodos de rueda libre.', q: mcq('En un puente H cierras arriba-izquierda y abajo-izquierda. ¿Qué pasa?', ['Cortocircuito de la alimentación', 'El motor gira hacia la izquierda', 'El motor frena', 'Nada'], 'Los dos del mismo lado unen + y masa.') }
  ] },
  /* --- Curso base m10: circuitos integrados --- */
  bb_packages: { name: 'Encapsulados y tamaños', alts: [
    { title: 'Con o sin agujero', text: '<b>De inserción (THT)</b>: patas que atraviesan la placa; DIP para chips, TO-92 y TO-220 para transistores y reguladores; sirven en protoboard. <b>De superficie (SMD)</b>: se sueldan encima; SOIC (patas en ala), SOT-23, QFN (sin patas, pads debajo), BGA (bolitas debajo) y pasivos como 0805 o 0603.', q: mcq('¿Cuál de estos encapsulados es de inserción?', ['TO-92', 'SOT-23', 'QFN', '0603'], 'El TO-92 tiene tres patas que atraviesan la placa.') },
    { title: 'Números que son medidas', text: 'El paso de DIP y protoboard es 0,1 pulgadas = <b>2,54 mm</b>; SOIC usa 1,27 mm (la mitad) y TSSOP, 0,65 mm. En pasivos SMD, el código es el tamaño en centésimas de pulgada: <b>0805</b> = 0,08 × 0,05 pulgadas ≈ 2,0 × 1,25 mm; <b>0603</b> ≈ 1,6 × 0,8 mm.', q: mcq('¿Qué paso tienen las patas de un SOIC?', ['1,27 mm', '2,54 mm', '0,65 mm', '0,5 mm'], 'La mitad de 0,1 pulgadas.') }
  ] },
  bb_datasheet: { name: 'Leer la hoja de datos', alts: [
    { title: 'Límites, recomendado y típico', text: '<b>Absolute maximum ratings</b>: límites de rotura, no se rozan nunca. <b>Recommended operating conditions</b>: donde funciona bien; diseña ahí. En las características, <b>typ.</b> es lo típico, sin garantía: para diseñar usa <b>min.</b> y <b>max.</b> Un 74HC con máximo absoluto de 7 V y recomendado de 2–6 V se alimenta a 5 V, nunca a 9 V.', q: mcq('Un sensor: absolute maximum 4 V; recommended 1,8–3,6 V. ¿A qué lo alimentas?', ['3,3 V', '4 V', '5 V', '3,9 V'], 'Dentro del rango recomendado, lejos del límite de rotura.') },
    { title: 'El pinout manda', text: 'El orden de patas cambia entre modelos aunque la cápsula sea igual: un 2N3904 es E-B-C con la cara plana hacia ti, pero otros TO-92 no; el 7805, de frente, es entrada-masa-salida, y el LM317, ADJ-salida-entrada. Míralo siempre en el <b>pinout de la hoja de datos</b> y comprueba que la huella de la PCB lo respeta: si no, la placa sale bien pero no funciona.', q: mcq('Cambias un transistor por otro con la misma cápsula TO-92. ¿Qué compruebas primero?', ['Que el orden de patas coincida en su hoja de datos', 'Que sea del mismo color', 'Nada: todos los TO-92 son iguales', 'Que pese lo mismo'], 'La cápsula no dice qué pata es cada una.') }
  ] },
  bb_decoup: { name: 'Condensador de desacoplo', alts: [
    { title: 'Una reserva al lado', text: 'Un chip pide corriente a golpes, en cada flanco de reloj. Las pistas hasta la fuente tienen inductancia y no dan esos picos al instante: la tensión cae un momento y el chip puede reiniciarse. Un <b>condensador de 100 nF pegado a sus patas de alimentación</b> es una reserva local que da esos picos. Si un circuito digital se reinicia «a veces», revisa primero alimentación y desacoplo.', q: mcq('Un microcontrolador se reinicia al encender un relé. ¿Qué revisas primero?', ['La alimentación y el condensador de desacoplo', 'El código', 'El color de los cables', 'La serigrafía'], 'Las caídas de alimentación son la causa número uno.') },
    { title: 'Cada milímetro cuenta', text: 'El desacoplo solo sirve si el bucle condensador–chip es pequeño: el condensador lo más cerca posible de las patas de VCC y GND, y su <b>vía de masa pegada a su pad</b>, para que la corriente vaya y vuelva por el camino más corto. Un 100 nF a cinco centímetros casi no sirve.', q: mcq('En la PCB, el 100 nF de un chip va…', ['Pegado a sus patas de alimentación, con la vía de masa junto a su pad', 'Junto al conector de alimentación', 'En una esquina libre', 'Lejos, para que no estorbe'], 'Bucle mínimo entre condensador y chip.') }
  ] },
  bb_opgain: { name: 'Ganancia del inversor y del no inversor', alts: [
    { title: 'Dos fórmulas', text: '<b>No inversor</b> (señal a la +, Rf de la salida a la −, Rg de la − a masa): <b>G = 1 + Rf / Rg</b>; nunca baja de 1, y con la salida unida directamente a la − es un <b>seguidor</b>: G = 1. <b>Inversor</b> (señal a la − por Rin, la + a masa): <b>G = −Rf / Rin</b>; el signo indica que sale dada la vuelta.', q: mcq('No inversor con Rf = 47 kΩ y Rg = 4,7 kΩ. ¿Ganancia?', ['11', '10', '−10', '0,1'], '1 + 47/4,7 = 11.') },
    { title: 'Míralo en el inversor', text: 'La − se queda a 0 V (masa virtual). La corriente que entra por Rin, Vent / Rin, no puede meterse en el chip: sigue entera por Rf. Para que eso pase, la salida tiene que quedar al otro lado, Rf / Rin veces más lejos. Mueve Rf y Rin y mira la ganancia.', tune: { viz: 'opInv', params: { Vin: { label: 'Entrada', val: 0.5, min: -1, max: 1, step: 0.05, unit: 'V', dec: 2 }, Rin: { label: 'Rin', val: 10000, fmt: 'R', min: 1000, max: 100000 }, Rf: { label: 'Rf', val: 22000, fmt: 'R', min: 1000, max: 100000 } } }, q: mcq('Inversor con Rf = 22 kΩ, Rin = 10 kΩ, la + a masa y 0,5 V a la entrada. ¿Salida?', ['−1,1 V', '1,1 V', '−0,23 V', '1,6 V'], '−22/10 × 0,5 = −1,1 V.') },
    { title: 'El divisor del no inversor', text: 'En el no inversor, Rf y Rg forman un divisor entre la salida y masa, y su punto medio (la −) tiene que valer lo mismo que la entrada. Si Rg es la décima parte de Rf + Rg, la salida tiene que ser 10 veces la entrada… más exactamente, (Rf + Rg) / Rg = 1 + Rf / Rg. Con alimentación única, todo se mide respecto a la referencia que pongas en la +.', tune: { viz: 'opNI', params: { Vin: { label: 'Entrada', val: 0.4, min: 0, max: 2, step: 0.05, unit: 'V', dec: 2 }, Rf: { label: 'Rf', val: 47000, fmt: 'R', min: 1000, max: 100000 }, Rg: { label: 'Rg', val: 4700, fmt: 'R', min: 1000, max: 100000 }, fol: { val: 0, fixed: true } } }, q: mcq('No inversor con Rf = Rg = 10 kΩ y 1 V a la entrada. ¿Salida?', ['2 V', '1 V', '0,5 V', '−1 V'], 'G = 1 + 1 = 2.') }
  ] },
  bb_oplimits: { name: 'Límites del operacional real', alts: [
    { title: 'Cuatro defectos y su síntoma', text: '<b>Offset</b>: como si hubiera unos mV entre las entradas; la ganancia lo multiplica (5 mV × 100 = 0,5 V de error). <b>Salida</b>: no llega a la alimentación (un LM358 a 5 V se queda en unos 3,5 V; un rail-to-rail llega casi a 0 y a 5 V). <b>GBW</b>: la ganancia cae con la frecuencia. <b>Slew rate</b>: la salida no cambia más rápido de cierto V/µs.', q: mcq('Ganancia 200 y 3 mV de offset. ¿Error en la salida?', ['0,6 V', '3 mV', '67 V', '0,06 V'], '0,003 × 200 = 0,6 V.') },
    { title: 'La salida tiene techo', text: 'Por mucha ganancia que pongas, la salida no pasa de lo que da el chip, algo por debajo de su alimentación. Calcula siempre la salida ideal (entrada × ganancia) y compárala con ese techo: si lo supera, la salida se queda pegada y las reglas de oro dejan de valer. Pruébalo subiendo la entrada.', tune: { viz: 'opNI', params: { Vin: { label: 'Entrada', val: 0.5, min: 0, max: 2, step: 0.05, unit: 'V', dec: 2 }, Rf: { label: 'Rf', val: 100000, fmt: 'R', min: 1000, max: 100000 }, Rg: { label: 'Rg', val: 10000, fmt: 'R', min: 1000, max: 100000 }, fol: { val: 0, fixed: true } } }, q: mcq('Un LM358 a 12 V con ganancia 10 recibe 1,5 V. ¿Qué sale?', ['Algo más de 10 V: se satura por debajo de 12 V', '15 V', '1,5 V', '12 V exactos'], '1,5 × 10 = 15 V no cabe; un LM358 a 12 V llega a unos 10,5 V.') },
    { title: 'Mira la tensión de salida', text: 'La hoja de datos da la tensión máxima de salida (VOH) y la mínima (VOL) según la alimentación. Un LM358 a 9 V no pasa de unos 7,5 V; a 5 V, de unos 3,5 V. Si necesitas llegar casi a la alimentación, usa un operacional <b>rail-to-rail</b> como el MCP6002.', q: mcq('Un LM358 a 12 V debe dar 11,8 V a la salida. ¿Qué pasa?', ['No llega: se queda un voltio o más por debajo; usa un rail-to-rail', 'Llega sin problema', 'Llega a 24 V', 'Se invierte la salida'], 'Mira VOH en la hoja de datos.') }
  ] },
  bb_gbw: { name: 'Velocidad del operacional: GBW y slew rate', alts: [
    { title: 'Ganancia por ancho de banda', text: 'Un operacional no da la misma ganancia a todas las frecuencias: ganancia × ancho de banda ≈ constante, el <b>GBW</b>. Con 1 MHz de GBW, a ganancia 100 llega a unos 10 kHz; a ganancia 10, a 100 kHz. Mueve la ganancia y la frecuencia y mira dónde se dobla la curva.', tune: { viz: 'gbw', params: { gbw: { label: 'GBW del chip', val: 1, list: [1, 3, 10], unit: 'MHz', dec: 0 }, G: { label: 'Ganancia', val: 100, list: [1, 10, 100, 1000], dec: 0 }, f: { label: 'Frecuencia', val: 10, list: [0.1, 1, 10, 100, 1000], unit: 'kHz', dec: 1 } } }, q: mcq('GBW = 3 MHz y ganancia 30. ¿Ancho de banda?', ['100 kHz', '90 MHz', '3 MHz', '10 kHz'], '3 MHz / 30 = 100 kHz.') },
    { title: 'La pendiente máxima', text: 'El <b>slew rate</b> (SR) es lo más rápido que puede cambiar la salida, en V/µs. Una senoide de pico Vp y frecuencia f tiene una pendiente máxima de 2π · f · Vp; si supera el SR, sale triangular. <b>fmax = SR / (2π · Vp)</b>. Un LM358 (unos 0,3–0,6 V/µs) se queda corto con senoides grandes de decenas de kHz.', q: mcq('SR = 0,5 V/µs y una senoide de 4 V de pico. ¿Frecuencia máxima sin deformarse?', ['Unos 20 kHz', 'Unos 125 kHz', 'Unos 2 kHz', 'Unos 2 MHz'], '500 000 / (2π × 4) ≈ 19,9 kHz.') },
    { title: 'Repartir la ganancia', text: 'Si necesitas ×100 hasta 20 kHz con un chip de 1 MHz, una sola etapa no llega (BW = 10 kHz). Dos etapas de ×10 multiplican ×100 y cada una llega a 100 kHz. Es el truco habitual antes de cambiar de chip.', q: mcq('Chip de 2 MHz de GBW. ¿Qué ancho de banda tiene cada etapa si montas dos de ×20?', ['100 kHz', '50 kHz', '1 MHz', '20 kHz'], '2 MHz / 20 = 100 kHz por etapa.') }
  ] },
  bb_comp: { name: 'El comparador', alts: [
    { title: 'Quién gana', text: 'Sin realimentación, el operacional (o un comparador) solo mira qué entrada es mayor: si <b>IN+ > IN−</b>, salida alta; si IN+ < IN−, salida baja. No hay término medio. Mueve el umbral y la luz, y mira el LED.', tune: { viz: 'comparator', params: { luz: { label: 'Luz', val: 30, min: 0, max: 100, step: 5, unit: '%', dec: 0 }, Vref: { label: 'Umbral (IN−)', val: 2.5, min: 0, max: 5, step: 0.1, unit: 'V', dec: 1 }, ruido: { val: 0, fixed: true } } }, q: mcq('IN+ = 3 V e IN− = 1,5 V. ¿Salida?', ['Alta', 'Baja', 'A mitad', '4,5 V'], 'IN+ es mayor.') },
    { title: 'Señal contra referencia', text: 'Una entrada recibe la señal que vigilas (un divisor con una LDR, un termistor, la batería) y la otra una <b>referencia</b> fija, de un divisor o un potenciómetro. Al girar el potenciómetro mueves el umbral. Si la señal va a IN+, la salida sube cuando la señal supera la referencia; si va a IN−, al revés.', q: mcq('La señal de un termistor va a IN− y un potenciómetro a IN+. Cuando la señal supera la referencia, la salida…', ['Baja', 'Sube', 'No cambia', 'Oscila sin parar'], 'Ahora IN− > IN+.') }
  ] },
  bb_hystwhy: { name: 'Histéresis para limpiar señales', alts: [
    { title: 'Un termostato', text: 'Un termostato que encendiera y apagara a 20,0 °C conmutaría sin parar. Por eso enciende a 19 °C y apaga a 21 °C: dos umbrales. Un comparador con algo de realimentación positiva (un <b>Schmitt trigger</b>) hace lo mismo y el ruido cerca del umbral ya no lo hace temblar. Conviene una histéresis algo mayor que el ruido pico a pico, sin pasarse.', q: mcq('El ruido de tu sensor es de 0,2 V pico a pico. ¿Qué histéresis eliges?', ['Algo más, como 0,3 V', '0,05 V', 'Toda la posible, 5 V', 'Ninguna'], 'Un poco más que el ruido.') },
    { title: 'Velo con ruido de verdad', text: 'Aquí una señal ruidosa cruza dos umbrales. Con las líneas muy juntas, cada pico de ruido hace cambiar la salida; sepáralas (más R1 o menos R2) hasta que cada cruce cuente una sola vez, y verás que si te pasas la señal ya no llega al umbral de subida.', tune: { viz: 'schmittHyst', params: { R1: { label: 'R1', val: 1000, list: [1000, 2200, 4700, 10000, 22000, 47000], fmt: 'R' }, R2: { label: 'R2', val: 220000, list: [10000, 22000, 47000, 100000, 220000], fmt: 'R' } } }, q: mcq('Separas mucho los dos umbrales. ¿Qué arriesgas?', ['Que una señal pequeña no llegue a cruzarlos y pierdas sensibilidad', 'Que el ruido haga temblar la salida', 'Que se queme el comparador', 'Nada'], 'Mucha histéresis: limpia, pero sorda.') },
    { title: 'Rampas lentas', text: 'Una señal que sube despacio (la de un condensador que se carga, un sensor de temperatura) pasa un buen rato cerca del umbral, justo donde el ruido más molesta. Con un solo umbral da varios cambios; con dos, el primer cruce manda y los siguientes ya no cuentan: sale un único flanco limpio.', q: mcq('Una tensión sube muy despacio y con algo de ruido hasta cruzar el umbral de un comparador sin histéresis. ¿Qué verás a la salida?', ['Varios cambios seguidos al cruzar', 'Un único cambio limpio', 'Nada', 'Una rampa'], 'Mientras está cerca del umbral, el ruido lo cruza una y otra vez.') }
  ] },
  bb_schmitt_calc: { name: 'Umbrales del Schmitt trigger', alts: [
    { title: 'Las fórmulas', text: 'Schmitt no inversor con alimentación única: Vref a IN−, la entrada por R1 hasta IN+ y R2 de la salida a IN+. Con salida rail-to-rail: <b>histéresis = Vcc · R1 / R2</b>; umbral de subida = <b>Vref · (R1 + R2) / R2</b>; el de bajada = subida − histéresis. Más R1 o menos R2, más histéresis.', q: mcq('Vcc = 12 V, R1 = 10 kΩ y R2 = 100 kΩ. ¿Histéresis?', ['1,2 V', '0,12 V', '12 V', '0,83 V'], '12 × 10 / 100 = 1,2 V.') },
    { title: 'Un ejemplo completo', text: 'Vcc = 5 V, Vref = 2,5 V, R1 = 10 kΩ y R2 = 100 kΩ. Subida: 2,5 × 110 / 100 = 2,75 V. Histéresis: 5 × 10 / 100 = 0,5 V. Bajada: 2,75 − 0,5 = 2,25 V. Los umbrales quedan centrados en 2,5 V, a ±0,25 V. Compruébalo: con 10 kΩ y 100 kΩ las líneas roja y verde están a 2,75 y 2,25 V.', tune: { viz: 'schmittHyst', params: { R1: { label: 'R1', val: 10000, list: [1000, 2200, 4700, 10000, 22000, 47000], fmt: 'R' }, R2: { label: 'R2', val: 100000, list: [10000, 22000, 47000, 100000, 220000], fmt: 'R' } } }, q: mcq('Mismo circuito, pero R1 = 4,7 kΩ. ¿Umbral de subida?', ['Unos 2,62 V', 'Unos 2,5 V', 'Unos 2,75 V', 'Unos 2,38 V'], '2,5 × 104,7 / 100 ≈ 2,62 V.') }
  ] },
  bb_summer: { name: 'Sumador inversor', alts: [
    { title: 'Masa virtual', text: 'En el sumador, la entrada − se queda a 0 V (masa virtual) porque la + está a masa. Cada entrada mete una corriente Vi / Ri, todas pasan por Rf y <b>Vsal = −Rf · (V1/R1 + V2/R2 + …)</b>. Con todas las resistencias iguales, la salida es la suma cambiada de signo.', q: mcq('Rf = R1 = R2 = 10 kΩ, V1 = 0,5 V y V2 = 1,5 V. ¿Vsal?', ['−2 V', '2 V', '−1 V', '−0,75 V'], '−(0,5 + 1,5).') },
    { title: 'Corrientes que se juntan', text: 'Míralo como agua: cada entrada aporta su chorro (Vi / Ri) al mismo punto, y todo sale por Rf. La caída en Rf es la suma de chorros × Rf. Cambia las resistencias: la que tiene menos resistencia mete más corriente y pesa más.', tune: { viz: 'summer', params: { V1: { label: 'V1', val: 1, min: -2, max: 2, step: 0.1, unit: 'V', dec: 1 }, V2: { label: 'V2', val: 0.5, min: -2, max: 2, step: 0.1, unit: 'V', dec: 1 }, R1: { label: 'R1', val: 10000, list: [5000, 10000, 20000], fmt: 'R' }, R2: { label: 'R2', val: 5000, list: [5000, 10000, 20000], fmt: 'R' }, Rf: { label: 'Rf', val: 10000, list: [5000, 10000, 20000], fmt: 'R' } } }, q: mcq('Rf = 20 kΩ, R1 = 10 kΩ, R2 = 20 kΩ y V1 = V2 = 1 V. ¿Vsal?', ['−3 V', '−2 V', '−1,5 V', '3 V'], '−(2 × 1 + 1 × 1) = −3 V.') }
  ] },
  bb_diffamp: { name: 'Restador (amplificador diferencial)', alts: [
    { title: 'Amplificar la diferencia', text: 'Con cuatro resistencias (R1 = R3 y R2 = R4), <b>Vsal = (R2 / R1) · (V2 − V1)</b>. Solo cuenta la diferencia: si las dos entradas suben juntas (tensión común), la salida no cambia. Por eso va detrás de un puente de Wheatstone, cuyos dos puntos medios están a unos 2,5 V y difieren en milivoltios.', q: mcq('R2/R1 = 20, V2 = 1,52 V y V1 = 1,50 V. ¿Vsal?', ['0,4 V', '30,4 V', '0,02 V', '−0,4 V'], '20 × 0,02 = 0,4 V.') },
    { title: 'El emparejamiento importa', text: 'El rechazo de la tensión común depende de que las resistencias estén bien emparejadas. Pruébalo: con resistencias perfectas, mover la tensión común no cambia nada; con un 5 % de desajuste, parte de ella se cuela en la salida como si fuera señal. Para medir de verdad se usan resistencias del 0,1 % o un amplificador de instrumentación integrado (INA).', tune: { viz: 'diffAmp', params: { Vcm: { label: 'Tensión común', val: 2.5, min: 0, max: 5, step: 0.1, unit: 'V', dec: 1 }, Vd: { label: 'Diferencia', val: 10, list: [-50, -20, -10, 0, 10, 20, 50], unit: 'mV', dec: 0 }, G: { label: 'Ganancia', val: 10, list: [1, 10, 100], dec: 0 }, tol: { label: 'Desajuste', val: 5, list: [0, 0.1, 1, 5], unit: '%', dec: 1 } } }, q: mcq('La salida de tu restador cambia cuando las dos entradas suben a la vez. ¿Causa probable?', ['Resistencias mal emparejadas', 'Demasiada ganancia', 'Falta de offset', 'Que el operacional es rail-to-rail'], 'Con resistencias desiguales, la tensión común no se cancela del todo.') }
  ] },
  bb_integ: { name: 'Integrador y derivador', alts: [
    { title: 'Un cubo que se llena', text: 'En el integrador, la entrada mete una corriente Vent / R que carga el condensador de la realimentación. Con entrada constante, la salida es una rampa de pendiente <b>Vent / (R · C)</b>, con el signo cambiado. Una cuadrada son tramos constantes: sale triangular.', tune: { viz: 'integrator', params: { mode: { label: 'Entrada (0 continua, 1 cuadrada)', val: 0, list: [0, 1], dec: 0 }, Vin: { label: 'Amplitud', val: 1, list: [0.5, 1, 2], unit: 'V', dec: 1 }, R: { label: 'R', val: 10000, list: [10000, 47000, 100000], fmt: 'R' }, C: { label: 'C', val: 1, list: [0.1, 1, 10], unit: 'µF', dec: 1 } } }, q: mcq('R = 100 kΩ, C = 1 µF y 2 V a la entrada. ¿Pendiente (sin signo)?', ['20 V/s', '200 V/s', '2 V/s', '0,2 V/s'], '2 / (100 000 × 0,000001) = 20 V/s.') },
    { title: 'Tiempo = tensión / pendiente', text: 'Una vez tienes la pendiente, cualquier pregunta de tiempo sale dividiendo: para moverse ΔV, tarda ΔV / pendiente. Con 50 V/s, moverse 2 V lleva 2 / 50 = 0,04 s.', q: mcq('Un integrador con pendiente de 50 V/s. ¿Cuánto tarda en moverse 2 V?', ['40 ms', '25 s', '100 s', '4 ms'], '2 / 50 = 0,04 s.') },
    { title: 'Integrar y derivar son opuestos', text: 'El <b>derivador</b> (condensador a la entrada, R en la realimentación) da una salida proporcional a lo rápido que cambia la entrada: una triangular (rampas de pendiente fija) sale cuadrada. El integrador hace lo contrario: cuadrada → triangular. Y el integrador, visto en frecuencia, es un paso bajo con mucha ganancia.', q: mcq('¿Qué sale de un derivador si le metes una triangular?', ['Una cuadrada', 'Una triangular más grande', 'Una senoide', 'Nada'], 'Cada rampa tiene pendiente fija: salida constante en cada tramo.') }
  ] },
  bb_actfilt: { name: 'Filtros activos', alts: [
    { title: 'Un seguidor que protege al filtro', text: 'Si a un RC le cuelgas una carga, queda en paralelo y cambia su frecuencia de corte. Un operacional en seguidor detrás da una salida fuerte: el filtro ya no nota la carga y puedes encadenar etapas. El <b>Sallen-Key</b> es el de segundo orden más usado: con R iguales, <b>f₀ = 1 / (2π · R · √(C1 · C2))</b>.', q: mcq('Sallen-Key con R = 10 kΩ y C1 = C2 = 10 nF. ¿f₀?', ['Unos 1,6 kHz', 'Unos 16 kHz', 'Unos 160 Hz', 'Unos 10 kHz'], '1 / (2π × 10 000 × 10 nF) ≈ 1592 Hz.') },
    { title: 'La Q decide la forma', text: 'En un filtro de segundo orden, Q dice cómo es el codo: <b>Q ≈ 0,707</b> es Butterworth, lo más plano posible sin pico; con Q menor cae antes y más suave; con Q mayor aparece un pico. En el Sallen-Key con R iguales, Q ≈ ½ · √(C1 / C2). Cambia C1 y C2 y mira la curva.', tune: { viz: 'sallenKey', params: { R: { label: 'R', val: 10000, list: [4700, 10000, 22000], fmt: 'R' }, C1: { label: 'C1', val: 22, list: [10, 22, 47, 100, 220], unit: 'nF', dec: 0 }, C2: { label: 'C2', val: 10, list: [10, 22, 47], unit: 'nF', dec: 0 } } }, q: mcq('Un filtro de segundo orden tiene Q = 3. ¿Qué respuesta da?', ['Un pico marcado cerca de f₀', 'Plana (Butterworth)', 'Una caída muy suave sin pico', 'Ninguna atenuación'], 'Q alta: resonancia.') }
  ] },
  bb_antialias: { name: 'Antialiasing y cadena de medida', alts: [
    { title: 'La mitad de la frecuencia de muestreo', text: 'Si muestreas a fs muestras por segundo, solo puedes representar señales por debajo de <b>fs / 2</b> (Nyquist). Lo que esté por encima aparece disfrazado de una frecuencia baja que no existe (aliasing). Por eso delante del ADC va un paso bajo que lo quita.', q: mcq('Muestreas a 8000 muestras por segundo. ¿Hasta qué frecuencia puede llegar la señal?', ['4000 Hz', '8000 Hz', '16 000 Hz', '800 Hz'], 'La mitad de la frecuencia de muestreo.') },
    { title: 'El orden de la cadena', text: 'Una cadena de medida típica: <b>sensor → amplificador</b> (ganancia y desplazamiento para aprovechar el rango del ADC) <b>→ filtro paso bajo antialiasing → ADC</b>. Primero se adapta la señal, luego se limpia y al final se convierte.', q: mcq('¿Qué va justo antes del ADC en una cadena de medida?', ['El filtro paso bajo antialiasing', 'El sensor', 'El amplificador', 'Nada'], 'Se filtra justo antes de muestrear.') }
  ] },
  bb_linreg: { name: 'Regulador lineal: pérdidas y rendimiento', alts: [
    { title: 'Una resistencia automática', text: 'Un regulador lineal deja caer lo que sobra entre la entrada y la salida y lo convierte en calor: <b>P = (Vent − Vsal) · I</b>. Su rendimiento máximo es <b>Vsal / Vent</b>: de 12 a 5 V, un 42 %. Sube la entrada y la corriente y mira cómo crece el calor.', tune: { viz: 'linreg', params: { tipo: { label: 'Regulador (0 7805, 1 LDO 5 V, 2 LDO 3,3 V)', val: 0, list: [0, 1, 2], dec: 0 }, Vin: { label: 'Entrada', val: 12, min: 3, max: 15, step: 0.1, unit: 'V', dec: 1 }, I: { label: 'Corriente', val: 500, list: [50, 100, 200, 500, 1000], unit: 'mA', dec: 0 } } }, q: mcq('Regulador lineal de 9 V a 5 V con 300 mA. ¿Potencia en calor?', ['1,2 W', '1,5 W', '2,7 W', '0,4 W'], '(9 − 5) × 0,3 = 1,2 W.') },
    { title: 'Misma corriente dentro y fuera', text: 'Por un lineal entra la misma corriente que sale. Por eso el rendimiento depende solo de las tensiones: Pútil / Pent = (Vsal · I) / (Vent · I) = Vsal / Vent. Con 6 V de entrada y 5 V de salida, un 83 %; con 24 V de entrada, un 21 %.', q: mcq('Lineal de 15 V a 3,3 V. ¿Rendimiento máximo?', ['Un 22 %', 'Un 78 %', 'Un 45 %', 'Un 100 %'], '3,3 / 15 = 0,22.') }
  ] },
  bb_chips: { name: 'Chips lógicos y de apoyo', alts: [
    { title: 'Una caja de herramientas', text: '<b>74HC00</b>: cuatro NAND. <b>74HC14</b>: seis inversores Schmitt. <b>CD4017</b>: contador con 10 salidas que se encienden por turnos. <b>ULN2003</b>: siete drivers Darlington para relés y motores. En los DIP-14 lógicos, la pata 14 es VCC y la 7, masa.', svg: '<svg viewBox="0 0 300 150" class="viz"><rect x="100" y="15" width="100" height="120" rx="4" fill="#1c1c1c"/><path d="M140 15a10 10 0 0 0 20 0" fill="var(--bg)"/><text x="150" y="80" text-anchor="middle" fill="#ddd" font-size="11">74HC00</text><text x="92" y="128" text-anchor="end" class="vizlab">7 masa</text><text x="208" y="30" class="vizlab">14 VCC</text><path d="M200 26h10M90 124h10" stroke="#9AA3B2" stroke-width="6"/></svg>', q: mcq('Necesitas encender 10 LEDs por turnos, uno por cada pulso de reloj. ¿Qué chip?', ['CD4017', '74HC00', 'ULN2003', '7805'], 'Contador con 10 salidas.') },
    { title: 'Nada al aire', text: 'Una entrada CMOS sin conectar flota: lee ruido, puede quedarse a medio camino y hacer que el chip consuma de más y se caliente. Las entradas sin usar se unen a <b>masa o a VCC</b>, directamente o con una resistencia. Las salidas sin usar sí se dejan libres.', q: mcq('Usas tres de las cuatro NAND de un 74HC00. ¿Qué haces con las entradas de la cuarta?', ['Unirlas a masa o a VCC', 'Dejarlas al aire', 'Unirlas a su salida', 'Cortarlas'], 'Ninguna entrada CMOS al aire.') }
  ] },
  /* --- Curso base m11: electrónica digital --- */
  bb_bin: { name: 'Binario ↔ decimal', alts: [
    { title: 'Pesos', text: 'Escribe encima de cada bit su peso, de derecha a izquierda: 1, 2, 4, 8, 16, 32, 64, 128. Para leer un binario, suma los pesos de los unos: 1010 0101 = 128 + 32 + 4 + 1 = 165. Para escribir un número, ve restando el peso más grande que quepa: 100 = 64 + 32 + 4 → 0110 0100.', q: mcq('¿Cuánto vale 0100 1001?', ['73', '37', '145', '9'], '64 + 8 + 1 = 73.') },
    { title: 'Mitades', text: 'Para pasar de decimal a binario sin tabla: divide entre 2 y apunta el resto, una y otra vez; los restos, leídos de abajo arriba, son los bits. 13 → 6 resto 1 → 3 resto 0 → 1 resto 1 → 0 resto 1: <b>1101</b>. Comprueba sumando pesos: 8 + 4 + 1 = 13.', q: mcq('¿Cómo se escribe 22 en binario?', ['10110', '01101', '10011', '11010'], '16 + 4 + 2 = 22.') }
  ] },
  bb_nbits: { name: 'Cuántos valores caben en n bits', alts: [
    { title: 'Cada bit dobla', text: 'Con 1 bit hay 2 valores; cada bit más los duplica: con n bits hay <b>2ⁿ</b> valores, del 0 al 2ⁿ − 1. 8 bits: 256 (de 0 a 255). Para contar de 0 a 15 (16 valores) hacen falta 4 bits, es decir, 4 biestables.', svg: '<svg viewBox="0 0 300 120" class="viz"><text x="20" y="30" class="vizlab">1 bit</text><text x="110" y="30" class="vizsm">0 1</text><text x="20" y="55" class="vizlab">2 bits</text><text x="110" y="55" class="vizsm">00 01 10 11</text><text x="20" y="80" class="vizlab">3 bits</text><text x="110" y="80" class="vizsm">000 001 010 011 100 101 110 111</text><text x="20" y="108" class="vizsm">2 → 4 → 8: cada bit más, el doble de valores</text></svg>', q: mcq('¿Cuántos bits necesitas para contar de 0 a 63?', ['6', '63', '64', '8'], '64 valores = 2⁶.') },
    { title: 'Al revés: cuántos bits', text: 'Busca la primera potencia de 2 que llegue a los valores que necesitas: 10 valores → 2⁴ = 16 → 4 bits; 100 valores → 2⁷ = 128 → 7 bits. Ojo: el valor más alto es 2ⁿ − 1, porque el 0 también cuenta.', q: mcq('¿Cuántos valores distintos caben en 10 bits?', ['1024', '1023', '100', '20'], '2¹⁰ = 1024 (de 0 a 1023).') }
  ] },
  bb_hex: { name: 'Hexadecimal', alts: [
    { title: 'Dieciséis cifras', text: 'El hexadecimal tiene 16 cifras: 0–9 y luego A = 10, B = 11, C = 12, D = 13, E = 14, F = 15. Cada cifra son exactamente <b>4 bits</b> (2⁴ = 16), así que un byte se escribe con dos cifras: 1111 0011 = 0xF3. Mueve las dos cifras y mira los bits.', tune: { viz: 'hexNibble', params: { hi: { label: 'Cifra alta', val: 15, min: 0, max: 15, step: 1, dec: 0 }, lo: { label: 'Cifra baja', val: 3, min: 0, max: 15, step: 1, dec: 0 } } }, q: mcq('¿Cuánto vale la cifra hexadecimal E?', ['14', '15', '13', '5'], 'A10 B11 C12 D13 E14 F15.') },
    { title: 'Pasar a decimal', text: 'La cifra de la izquierda vale 16 veces su valor: <b>0xB7 = 11 × 16 + 7 = 183</b>. Al revés, divide entre 16: el cociente es la primera cifra y el resto, la segunda (200 = 12 × 16 + 8 → 0xC8).', q: mcq('¿Cuánto vale 0x2A en decimal?', ['42', '210', '32', '26'], '2 × 16 + 10 = 42.') }
  ] },
  bb_gates: { name: 'Puertas lógicas y tablas de verdad', alts: [
    { title: 'Interruptores', text: '<b>AND</b>: interruptores en serie, 1 solo si todas las entradas son 1. <b>OR</b>: en paralelo, 1 si alguna es 1. <b>NOT</b> invierte. <b>NAND</b> y <b>NOR</b> son AND y OR con la salida invertida. <b>XOR</b>: 1 solo si las entradas son distintas. Pruébalas.', tune: { viz: 'gateSw', params: { A: { label: 'A', val: 1, list: [0, 1], dec: 0 }, B: { label: 'B', val: 0, list: [0, 1], dec: 0 }, g: { label: 'Puerta (0 AND, 1 OR, 2 NOT, 3 NAND, 4 NOR, 5 XOR)', val: 4, list: [0, 1, 2, 3, 4, 5], dec: 0 } } }, q: mcq('Una NOR con A = 0 y B = 0 da…', ['1', '0', 'Depende del reloj', 'A'], 'La OR daría 0; invertida, 1.') },
    { title: 'Rellenar la tabla fila a fila', text: 'Con dos entradas hay cuatro combinaciones: 00, 01, 10 y 11. Para cada una, calcula primero la puerta básica (AND u OR) y, si es NAND o NOR, invierte el resultado. NAND: 00 → 1, 01 → 1, 10 → 1, 11 → 0. XOR: 00 → 0, 01 → 1, 10 → 1, 11 → 0.', q: mcq('XOR con A = 1 y B = 1 da…', ['0', '1', '2', 'Indeterminado'], 'Iguales → 0.') }
  ] },
  bb_boole: { name: 'Álgebra de Boole', alts: [
    { title: 'Reglas que se ven con interruptores', text: 'AND es como multiplicar: <b>A · 0 = 0</b> (un interruptor abierto en serie lo corta todo) y A · 1 = A. OR es como sumar, pero 1 + 1 sigue siendo 1: <b>A + 1 = 1</b> (uno cerrado en paralelo deja pasar siempre) y A + 0 = A.', q: mcq('A · 1 =', ['A', '1', '0', 'Ā'], 'Un interruptor cerrado en serie no cambia nada.') },
    { title: 'De Morgan, comprobado', text: 'De Morgan: <b>(A·B)‾ = Ā + B̄</b> y <b>(A+B)‾ = Ā · B̄</b>: al invertir, AND pasa a OR y cada entrada se invierte. Compruébalo: cambia A y B y verás que los dos circuitos dan siempre lo mismo. Por eso una NAND es una OR con entradas invertidas.', tune: { viz: 'deMorgan', params: { A: { label: 'A', val: 0, list: [0, 1], dec: 0 }, B: { label: 'B', val: 1, list: [0, 1], dec: 0 }, ley: { label: 'Comparar (0 NAND, 1 NOR)', val: 0, list: [0, 1], dec: 0 } } }, q: mcq('Por De Morgan, (A+B)‾ es…', ['Ā · B̄', 'Ā + B̄', 'A · B', 'A + B'], 'La OR invertida es una AND de las entradas invertidas.') }
  ] },
  bb_combi: { name: 'Bloques combinacionales', alts: [
    { title: 'Tres bloques', text: '<b>Decodificador</b>: n entradas activan una de <b>2ⁿ</b> salidas (3 bits → 8 salidas). <b>Multiplexor</b>: elige una de varias entradas con unas líneas de selección; para 2ⁿ entradas hacen falta n líneas (4 entradas → 2). Mueve la selección y mira qué entrada pasa.', tune: { viz: 'mux4', params: { D: { label: 'Datos', val: 6, min: 0, max: 15, step: 1, dec: 0 }, S1: { label: 'S1', val: 0, list: [0, 1], dec: 0 }, S0: { label: 'S0', val: 1, list: [0, 1], dec: 0 } } }, q: mcq('Un multiplexor de 8 entradas, ¿cuántas líneas de selección?', ['3', '8', '2', '4'], '2³ = 8.') },
    { title: 'Sumar en binario', text: 'Sumar dos bits: 0 + 0 = 0; 0 + 1 = 1; 1 + 1 = 10 en binario, es decir, suma 0 y te llevas 1. La suma es una XOR (1 si son distintos) y el acarreo, una AND (1 si los dos son 1).', q: mcq('Semisumador con A = 1 y B = 0. ¿Resultado?', ['Suma 1, acarreo 0', 'Suma 0, acarreo 1', 'Suma 1, acarreo 1', 'Suma 0, acarreo 0'], 'XOR = 1; AND = 0.') }
  ] },
  bb_latch: { name: 'Biestables: memoria de un bit', alts: [
    { title: 'Puertas que recuerdan', text: 'Un circuito <b>combinacional</b> solo depende de las entradas de ahora; uno <b>secuencial</b> también de lo que pasó antes. Dos NAND cruzadas forman un biestable SR con entradas S̄ y R̄ activas a nivel <b>bajo</b>: un pulso a 0 en S̄ pone Q a 1 y se queda así. Pruébalo: pulsa S̄ y luego suéltalo.', tune: { viz: 'latchSR', params: { Sn: { label: 'S̄ (1 suelto, 0 pulsado)', val: 1, list: [0, 1], dec: 0 }, Rn: { label: 'R̄ (1 suelto, 0 pulsado)', val: 1, list: [0, 1], dec: 0 } } }, q: mcq('En un SR con NAND, ¿qué pone la salida a 1?', ['Un pulso a 0 en S̄', 'Un pulso a 1 en S̄', 'Un pulso a 0 en R̄', 'Dejar las dos entradas a 1'], 'Entradas activas a nivel bajo.') },
    { title: 'Una foto en el flanco', text: 'El <b>biestable D</b> es una cámara: en cada <b>flanco del reloj</b> copia lo que haya en D a la salida Q y lo mantiene hasta el flanco siguiente, cambie D lo que cambie entretanto. Encadenándolos se hacen registros y contadores.', q: mcq('D cambia de 0 a 1 entre dos flancos de reloj. ¿Cuándo cambia Q?', ['En el siguiente flanco de reloj', 'En cuanto cambia D', 'Nunca', 'Al quitar la alimentación'], 'Solo captura en el flanco.') }
  ] },
  /* --- Curso base m13: alimentación --- */
  bb_battlife: { name: 'Autonomía de una batería', alts: [
    { title: 'Un depósito que se vacía', text: 'La capacidad en mAh dice cuántos miliamperios puede dar durante una hora. Para saber cuánto dura: <b>horas ≈ capacidad (mAh) / consumo (mA)</b>. 2000 mAh con 100 mA: unas 20 h. En la práctica, algo menos: la capacidad baja con consumos altos, con el frío y con la edad.', q: mcq('Batería de 1000 mAh y consumo de 50 mA. ¿Horas aproximadas?', ['20 h', '50 000 h', '0,05 h', '950 h'], '1000 / 50 = 20 h.') },
    { title: 'Mismas unidades', text: 'Divide miliamperios-hora entre miliamperios y te quedan horas. Si el consumo te lo dan en amperios, pásalo antes a mA: 2500 mAh con 0,25 A son 2500 / 250 = 10 h. Si el consumo cambia (un sensor que duerme y despierta), usa el consumo medio.', q: mcq('Batería de 2500 mAh y consumo de 0,5 A. ¿Horas aproximadas?', ['5 h', '5000 h', '1250 h', '0,2 h'], '0,5 A = 500 mA; 2500 / 500 = 5 h.') }
  ] },
  bb_cells: { name: 'Pilas: tensión, serie y paralelo', alts: [
    { title: 'Serie suma voltios, paralelo suma capacidad', text: 'Pilas iguales en <b>serie</b> suman tensión con la misma capacidad: dos celdas de litio (2S) dan 7,4 V nominales y 8,4 V llenas (2 × 4,2). En <b>paralelo</b> mantienen la tensión y suman capacidad (mAh). Solo se juntan pilas iguales y con la misma carga.', svg: '<svg viewBox="0 0 300 140" class="viz"><rect x="20" y="40" width="24" height="50" rx="4" fill="var(--ice)"/><rect x="50" y="40" width="24" height="50" rx="4" fill="var(--ice)"/><rect x="80" y="40" width="24" height="50" rx="4" fill="var(--ice)"/><text x="62" y="110" text-anchor="middle" class="vizlab">3 en serie</text><text x="62" y="128" text-anchor="middle" class="vizsm">3 × la tensión · misma capacidad</text><rect x="190" y="25" width="70" height="22" rx="4" fill="var(--led)"/><rect x="190" y="53" width="70" height="22" rx="4" fill="var(--led)"/><rect x="190" y="81" width="70" height="22" rx="4" fill="var(--led)"/><text x="225" y="120" text-anchor="middle" class="vizlab">3 en paralelo</text><text x="225" y="136" text-anchor="middle" class="vizsm">misma tensión · 3 × mAh</text></svg>', q: mcq('Tres celdas de litio en serie (3S), llenas. ¿Tensión?', ['12,6 V', '11,1 V', '4,2 V', '8,4 V'], '3 × 4,2 V; 11,1 V es la nominal.') },
    { title: 'La tensión dice la carga', text: 'Medida en vacío, la tensión de una pila indica más o menos cuánto le queda. Una pila de 9 V nueva da algo más de 9 V y está gastada por debajo de unos 7 V; una celda de litio va de 4,2 V llena a unos 3 V vacía. Mueve la carga en la curva de la Li-ion y mírala.', tune: { viz: 'dischargeCurve', params: { q: { label: 'Química (0 alcalina, 1 NiMH, 2 Li-ion, 3 LiFePO4)', val: 2, list: [0, 1, 2, 3], dec: 0 }, carga: { label: 'Carga que queda', val: 100, min: 0, max: 100, step: 5, unit: '%', dec: 0 } } }, q: mcq('Mides una pila de 9 V y marca 7,2 V. ¿Cómo está?', ['Casi gastada', 'Nueva', 'Sobrecargada', 'Puesta al revés'], 'Nueva daría más de 9 V.') },
    { title: 'Nominal no es llena', text: 'La tensión «nominal» que pone la etiqueta es la media de la descarga. Una Li-ion «de 3,7 V» llena marca 4,2 V; una alcalina «de 1,5 V» nueva, 1,6 V. Para packs en serie, multiplica por el número de celdas: 3S son 11,1 V nominales y 12,6 V llenas.', q: mcq('Un pack 4S de Li-ion lleno, ¿qué tensión tiene?', ['16,8 V', '14,8 V', '4,2 V', '12,6 V'], '4 × 4,2 V.') }
  ] },
  bb_lisafe: { name: 'Seguridad con baterías de litio', alts: [
    { title: 'Límites que no se negocian', text: 'Una celda de litio guarda mucha energía y puede incendiarse. No la cargues por encima de su tensión final (4,2 V en la mayoría; algunas, 4,35 V). No la cargues <b>por debajo de 0 °C</b> (se deposita litio metálico dentro). Si se hincha, deja de usarla y llévala a reciclar. Nunca la cortocircuites ni la perfores.', svg: '<svg viewBox="0 0 300 110" class="viz"><path d="M150 12L250 95H50Z" fill="var(--err-soft)" stroke="var(--err)" stroke-width="3" stroke-linejoin="round"/><text x="150" y="80" text-anchor="middle" font-size="44" font-weight="800" fill="var(--err)" class="a-pulse">!</text></svg>', q: mcq('Una LiPo de un dron está algo hinchada. ¿Qué haces?', ['Dejar de usarla y llevarla a reciclar', 'Pincharla para desinflarla', 'Cargarla más despacio', 'Usarla hasta que se apague'], 'Una celda hinchada puede arder.') },
    { title: 'Mira la carga en la gráfica', text: 'El cargador de litio sube la tensión con corriente constante y, al llegar a 4,2 V, la clava ahí y deja que la corriente baje. Nunca pasa de 4,2 V: si lo hiciera, la celda se degradaría y se calentaría. Avanza el tiempo y mira cómo la tensión se aplana en 4,2 V.', tune: { viz: 'cccv', params: { cap: { label: 'Capacidad', val: 2000, list: [1000, 2000, 3000], unit: 'mAh', dec: 0 }, rate: { label: 'Tasa', val: 0.5, list: [0.2, 0.5, 1], unit: 'C', dec: 1 }, t: { label: 'Tiempo', val: 1, min: 0, max: 6, step: 0.1, unit: 'h', dec: 1 } } }, q: mcq('¿Qué pasa si cargas hasta 4,4 V una celda de 4,2 V?', ['Se degrada deprisa y aumenta el riesgo de incendio', 'Guarda más energía sin problema', 'Nada', 'Se descarga'], 'La tensión final es un límite.') },
    { title: 'Antes de cargar una celda recuperada', text: 'Inspecciónala: sin golpes, hinchazón ni fugas. Mide su tensión: por debajo de unos 2,5 V, mejor reciclarla. Busca su corriente máxima de carga. Cárgala vigilada sobre una superficie no inflamable y tócala de vez en cuando: como mucho, templada.', q: mcq('Una celda de litio recuperada marca 1,2 V. ¿Qué haces?', ['Reciclarla: se ha descargado demasiado', 'Cargarla a tope enseguida', 'Cargarla a 2C para recuperarla', 'Ponerla en paralelo con una llena'], 'Tras una descarga profunda, cargarla es arriesgado.') }
  ] },
  bb_crate: { name: 'Corriente de carga (tasa C)', alts: [
    { title: 'Qué es 1C', text: '<b>1C</b> es la corriente que vaciaría (o llenaría) la celda en una hora: para 2000 mAh, 2000 mA; 0,5C son 1000 mA. El tiempo mínimo de carga en corriente constante es <b>capacidad / corriente</b>; la fase final a tensión constante añade bastante más. Cambia capacidad y tasa y mira la corriente programada.', tune: { viz: 'cccv', params: { cap: { label: 'Capacidad', val: 2000, list: [1000, 2000, 3000], unit: 'mAh', dec: 0 }, rate: { label: 'Tasa', val: 0.5, list: [0.2, 0.5, 1], unit: 'C', dec: 1 }, t: { label: 'Tiempo', val: 0.5, min: 0, max: 6, step: 0.1, unit: 'h', dec: 1 } } }, q: mcq('Celda de 1500 mAh. ¿Corriente a 0,5C?', ['750 mA', '1500 mA', '3000 mA', '75 mA'], '0,5 × 1500 mA.') },
    { title: 'Fijar la corriente del TP4056', text: 'En el TP4056, la resistencia de la pata PROG fija la corriente de carga: <b>I ≈ 1200 / RPROG</b>, o sea, <b>RPROG = 1200 / I</b> (I en amperios). 1,2 kΩ → 1 A; 2,4 kΩ → 500 mA. Elige una corriente que no pase de la máxima de carga de tu celda.', q: mcq('¿Qué RPROG da 600 mA en un TP4056?', ['2 kΩ', '720 Ω', '1,2 kΩ', '500 Ω'], '1200 / 0,6 = 2000 Ω.') }
  ] },
  bb_libms: { name: 'Cargador y protección de la celda', alts: [
    { title: 'Cargar no es proteger', text: 'El <b>cargador</b> (TP4056) controla la carga: corriente constante y luego 4,2 V fijos. La <b>protección</b> (un DW01A con dos MOSFET, o un BMS) corta si la tensión baja de unos 2,5 V, sube de unos 4,3 V o la corriente se dispara. En un módulo TP4056 con protección, B+/B− van a la celda y tu circuito se conecta en <b>OUT+/OUT−</b>.', svg: '<svg viewBox="0 0 300 120" class="viz"><rect x="20" y="40" width="60" height="40" rx="6" fill="var(--led)"/><text x="50" y="65" text-anchor="middle" class="vizlab" style="fill:#14213D">celda</text><rect x="110" y="35" width="80" height="50" rx="6" fill="var(--ice-soft)" stroke="var(--ice)"/><text x="150" y="58" text-anchor="middle" class="vizsm" style="fill:currentColor">DW01A +</text><text x="150" y="72" text-anchor="middle" class="vizsm" style="fill:currentColor">2 MOSFET</text><path d="M80 60H110M190 60H280" stroke="currentColor" stroke-width="2.2"/><text x="95" y="52" text-anchor="middle" class="vizsm">B±</text><text x="280" y="52" text-anchor="end" class="vizlab">OUT±</text><text x="150" y="110" text-anchor="middle" class="vizsm">tu circuito, siempre detrás de la protección</text></svg>', q: mcq('Conectas tu circuito a B+/B− de un módulo TP4056 con protección. ¿Qué pierdes?', ['La protección contra descarga profunda y cortocircuito', 'Nada', 'La carga por USB', 'La tensión de 4,2 V'], 'B± es la celda sin proteger.') },
    { title: 'Nada directo a la celda', text: 'Una celda de litio solo se carga con un cargador de litio. Una fuente o una placa solar «de 5 o 6 V» puede dar bastante más de 4,2 V y la sobrecargaría; además, sin un diodo, la celda podría descargarse hacia atrás. Entre la fuente y la celda, siempre un cargador de litio.', q: mcq('Quieres cargar una celda de litio con una fuente de 5 V. ¿Qué necesitas?', ['Un cargador de litio entre la fuente y la celda', 'Nada: conectarla directa', 'Solo un diodo', 'Un condensador grande'], 'El cargador limita a 4,2 V y controla la corriente.') }
  ] },
  bb_smps_pick: { name: 'Conmutados frente a lineales', alts: [
    { title: 'Cada caso, su regulador', text: '<b>Buck</b>: baja la tensión con un 85–95 % de rendimiento. <b>Boost</b>: la sube (3,7 V → 5 V). <b>Buck-boost</b>: sube o baja, para entradas que cruzan la salida (3–4,2 V → 3,3 V). <b>Lineal</b>: simple y sin ruido, bueno con poca corriente o poca diferencia de tensión. Mueve la fuente y lo que necesitas y mira qué tipo pide.', tune: { viz: 'buckBoost', params: { Va: { label: 'Fuente: tensión llena', val: 4.2, min: 0.5, max: 15, step: 0.1, unit: 'V', dec: 1 }, Vb: { label: 'Fuente: tensión vacía', val: 3, min: 0.5, max: 15, step: 0.1, unit: 'V', dec: 1 }, Vo: { label: 'Necesitas', val: 5, list: [3.3, 5, 12], unit: 'V', dec: 1 } } }, q: mcq('Necesitas 12 V desde una celda de litio. ¿Qué regulador?', ['Un boost', 'Un buck', 'Un 7812 lineal', 'Un LDO'], 'Hay que subir la tensión.') },
    { title: 'La eficiencia con números', text: 'El rendimiento es Psal / Pent. Si un buck al 90 % entrega 5 V y 2 A (10 W), la entrada debe dar <b>Pent = Psal / η</b> = 10 / 0,9 ≈ 11,1 W; la diferencia, 1,1 W, se va en calor. Un lineal haciendo lo mismo desde 12 V perdería 14 W. La pega de los conmutados es el ruido: a veces se pone un LDO detrás.', q: mcq('Boost al 85 % que entrega 5 V y 1 A. ¿Potencia de entrada?', ['Unos 5,9 W', '5 W', 'Unos 4,25 W', '8,5 W'], '5 / 0,85 ≈ 5,9 W.') }
  ] },
  bb_buck: { name: 'Dimensionar el buck: D, rizado y bobina', alts: [
    { title: 'Trocear y alisar', text: 'En el buck ideal, <b>D = Vsal / Vent</b>. La corriente de la bobina sube y baja en cada ciclo: <b>ΔI = (Vent − Vsal) · D / (L · f)</b>. Más inductancia o más frecuencia, menos rizado. Cambia la bobina y la frecuencia y mira el triángulo.', tune: { viz: 'buckDesign', params: { Vin: { label: 'Entrada', val: 12, list: [9, 12, 24], unit: 'V', dec: 0 }, Vout: { label: 'Salida', val: 5, list: [3.3, 5], unit: 'V', dec: 1 }, Iout: { label: 'Corriente de salida', val: 2, list: [0.5, 1, 2], unit: 'A', dec: 1 }, f: { label: 'Frecuencia', val: 500, list: [150, 500, 1000], unit: 'kHz', dec: 0 }, L: { label: 'Bobina', val: 10, list: [2.2, 4.7, 10, 22, 47], unit: 'µH', dec: 1 } } }, q: mcq('Buck ideal de 24 V a 6 V. ¿Ciclo de trabajo?', ['25 %', '75 %', '400 %', '18 %'], '6 / 24 = 0,25.') },
    { title: 'Elegir la bobina', text: 'Se elige un rizado ΔI del 20–40 % de la corriente de salida y se despeja <b>L = (Vent − Vsal) · D / (ΔI · f)</b>. La bobina debe aguantar sin saturarse el <b>pico</b>: corriente media + ΔI / 2, con margen. 12 → 5 V a 2 A con ΔI = 0,6 A: pico de 2,3 A.', q: mcq('Salida de 3 A con ΔI = 1 A. ¿Corriente de pico en la bobina?', ['3,5 A', '3 A', '4 A', '1 A'], '3 + 1/2.') },
    { title: 'Proporciones', text: 'Sin hacer la cuenta entera: el rizado es inversamente proporcional a L y a f. Doble de inductancia, mitad de rizado; doble de frecuencia, mitad de rizado. Por eso un buck de 1 MHz usa bobinas la mitad de grandes que uno de 500 kHz.', q: mcq('Un buck tiene 0,8 A de rizado con 10 µH. ¿Y con 22 µH (misma frecuencia)?', ['Unos 0,36 A', 'Unos 1,8 A', '0,8 A', 'Unos 0,08 A'], '0,8 × 10 / 22 ≈ 0,36 A.') }
  ] },
  bb_buckreal: { name: 'El buck en la práctica', alts: [
    { title: 'Dónde se va el rendimiento', text: 'Pérdidas de un buck: la Rds(on) del MOSFET (I² · R), el diodo (Vf · I mientras conduce), el hilo de la bobina y las conmutaciones. Con salidas bajas, los 0,3–0,5 V de un Schottky pesan mucho frente a 3,3 V: por eso los buck <b>síncronos</b> cambian el diodo por un segundo MOSFET que apenas cae.', q: mcq('¿Por qué un buck síncrono rinde más con salidas de 1,8 V?', ['Su segundo MOSFET cae mucho menos que un diodo', 'Porque conmuta más despacio', 'Porque no tiene bobina', 'No rinde más'], 'La caída del diodo sería una parte grande de la salida.') },
    { title: 'Rizado de tensión y bucle crítico', text: 'El rizado de corriente ΔI, al atravesar el condensador de salida, da un rizado de tensión de unos <b>ΔI · ESR</b>: 1 A con 10 mΩ son 10 mV. Y el bucle por el que circulan los pulsos (condensador de entrada, MOSFET y diodo) debe ser mínimo en la PCB, porque radia ruido.', svg: '<svg viewBox="0 0 300 120" class="viz"><rect x="60" y="25" width="50" height="30" rx="4" fill="var(--ice-soft)" stroke="var(--ice)"/><text x="85" y="44" text-anchor="middle" class="vizsm" style="fill:currentColor">C ent.</text><rect x="125" y="25" width="50" height="30" rx="4" fill="var(--ice-soft)" stroke="var(--ice)"/><text x="150" y="44" text-anchor="middle" class="vizsm" style="fill:currentColor">MOSFET</text><rect x="125" y="70" width="50" height="30" rx="4" fill="var(--ice-soft)" stroke="var(--ice)"/><text x="150" y="89" text-anchor="middle" class="vizsm" style="fill:currentColor">diodo</text><path d="M110 40H125M150 55V70M125 85H85V55" fill="none" stroke="var(--err)" stroke-width="3" class="a-flow"/><text x="200" y="66" class="vizsm" style="fill:var(--err)">bucle mínimo</text></svg>', q: mcq('ΔI = 0,4 A y condensador de salida con 50 mΩ de ESR. ¿Rizado por la ESR?', ['20 mV', '8 mV', '125 mV', '0,2 mV'], '0,4 × 0,05 = 0,02 V.') }
  ] },
  bb_capenergy: { name: 'Energía guardada en un condensador', alts: [
    { title: 'Con el cuadrado de la tensión', text: 'La energía de un condensador es <b>E = ½ · C · V²</b>, con faradios y voltios. 10 F a 2,7 V: ½ × 10 × 7,29 ≈ 36 J. Parece mucho, pero una celda de litio de 2000 mAh y 3,7 V guarda unos 26 600 J. Un supercondensador da picos de potencia, aguanta cientos de miles de ciclos y no arde: ideal para mantener un reloj o una memoria en un corte, no para alimentar algo todo el día.', q: mcq('5 F a 2,5 V. ¿Energía?', ['Unos 15,6 J', 'Unos 6,25 J', 'Unos 31 J', 'Unos 12,5 J'], '½ × 5 × 6,25 ≈ 15,6 J.') },
    { title: 'Solo cuenta la parte útil', text: 'La tensión va al cuadrado: el doble de tensión, cuatro veces más energía. Y al descargarse la tensión baja: si tu circuito deja de funcionar por debajo de V2, solo aprovechas <b>½ · C · (V1² − V2²)</b>. 10 F de 2,7 a 1,8 V: ½ × 10 × (7,29 − 3,24) ≈ 20 J, poco más de la mitad del total.', q: mcq('1 F de 5 V a 3 V. ¿Energía útil?', ['8 J', '2 J', '12,5 J', '4,5 J'], '½ × 1 × (25 − 9) = 8 J.') }
  ] },
  bb_solar: { name: 'Energía solar pequeña', alts: [
    { title: 'Hacer el balance', text: 'Calcula lo que entra y lo que sale cada día, en mAh. Entra: corriente de la placa × horas útiles de sol (en invierno, pocas). Sale: consumo medio × 24 h. Con 100 mA durante 3 h entran 300 mAh; un sensor de 2 mA gasta 48 mAh: hay margen para pérdidas y días nublados.', q: mcq('Una placa da 60 mA durante 2 h al día. ¿Cuántos mAh entran?', ['120 mAh', '30 mAh', '62 mAh', '1440 mAh'], '60 × 2 = 120 mAh.') },
    { title: 'MPPT: buscar el máximo', text: 'Una placa solar se comporta casi como una fuente de corriente que depende de la luz: su potencia cambia con la tensión a la que la hagas trabajar, y hay un punto que da el máximo. Un cargador con <b>MPPT</b> ajusta esa tensión continuamente. Cambia la carga y la luz y busca el círculo.', tune: { viz: 'solarIV', params: { luz: { label: 'Luz', val: 100, min: 10, max: 100, step: 5, unit: '%', dec: 0 }, R: { label: 'Carga', val: 22, list: [5, 10, 22, 33, 39, 47, 68, 100, 150, 220], fmt: 'R' } } }, q: mcq('¿Qué hace un cargador MPPT?', ['Hace trabajar la placa en el punto de su curva que da más potencia', 'Protege la batería del frío', 'Convierte la continua en alterna', 'Mide la temperatura de la placa'], 'Seguimiento del punto de máxima potencia.') }
  ] },
  /* --- Curso base: generadores compartidos con m2 y m6 --- */
  bb_eseries: { name: 'Elegir el valor comercial', alts: [
    { title: 'Solo existen algunos valores', text: 'Las resistencias se fabrican en series de valores: la <b>E12</b> tiene 12 por década: 10, 12, 15, 18, 22, 27, 33, 39, 47, 56, 68 y 82 (y sus múltiplos por 10). Si el cálculo te da un valor que no existe, elige el de la serie más cercano en el sentido seguro.', q: mcq('¿Cuál de estos valores pertenece a la serie E12?', ['390 Ω', '400 Ω', '350 Ω', '300 Ω'], '39 × 10 = 390.') },
    { title: 'Hacia arriba, si limita corriente', text: 'Si la resistencia limita la corriente de un LED, redondea <b>hacia arriba</b>: un poco más de resistencia da un poco menos de corriente, que es seguro; un poco menos la daría de más. Te sale 195 Ω → 220 Ω; 300 Ω → 330 Ω.', q: mcq('Te sale 250 Ω para un LED. ¿Qué valor E12 eliges?', ['270 Ω', '220 Ω', '2,7 kΩ', '22 Ω'], 'El siguiente hacia arriba.') }
  ] },
  bb_capcode: { name: 'Código de los condensadores', alts: [
    { title: 'Dos cifras y ceros, en pF', text: 'Los condensadores cerámicos llevan tres cifras: las dos primeras son el valor y la tercera, cuántos ceros añadir, en <b>picofaradios</b>. 104 = 10 seguido de 4 ceros = 100 000 pF = <b>100 nF</b>. 473 = 47 000 pF = 47 nF.', q: mcq('Un condensador pone «222». ¿Cuánto vale?', ['2,2 nF', '222 pF', '22 nF', '2,2 µF'], '22 y dos ceros: 2200 pF = 2,2 nF.') },
    { title: 'Pasar de pF a nF y µF', text: 'Cuando tengas los picofaradios, divide entre 1000 para pasar a nF y otra vez entre 1000 para µF: 1 000 000 pF = 1000 nF = 1 µF (código 105). Un 101 son 100 pF, y un 103, 10 nF.', q: mcq('Un condensador pone «105». ¿Cuánto vale?', ['1 µF', '105 pF', '10 nF', '100 nF'], '10 y cinco ceros: 1 000 000 pF = 1 µF.') }
  ] },
  /* --- Curso base m14: diseño de PCB --- */
  bb_pcbflow: { name: 'Flujo de diseño de una PCB', alts: [
    { title: 'Del dibujo a los Gerbers', text: 'En KiCad: esquema → asignar huellas → contorno de la placa → colocar → rutar → <b>DRC</b> → exportar Gerbers y taladros. El esquema genera la <b>netlist</b>, la lista de qué patas están unidas, que guía el rutado. El DRC comprueba las reglas del fabricante: si pide 0,15 mm de separación y tienes 0,1 mm, separa las pistas.', q: mcq('¿Qué paso va justo antes de exportar los Gerbers?', ['Pasar el DRC', 'Dibujar el esquema', 'Asignar huellas', 'Definir el contorno'], 'Primero se comprueba, luego se exporta.') },
    { title: 'Capas de una placa', text: 'Una placa tiene capas con oficios distintos: <b>cobre</b> (pistas y pads), <b>máscara</b> de soldadura (el barniz, normalmente verde, que cubre el cobre salvo en los pads), <b>serigrafía</b> (textos y dibujos, normalmente blancos) y <b>taladros</b>. Cada capa se exporta en su propio Gerber.', q: mcq('¿Qué capa evita que el estaño se extienda por las pistas?', ['La máscara de soldadura', 'La serigrafía', 'El cobre', 'Los taladros'], 'Solo deja al aire los pads.') }
  ] },
  charge: { name: 'Corriente = carga / tiempo', alts: [
    { title: 'Contar culombios', text: 'La corriente cuenta cuánta carga pasa por un punto cada segundo: <b>I = Q / t</b>. Si en 5 segundos pasan 10 culombios, cada segundo pasan 2: 2 A. Al revés, Q = I × t: 0,5 A durante 10 s mueven 5 C.', q: mcq('Pasan 6 C en 3 s. ¿Corriente?', ['2 A', '18 A', '0,5 A', '3 A'], 'I = 6 / 3.') },
    { title: 'Con números', text: 'La carga se mide en culombios (C). Un culombio son unos 6 trillones de electrones (6,24 × 10¹⁸). Un amperio es un culombio pasando cada segundo: <b>I = Q / t</b>.', q: mcq('Pasan 2 culombios por un cable en 1 segundo. ¿Corriente?', ['2 A', '0,5 A', '1 A', '2 V'], 'I = Q / t = 2 / 1 = 2 A.') }
  ] },
  current: { name: 'La corriente no se gasta', alts: [
    { title: 'El caudal', text: 'La corriente es cuánta carga pasa por un punto cada segundo, como los litros por segundo de un río. No se “gasta”: la misma corriente que sale de la pila vuelve a ella.', q: mcq('En un circuito con una pila y una bombilla, la corriente que vuelve a la pila es…', ['La misma que sale', 'Menor, porque la bombilla la gasta', 'Cero', 'El doble'], 'La bombilla gasta energía, no corriente.') },
    { title: 'Contando coches', text: 'Si te pones en un puente de una autopista y cuentas coches por minuto, eso es “corriente de coches”. Da igual en qué punto de la carretera sin desvíos te pongas: pasan los mismos.', q: mcq('En un circuito en serie, ¿dónde es mayor la corriente?', ['Es igual en todos los puntos', 'Justo al salir de la pila', 'Antes de la resistencia', 'Después del LED'], 'Sin desvíos, por todos los puntos pasa lo mismo.') }
  ] },
  voltage: { name: 'Tensión', alts: [
    { title: 'Diferencia de altura', text: 'La tensión es como la diferencia de altura entre dos depósitos de agua: cuanta más diferencia, más empuje. Por eso siempre se mide <b>entre dos puntos</b>. Decir “este punto tiene 5 V” significa “5 V respecto a masa”.', q: mcq('¿Por qué un pájaro posado en un cable de alta tensión no se electrocuta?', ['Porque sus dos patas están al mismo potencial: no hay diferencia de tensión', 'Porque las plumas aíslan', 'Porque la corriente va demasiado rápido', 'Porque los pájaros no conducen'], 'Sin diferencia de tensión no hay empuje ni corriente.') },
    { title: 'Energía por carga', text: 'Un voltio significa que cada culombio que atraviesa la pila recibe un julio de energía. Una pila de 9 V da a cada carga 9 veces más energía que una de 1 V.', q: mcq('Una pila de 9 V y otra de 1,5 V. ¿Qué cambia?', ['La energía que recibe cada carga', 'El número de electrones del cable', 'La velocidad de la luz', 'El color de la corriente'], 'Tensión = energía por unidad de carga.') },
    { title: 'Masa como referencia', text: 'Igual que medimos la altura de una montaña desde el nivel del mar, en electrónica elegimos un punto de referencia llamado <b>masa</b> (GND) y le damos 0 V. Todas las demás tensiones se miden respecto a él.', q: mcq('Si un punto está a 5 V y otro a 2 V respecto a masa, ¿qué tensión hay entre ellos?', ['3 V', '7 V', '5 V', '2 V'], 'Diferencia: 5 − 2 = 3 V.') }
  ] },
  resistance: { name: 'Resistencia de un cable', alts: [
    { title: 'Una tubería larga y estrecha', text: 'Un hilo es como una tubería: cuanto más larga, más le cuesta pasar al agua; cuanto más ancha, menos. Por eso la resistencia de un cable crece con la longitud y baja con la sección. Los cables que llevan mucha corriente (un horno) son gruesos para tener poca resistencia y no calentarse.', q: mcq('2 m de cable tienen 0,2 Ω. ¿Cuánto tienen 5 m del mismo cable?', ['0,5 Ω', '0,08 Ω', '0,2 Ω', '1 Ω'], 'Proporcional a la longitud: 0,1 Ω por metro.') },
    { title: 'Qué la determina', text: 'La resistencia de un hilo depende del material, de su longitud y de su grosor: <b>R = ρ · L / S</b>. El doble de largo, el doble de resistencia. El doble de sección, la mitad.', q: mcq('Un cable el doble de largo y del mismo grosor tiene…', ['El doble de resistencia', 'La mitad de resistencia', 'La misma resistencia', 'Cuatro veces menos'], 'R es proporcional a la longitud.') }
  ] },
  circuit: { name: 'Circuito cerrado', alts: [
    { title: 'Un camino en bucle', text: 'La corriente necesita un camino de ida y vuelta a la pila. Si se corta en cualquier punto (circuito abierto), se para en todas partes. Si encuentra un atajo sin resistencia (cortocircuito), circula muchísima corriente y algo se calienta.', q: mcq('Un cable une directamente el + y el − de una pila. ¿Qué pasa?', ['Cortocircuito: mucha corriente y calor', 'No pasa nada, no hay componentes', 'Circuito abierto', 'La pila se recarga'], 'Sin resistencia que limite, la corriente se dispara.') },
    { title: 'El interruptor', text: 'Un interruptor no “manda” la electricidad: simplemente abre o cierra el camino. Abierto = puente levantado; cerrado = puente bajado.', q: mcq('Un interruptor abierto en serie con un LED…', ['Corta el camino y el LED se apaga', 'Hace que el LED brille más', 'Provoca un cortocircuito', 'Solo afecta a la mitad del circuito'], 'En serie, cualquier corte apaga todo.') }
  ] },
  ohm: { name: 'Ley de Ohm', alts: [
    { title: 'El triángulo', text: 'Dibuja un triángulo con V arriba e I y R abajo. Tapa la magnitud que buscas: lo que queda te dice la operación. Tapando V queda I × R; tapando I queda V / R; tapando R queda V / I.', svg: '<svg viewBox="0 0 200 150" class="viz"><path d="M100 15L185 135H15Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="M45 85H155M100 85V135" stroke="currentColor" stroke-width="3"/><text x="100" y="72" text-anchor="middle" font-size="30" font-weight="800" fill="currentColor">V</text><text x="70" y="122" text-anchor="middle" font-size="26" font-weight="800" fill="currentColor">I</text><text x="130" y="122" text-anchor="middle" font-size="26" font-weight="800" fill="currentColor">R</text></svg>', q: mcq('Tapando la R en el triángulo, ¿qué fórmula queda?', ['R = V / I', 'R = V × I', 'R = I / V', 'R = V − I'], 'V arriba, I abajo: V entre I.') },
    { title: 'Proporciones', text: 'Con la resistencia fija, tensión y corriente van juntas: doble de tensión, doble de corriente. Con la tensión fija, resistencia y corriente van al revés: doble de resistencia, mitad de corriente.', tune: { viz: 'ohm', params: { V: { label: 'Pila', val: 4, min: 1, max: 12, step: 1, unit: 'V', dec: 0 }, R: { label: 'Resistencia', val: 1000, fmt: 'R', min: 100, max: 10000 } } }, q: mcq('Con 1 kΩ circulan 3 mA. ¿Cuánto circula con 2 kΩ y la misma pila?', ['1,5 mA', '6 mA', '3 mA', '0,3 mA'], 'Doble resistencia, mitad de corriente.') },
    { title: 'Paso a paso con unidades', text: 'El error más común es mezclar prefijos. Receta: 1) pasa todo a V, A y Ω; 2) aplica la fórmula; 3) vuelve al prefijo cómodo. Ejemplo: 9 V entre 4,7 kΩ → 9 / 4700 = 0,0019 A = 1,9 mA.', q: mcq('5 V entre 2,2 kΩ. ¿Corriente?', ['2,27 mA', '2,27 A', '0,44 mA', '11 mA'], '5 / 2200 = 0,00227 A = 2,27 mA.') }
  ] },
  power: { name: 'Potencia', alts: [
    { title: 'Energía por segundo', text: 'La potencia es la rapidez con la que se transforma la energía. Un vatio es un julio cada segundo. Una resistencia convierte toda su potencia en calor: si es demasiada, se quema.', q: mcq('¿Qué indica la potencia nominal de una resistencia (por ejemplo ¼ W)?', ['El calor máximo que puede disipar sin dañarse', 'Su valor en ohmios', 'La tensión máxima de la pila', 'Cuánta corriente produce'], 'Por eso se elige con margen.') },
    { title: 'Tres caminos', text: 'P = V × I es la base. Si te dan I y R, sustituye V = I·R → P = I²·R. Si te dan V y R, sustituye I = V/R → P = V²/R. Elige la que use los datos que tienes.', q: mcq('Conoces la corriente y la resistencia. ¿Qué fórmula usas?', ['P = I² × R', 'P = V² / R', 'P = V / I', 'P = R / I'], 'La que solo necesita I y R.') }
  ] },
  divider: { name: 'Divisor de tensión', alts: [
    { title: 'Una escalera', text: 'Imagina que la pila es una escalera de 9 escalones y las resistencias reparten los escalones según su tamaño. Con 2 kΩ arriba y 1 kΩ abajo, la de abajo se lleva 1 de cada 3 escalones: 3 V.', q: mcq('12 V, R1 = 3 kΩ arriba y R2 = 1 kΩ abajo. ¿Vsal?', ['3 V', '9 V', '4 V', '6 V'], 'R2 es 1/4 del total: 12/4 = 3 V.') },
    { title: 'Por qué no alimenta cosas', text: 'Si conectas una carga a la salida, queda en paralelo con R2 y la resistencia de abajo baja: la tensión cae. Un divisor sirve para dar una referencia o leer un sensor, no para alimentar.', q: mcq('Un divisor da 5 V en vacío. Le conectas un motor. ¿Qué pasa?', ['La tensión cae mucho', 'Sigue dando 5 V', 'Sube a 10 V', 'El motor gira al doble'], 'La carga cambia el divisor.') }
  ] },
  kvl: { name: 'Ley de mallas', alts: [
    { title: 'Subir y bajar una montaña', text: 'Si sales de casa, subes y bajas colinas y vuelves a casa, el desnivel total es cero. En una malla: la pila “sube” la tensión y cada componente la “baja”; al cerrar la vuelta, todo se compensa.', q: mcq('Pila de 5 V, una resistencia y un LED de 2 V. ¿Cuánto cae en la resistencia?', ['3 V', '5 V', '7 V', '2 V'], '5 − 2 = 3 V.') },
    { title: 'Compruébalo midiendo', text: 'Un truco práctico: mide la tensión de cada componente de la malla con el multímetro. Si las sumas no dan la pila, o hay un error de medida o un componente que no estás viendo (como un cable con mala conexión).', q: mcq('Mides 6 V + 2 V en una malla con una pila de 9 V. ¿Qué sospechas?', ['Que falta 1 V en alguna parte: una conexión con resistencia o un componente olvidado', 'Que Kirchhoff no se cumple aquí', 'Que la pila da 8 V exactos', 'Nada raro'], 'Kirchhoff siempre se cumple: busca dónde está el voltio que falta.') }
  ] },
  led: { name: 'LED y su resistencia', alts: [
    { title: 'Una presa que se desborda', text: 'Un LED es como una presa: por debajo de cierta tensión (≈2 V en rojo) no pasa nada; en cuanto la superas, el agua se desborda sin control. La resistencia en serie es la compuerta que limita el caudal.', q: mcq('¿Por qué no basta con dar al LED “exactamente” 2 V sin resistencia?', ['Porque un poco más de tensión dispara la corriente y lo quema', 'Porque necesita 9 V', 'Porque el LED no conduce sin resistencia', 'Sí basta'], 'Su curva es muy empinada: la resistencia lo estabiliza.') },
    { title: 'La receta en tres pasos', text: '1) Resta al voltaje de la fuente la tensión del LED: lo que queda cae en la resistencia. 2) Divide eso entre la corriente que quieres. 3) Elige el valor comercial superior.', q: mcq('5 V, LED verde de 2,1 V y 10 mA. ¿Qué resistencia comercial?', ['330 Ω', '220 Ω', '290 Ω', '510 kΩ'], '(5 − 2,1) / 0,01 = 290 Ω → 330 Ω.') }
  ] },
  rc: { name: 'Constante de tiempo RC', alts: [
    { title: 'Llenar una piscina con una manguera', text: 'Un condensador es una piscina; la resistencia, el grosor de la manguera. Al principio entra mucha agua, pero cuanto más llena está, más presión hace en contra y entra más despacio. τ = R·C dice lo lento que es: manguera más fina o piscina más grande, más tiempo.', q: mcq('Si duplicas la capacidad con la misma resistencia, el tiempo de carga…', ['Se duplica', 'Se reduce a la mitad', 'No cambia', 'Se cuadruplica'], 'τ = R × C.') },
    { title: 'Con números: τ = R × C', text: 'τ = R · C, con R en ohmios y C en faradios, da segundos. 10 kΩ y 100 µF: 10 000 × 0,0001 = <b>1 s</b>. Atajos: kΩ × µF = ms; MΩ × µF = s. Para τ = 1 s sirven 10 kΩ con 100 µF o 100 kΩ con 10 µF.', q: mcq('R = 47 kΩ y C = 10 µF. ¿τ?', ['0,47 s', '4,7 s', '47 s', '0,047 s'], '47 000 × 0,00001.') }
  ] },
  diode: { name: 'Diodo', alts: [
    { title: 'Una válvula antirretorno', text: 'Un diodo es como la válvula de un neumático: deja entrar aire pero no salir. La flecha del símbolo indica el sentido permitido (convencional): de ánodo a cátodo.', q: mcq('En el símbolo del diodo, la corriente puede ir…', ['En el sentido de la flecha (ánodo → cátodo)', 'Contra la flecha', 'En ambos sentidos', 'En ninguno'], 'La barra es el “tope”.') },
    { title: 'El peaje de 0,7 V', text: 'Para conducir, un diodo de silicio “cobra” unos 0,6–0,7 V. Ese peaje se resta siempre de la tensión disponible para el resto del circuito.', q: mcq('Dos diodos de silicio en serie con una pila de 5 V. ¿Qué tensión queda para el resto?', ['Unos 3,6 V', '5 V', '4,3 V', '1,4 V'], '5 − 0,7 − 0,7 ≈ 3,6 V.') }
  ] },
  bjt: { name: 'Transistor', alts: [
    { title: 'Un grifo controlado', text: 'El transistor es un grifo: la corriente de base es la mano que lo abre y la de colector, el agua que pasa. Con poca mano mueves mucha agua; esa multiplicación es β.', q: mcq('β = 100. Si la base recibe 0,2 mA, ¿cuánta corriente puede pasar por el colector como mucho?', ['20 mA', '0,2 mA', '2 mA', '200 mA'], '100 × 0,2 mA.') },
    { title: 'Interruptor: cortado o saturado', text: 'Para usarlo como interruptor solo interesan dos estados: cortado (sin base, no pasa nada, Vce ≈ alimentación) y saturado (base de sobra, pasa todo lo que permite la carga, Vce ≈ 0,1–0,2 V).', q: mcq('Mides Vce = 8,9 V con una alimentación de 9 V. El transistor está…', ['Cortado', 'Saturado', 'Quemado seguro', 'En inversa'], 'Si apenas cae nada en la carga, no conduce.') }
  ] },
  binary: { name: 'Binario', alts: [
    { title: 'Como un cuentakilómetros', text: 'Un cuentakilómetros decimal pasa de 9 a 10 porque cada rueda tiene 10 cifras. En binario cada rueda solo tiene 0 y 1, así que pasa de 1 a 10 (que vale dos). Cada posición vale el doble que la de su derecha: 1, 2, 4, 8, 16…', q: mcq('¿Qué viene después de 0111 en binario?', ['1000', '0112', '1111', '0110'], '7 + 1 = 8 = 1000.') },
    { title: 'Pesos', text: 'Para leer un número binario, escribe debajo los pesos (… 8 4 2 1) y suma los de las posiciones con 1. 1010 = 8 + 2 = 10.', q: mcq('¿Cuánto vale 1100?', ['12', '3', '1100', '6'], '8 + 4.') }
  ] },
  prefix: { name: 'Cambiar de prefijo', alts: [
    { title: 'La escalera de mil', text: 'Los prefijos son peldaños de 1000 en 1000: p → n → µ → m → (unidad) → k → M. Bajar un peldaño multiplica por 1000; subirlo divide entre 1000.', q: mcq('¿Cuántos µA hay en 1 mA?', ['1000', '10', '100', '0,001'], 'Un peldaño: ×1000.') },
    { title: 'Moviendo la coma', text: 'Cambiar de prefijo es mover la coma 3 posiciones: 4,7 kΩ → 4700 Ω (coma 3 a la derecha); 0,02 A → 20 mA (coma 3 a la derecha).', q: mcq('0,0047 A en mA es…', ['4,7 mA', '47 mA', '0,47 mA', '4700 mA'], 'Coma 3 posiciones a la derecha.') },
    { title: 'Pasa por la unidad', text: 'Si te lías, pasa siempre por la unidad: primero a la unidad base y luego al prefijo que quieres. 47 nF = 47 × 10⁻⁹ F = 0,000 000 047 F → en µF: 0,047 µF. Control: si pasas a un prefijo más grande, el número se hace más pequeño, y al revés.', q: mcq('470 nF son…', ['0,47 µF', '470 000 µF', '4,7 µF', '0,047 µF'], 'De n a µ el prefijo crece ×1000: el número se divide entre 1000.') }
  ] },
  pow10: { name: 'Potencias de 10', alts: [
    { title: 'Contar ceros', text: '10³ = 1000 (tres ceros). 10⁻³ = 0,001 (la coma se mueve tres a la izquierda). Multiplicar potencias suma exponentes: 10³ × 10⁻⁶ = 10⁻³.', q: mcq('10⁶ × 10⁻³ = ?', ['10³', '10⁻¹⁸', '10⁹', '10⁻³'], '6 + (−3) = 3.') }
  ] },
  algebra: { name: 'Despejar', alts: [
    { title: 'La balanza', text: 'Una ecuación es una balanza equilibrada: lo que hagas a un lado, házselo al otro. Si V = I·R y quieres R, divide los dos lados entre I: V/I = R.', q: mcq('De P = V × I, despeja V', ['V = P / I', 'V = P × I', 'V = I / P', 'V = P − I'], 'Divide los dos lados entre I.') }
  ] },
  color: { name: 'Código de colores', alts: [
    { title: 'Una frase para recordarlo', text: 'Negro 0, marrón 1, rojo 2, naranja 3, amarillo 4, verde 5, azul 6, violeta 7, gris 8, blanco 9. Del oscuro al claro pasando por el arcoíris. La tercera banda dice cuántos ceros añadir.', q: mcq('Rojo, violeta, naranja', ['27 kΩ', '273 Ω', '2,7 kΩ', '270 kΩ'], '2, 7 y tres ceros: 27 000 Ω.') },
    { title: 'Bandas paso a paso', text: 'Con cuatro bandas: la primera y la segunda son cifras, la tercera es el número de ceros y la cuarta, algo separada, la tolerancia (dorada ±5 %). Marrón, negro, rojo = 1, 0 y dos ceros = 1000 Ω = 1 kΩ. Empieza a leer por el lado contrario a la banda dorada.', q: mcq('Amarillo, violeta, marrón, dorado', ['470 Ω', '47 Ω', '4,7 kΩ', '471 Ω'], '4, 7 y un cero.') },
    { title: 'Al revés: del valor a los colores', text: 'Escribe el valor en ohmios, separa las dos primeras cifras y cuenta los ceros que quedan. 470 Ω = 47 y un cero → amarillo, violeta, marrón. 10 kΩ = 10 000 = 10 y tres ceros → marrón, negro, naranja.', q: mcq('¿Qué bandas tiene 2,2 kΩ?', ['Rojo, rojo, rojo', 'Rojo, rojo, naranja', 'Rojo, rojo, marrón', 'Naranja, naranja, rojo'], '2200 = 22 y dos ceros.') }
  ] },
  ac: { name: 'Corriente alterna', alts: [
    { title: 'Un columpio', text: 'La alterna es como un columpio: va y viene. La frecuencia es cuántas idas y vueltas completas hace por segundo (50 Hz en Europa). El valor eficaz (rms) es el de una continua que calentaría lo mismo: Vp/√2.', q: mcq('La red europea tiene 230 V eficaces. ¿Cuál es el pico aproximado?', ['325 V', '230 V', '163 V', '460 V'], '230 × √2 ≈ 325 V.') }
  ] },
  filter: { name: 'Filtro RC', alts: [
    { title: 'Un condensador elige frecuencias', text: 'El condensador deja pasar fácilmente las señales rápidas y bloquea las lentas. En un paso bajo RC, el condensador va a masa: “se come” lo rápido y deja pasar lo lento. La frontera es fc = 1/(2πRC).', q: mcq('En un paso bajo RC, si subes la frecuencia muy por encima de fc, la salida…', ['Baja mucho', 'Sube', 'No cambia', 'Se invierte'], 'Lo rápido se va a masa por el condensador.') }
  ] },
  log: { name: 'Logaritmos y dB', alts: [
    { title: 'Contar ceros otra vez', text: 'El logaritmo en base 10 responde a: ¿10 elevado a cuánto da este número? log(100) = 2. Los decibelios usan logaritmos porque el oído y muchos circuitos trabajan en proporciones: 20·log(×10) = 20 dB.', q: mcq('Una ganancia de ×100 en tensión son…', ['40 dB', '20 dB', '100 dB', '2 dB'], '20 · log(100) = 20 · 2.') }
  ] },
  opamp: { name: 'Amplificador operacional', alts: [
    { title: 'Las dos reglas de oro', text: 'Con realimentación negativa: 1) las entradas no consumen corriente; 2) la salida hace lo necesario para que las dos entradas tengan la misma tensión. Con eso se deducen todas las fórmulas.', q: mcq('En un seguidor de tensión (salida unida a la entrada −), si IN+ = 2 V, la salida es…', ['2 V', '0 V', 'La alimentación', '4 V'], 'La salida iguala las entradas.') }
  ] },
  ic555: { name: 'Temporizador 555', alts: [
    { title: 'Un condensador que sube y baja', text: 'Dentro del 555 hay dos comparadores que vigilan el condensador: cuando llega a 2/3 de la alimentación, lo descarga; cuando baja a 1/3, lo vuelve a cargar. La salida cambia en cada vuelta: eso es el parpadeo.', q: mcq('Si usas un condensador más grande en un 555 astable, el LED parpadea…', ['Más despacio', 'Más rápido', 'Igual', 'Deja de parpadear'], 'Más capacidad, más tiempo en cargar y descargar.') }
  ] },
  pullup: { name: 'Pull-up', alts: [
    { title: 'Un muelle', text: 'Una resistencia de pull-up es un muelle que mantiene la entrada arriba (HIGH) cuando nadie la toca. El pulsador, al cerrarse, la lleva a masa con más fuerza que el muelle: LOW.', q: mcq('Sin pull-up ni pull-down, una entrada sin conectar…', ['Lee valores al azar (flota)', 'Lee siempre LOW', 'Lee siempre HIGH', 'Se quema'], 'Por eso siempre hay que fijarla.') }
  ] },
  meter_a: { name: 'Medir corriente', alts: [
    { title: 'Un contador en la tubería', text: 'Para contar el agua que pasa hay que cortar la tubería y meter el contador en medio: toda el agua lo atraviesa. Con la corriente igual: se abre el circuito y el multímetro va en serie, con la punta roja en mA.', q: mcq('¿Por qué es peligroso poner el multímetro en modo corriente en paralelo con una pila?', ['Porque por dentro es casi un cable y provoca un cortocircuito', 'Porque mide alterna', 'Porque marca negativo', 'No es peligroso'], 'El fusible está ahí por eso.') }
  ] },
  breadboard: { name: 'Protoboard', alts: [
    { title: 'Tiras ocultas', text: 'Debajo de cada columna de 5 agujeros hay una pinza metálica: todo lo que pinches en la misma columna (a–e) queda unido. La ranura central separa la mitad de arriba de la de abajo. Las filas largas de los bordes son la alimentación.', q: mcq('Pinchas un cable en b7 y otro en e7. ¿Están conectados?', ['Sí, misma columna y mismo lado', 'No, filas distintas', 'Solo si hay un puente', 'Depende del cable'], 'a–e de la misma columna = un solo nudo.') },
    { title: 'Cada columna es un nudo', text: 'Piensa en cada columna de 5 agujeros como un nudo ya hecho. Dos patas en la misma columna quedan unidas: si son las dos patas de una resistencia, la cortocircuitas y no hace nada. Los chips se ponen a caballo de la ranura central para que cada pata quede en su propia columna, y las filas largas de los bordes reparten + y −.', q: mcq('¿Por qué un chip DIP se coloca sobre la ranura central?', ['Para que cada pata quede en una columna distinta', 'Para que se ventile', 'Para que reciba alimentación', 'Para sujetarlo mejor'], 'Si no, las patas enfrentadas quedarían unidas.') }
  ] },
  schematic: { name: 'Esquemas', alts: [
    { title: 'Un mapa de metro', text: 'Un esquema es como un mapa de metro: no respeta las distancias reales, solo qué está unido con qué. Dos dibujos muy distintos pueden ser el mismo circuito.', q: mcq('Dos esquemas tienen formas distintas pero las mismas conexiones. ¿Son el mismo circuito?', ['Sí', 'No', 'Solo si tienen el mismo tamaño', 'Solo si los colores coinciden'], 'Lo que importa son las conexiones.') }
  ] },
  cap: { name: 'Condensador', alts: [
    { title: 'Un depósito pequeño', text: 'Un condensador guarda carga entre dos placas. Se llena y se vacía muy rápido, y en continua, una vez lleno, no deja pasar corriente. Su capacidad (µF) es el tamaño del depósito.', q: mcq('En continua y ya cargado, un condensador se comporta como…', ['Un circuito abierto', 'Un cable', 'Una pila infinita', 'Una resistencia de 0 Ω'], 'Bloquea la continua.') }
  ] },
  logic: { name: 'Puertas lógicas', alts: [
    { title: 'Interruptores', text: 'AND son interruptores en serie (todos cerrados para que pase). OR son interruptores en paralelo (basta uno). NOT invierte. Todas las demás se construyen combinándolas.', q: mcq('Una alarma suena si la puerta está abierta O la ventana está abierta. ¿Qué puerta?', ['OR', 'AND', 'NOT', 'NAND'], 'Basta una condición.') }
  ] },
  pwm: { name: 'PWM', alts: [
    { title: 'Parpadeo muy rápido', text: 'Si enciendes y apagas una luz muy rápido, el ojo ve la media. PWM hace eso cientos de veces por segundo: con el 25 % del tiempo encendido, ves un 25 % de brillo.', q: mcq('analogWrite(pin, 255) equivale a…', ['Siempre encendido', 'Apagado', 'La mitad', '255 V'], '255 es el máximo: 100 %.') }
  ] },
  adc: { name: 'Conversión analógica', alts: [
    { title: 'Una regla con marcas', text: 'El ADC mide una tensión con una regla de marcas: la Uno tiene 1024 marcas entre 0 y 5 V (unos 4,9 mV cada una). El número que devuelve es la marca más cercana.', q: mcq('analogRead devuelve 512 en una Uno. ¿Tensión aproximada?', ['2,5 V', '5 V', '512 V', '1 V'], '512/1023 × 5 ≈ 2,5 V.') }
  ] },
  /* --- m12 Microcontroladores --- */
  mc_types: { name: 'Tipos: qué cabe en cada uno', alts: [
    { title: 'Cajas de distinto tamaño', text: 'Cada tipo es una caja de tamaño fijo: elige la caja por el dato más grande que vaya a guardar. En la Uno: <b>bool</b> y <b>byte</b> (1 byte; byte de 0 a 255), <b>int</b> (2 bytes, de −32 768 a 32 767), <b>unsigned long</b> (4 bytes, hasta unos 4300 millones) y <b>float</b> (4 bytes, con decimales). En las placas de 32 bits (ESP32, Pico, STM32) int ocupa 4 bytes. Si el dato no cabe, no hay aviso: sale un valor equivocado.', q: mcq('Vas a guardar los pasos de un motor, que llegan a 50 000. ¿Qué tipo eliges en una Uno?', ['unsigned int o long', 'int', 'byte', 'bool'], 'Un int de la Uno llega a 32 767; un unsigned int, a 65 535, y un long, a unos 2100 millones.') },
    { title: 'Bits y rangos', text: 'Con n bits hay 2ⁿ combinaciones: 8 bits dan 256 valores, 16 bits 65 536 y 32 bits más de 4000 millones. Si el tipo tiene signo, la mitad son negativos: un int de 16 bits va de −32 768 a 32 767. Y el tamaño de int depende de la placa: 16 bits en la Uno, 32 en el ESP32 o un STM32. Cuando importe, usa tipos de tamaño fijo como int16_t o uint32_t.', q: mcq('¿Hasta qué número llega un unsigned int de 16 bits?', ['65 535', '32 767', '255', '65 536'], '2¹⁶ − 1 = 65 535: el 0 también ocupa una combinación.') },
    { title: 'El tiempo no cabe en un int', text: 'millis() cuenta milisegundos sin parar. En un int de la Uno (2 bytes; 4 en placas de 32 bits) solo caben 32 767: a los 32,8 s ya no entra y salen valores absurdos, incluso negativos. Por eso los tiempos se guardan en <b>unsigned long</b>, el mismo tipo que devuelve millis(). Regla general: piensa el valor máximo del dato y elige el tipo más pequeño donde quepa.', q: mcq('¿De qué tipo declaras la variable donde guardas millis() para un parpadeo?', ['unsigned long', 'int', 'byte', 'float'], 'El mismo tipo que devuelve millis(): así nunca se queda corta.') }
  ] },
  mc_intmath: { name: 'División entera y resto (/ y %)', alts: [
    { title: 'Repartir caramelos', text: 'Reparte 17 caramelos entre 5 niños: cada uno recibe 3 (eso es <b>17 / 5</b> entre enteros) y sobran 2 (eso es <b>17 % 5</b>). Con enteros no se parten caramelos: los decimales se tiran, no se redondea. El resto sirve para ciclos: la posición del paso k en un ciclo de N es k % N. Y, como en matemáticas, / y % se calculan antes que + y −.', q: mcq('¿Cuánto da 23 / 4 entre enteros?', ['5', '5,75', '6', '3'], '4 × 5 = 20 y sobran 3: el cociente es 5 (y 23 % 4 sería 3).') },
    { title: 'El resto da vueltas', text: 'El resto siempre está entre 0 y el divisor menos 1, así que sirve para todo lo que va en círculo: (i + 1) % 4 recorre 0, 1, 2, 3, 0, 1…; segundos / 60 da los minutos y segundos % 60, los segundos que sobran. Para saber dónde cae el paso k de un ciclo de N, calcula k % N. La división entera, en cambio, cuenta las vueltas completas.', q: mcq('paso empieza en 0 y se hace paso = (paso + 1) % 5 siete veces. ¿Cuánto vale?', ['2', '7', '0', '5'], '0 → 1 → 2 → 3 → 4 → 0 → 1 → 2: es 7 % 5 = 2.') },
    { title: 'Compruébalo multiplicando', text: 'Cociente y resto cumplen siempre a = b × (a / b) + (a % b). Para 19 y 5: 19 = 5 × 3 + 4, así que 19 / 5 = 3 y 19 % 5 = 4. Si lo que te sale no cumple esa igualdad, hay un fallo. Y ojo al orden: en 2 + 17 / 5 primero va la división (entera) y luego la suma.', q: mcq('¿Cuánto vale 2 + 17 / 5 entre enteros?', ['5', '3', '3,8', '5,4'], 'Primero 17 / 5 = 3 (entera); luego 2 + 3 = 5.') }
  ] },
  mc_flow: { name: 'Bucles for y while', alts: [
    { title: 'Sigue el bucle con el dedo', text: 'Un <b>for</b> tiene tres partes: inicio (int i = 0), condición para seguir (i &lt; 5) y paso (i++). Apunta en un papel el valor de i en cada vuelta y comprueba la condición <b>antes</b> de cada una: cuando es falsa, el bucle termina. Con i &lt; 5 desde 0 salen 5 vueltas (de 0 a 4); con i &lt;= 5, seis. Lo que se repite es lo que va entre sus llaves.', q: mcq('for (int i = 1; i < 4; i++) — ¿qué valores toma i dentro del bucle?', ['1, 2 y 3', '1, 2, 3 y 4', '0, 1, 2 y 3', 'Solo 4'], 'Cuando i llega a 4 la condición es falsa y el bucle termina.') },
    { title: 'Algo tiene que cambiar', text: 'Un <b>while</b> repite mientras su condición sea cierta. Si nada dentro del bucle la acaba haciendo falsa, no sale nunca y la placa parece colgada. En un for, el paso (i++, i -= 2…) es lo que avanza hacia el final: úsalo para contar las vueltas. Y todo lo que quieras repetir debe ir dentro de las llaves del bucle.', q: mcq('int k = 0; while (k < 3) { Serial.println(k); k++; } ¿Qué imprime?', ['0, 1 y 2', '0, 1, 2 y 3', '1, 2 y 3', 'Sin parar'], 'k sube en cada vuelta; al llegar a 3 la condición es falsa.') }
  ] },
  mc_func: { name: 'Funciones: parámetros y return', alts: [
    { title: 'Una receta', text: 'Una función es una receta con nombre. La cabecera lo dice todo: <b>int doble(int x)</b> recibe un int y devuelve un int; <b>void</b> delante significa que no devuelve nada. Al llamarla, los valores entran en los parámetros <b>en orden</b>: parpadear(8, 2) da pin = 8 y veces = 2. Si la cabecera promete devolver algo, el cuerpo necesita su <b>return</b>.', q: mcq('Con int cuadrado(int x) { return x * x; }, ¿cuánto vale cuadrado(3) + 1?', ['10', '7', '9', '16'], 'cuadrado(3) devuelve 9; más 1, 10.') },
    { title: 'Copias, no originales', text: 'Al llamar a una función le pasas <b>copias</b> de los valores, colocadas en orden en sus parámetros. Lo que haga con ellas no cambia tus variables. Si quieres un resultado, la función lo devuelve con <b>return</b> (del tipo que pone delante de su nombre) y tú lo guardas o lo usas. Sin return, lo que llega es basura.', q: mcq('void poner(int x) { x = 0; } … int a = 7; poner(a); ¿Cuánto vale a?', ['7', '0', 'Indefinido', '1'], 'La función solo cambió su copia.') }
  ] },
  mc_array: { name: 'Arrays', alts: [
    { title: 'Una fila de taquillas', text: 'Un array es una fila de taquillas numeradas <b>empezando por 0</b>: en int v[5], la primera es v[0] y la última v[4]. Pedir v[5] es abrir la taquilla de otro: C++ no te lo impide y el fallo aparece donde menos lo esperas. Para recorrerlas todas, un for con i desde 0 mientras i &lt; 5.', q: mcq('int v[3] = {7, 8, 9}; ¿Cuánto vale v[1]?', ['8', '7', '9', 'No existe'], 'Índices 0, 1 y 2: v[1] es el segundo.') },
    { title: 'Bucle y array, pareja inseparable', text: 'Para hacer lo mismo con todos los elementos: un for con i desde 0 mientras <b>i &lt; N</b>, usando v[i] dentro. Como los índices empiezan en 0, el último es N − 1, y con i &lt;= N te sales una posición. Si mañana tienes 8 LEDs en vez de 5, solo cambias N y la lista.', q: mcq('Para recorrer un array de N elementos, la condición del for es…', ['i < N', 'i <= N', 'i < N + 1', 'i > N'], 'Con <= te sales una posición.') }
  ] },
  mc_serial: { name: 'Monitor serie: conectar bien', alts: [
    { title: 'Los dos extremos a la misma velocidad', text: 'El Monitor serie habla con la placa por el cable USB. Los dos lados deben usar los mismos <b>baudios</b>: si el programa pone Serial.begin(9600) y el monitor está en 115200, salen símbolos raros. En la Uno y la Nano ese puerto usa los pines <b>0 (RX) y 1 (TX)</b>: no conectes nada en ellos. Y al abrir el monitor la Uno se reinicia, así que el programa vuelve a empezar por setup().', q: mcq('Serial.begin(115200) y el monitor en 9600. ¿Qué ves?', ['Símbolos sin sentido', 'El texto bien, pero más lento', 'El texto bien', 'El texto al revés'], 'Cada lado interpreta los bits a su propio ritmo.') },
    { title: 'Síntoma → causa', text: 'Símbolos raros: baudios distintos en Serial.begin() y en el monitor. El mensaje de setup() vuelve a salir cada vez que abres el monitor: es normal, la Uno se reinicia al abrir el puerto. Un LED en el pin 0 o 1 hace cosas raras (o no puedes subir programas): esos pines son el RX y el TX del puerto serie que va al USB.', q: mcq('Cada vez que abres el Monitor serie ves de nuevo «Arrancando», que se imprime en setup(). ¿Por qué?', ['Abrir el monitor reinicia la Uno', 'setup() se repite cada cierto tiempo', 'El monitor guarda los mensajes viejos', 'Hay un fallo en loop()'], 'La Uno y la Nano se reinician al abrir el puerto.') }
  ] },
  mc_memory: { name: 'Flash, RAM y EEPROM', alts: [
    { title: 'Pizarra, libreta y libro', text: 'La <b>SRAM</b> es una pizarra: rápida, pero se borra al apagar (las variables). La <b>EEPROM</b> es una libreta: guarda sin corriente, pero se gasta si escribes mucho (récords, calibraciones). La <b>Flash</b> es el libro impreso con tu programa y sus textos fijos: sigue ahí al quitar la corriente. Las tres están dentro del mismo chip, junto al procesador y los periféricos: por eso, a diferencia de la CPU de un ordenador, funciona sola.', q: mcq('¿Dónde guardas la calibración de un sensor para que sobreviva a un apagado?', ['En la EEPROM', 'En la SRAM', 'En una variable local', 'En el Monitor serie'], 'La EEPROM no se borra al quitar la corriente.') },
    { title: 'Qué pasa al quitar la corriente', text: 'Pregúntate qué debe sobrevivir a un apagado. El <b>programa</b> está en la Flash: al volver la corriente (por USB o con una pila) arranca solo. Las <b>variables</b> están en la SRAM y empiezan de nuevo con su valor inicial. Los datos que quieras conservar van a la <b>EEPROM</b>. Todo eso está en el propio chip, con la CPU y los periféricos, cosa que la CPU de un ordenador no lleva.', q: mcq('Un contador de pulsaciones vale 57 y quitas la pila. Al volver a encender, ¿cuánto vale si es una variable normal?', ['Su valor inicial: la SRAM se borra al apagar', '57', 'Un número al azar', 'No arranca: se ha borrado el programa'], 'Las variables viven en la SRAM; el programa, en la Flash, sigue ahí.') }
  ] },
  mc_choose: { name: 'Elegir placa', alts: [
    { title: 'La herramienta justa', text: 'Elegir placa es como elegir herramienta: parte de lo que el proyecto necesita y elige la más sencilla que lo cumpla. <b>Uno/Nano</b>: 5 V, sencilla, compatible con shields y mil ejemplos. <b>ESP32</b>: 3,3 V, WiFi y Bluetooth. <b>Pico (RP2040)</b>: dos núcleos y bloques PIO para protocolos a medida. <b>STM32</b>: periféricos avanzados, uso industrial. Una <b>Raspberry Pi</b> no es un microcontrolador: es un ordenador con Linux.', q: mcq('Un juego de reflejos con dos botones y tres LEDs, alimentado por USB. ¿Qué basta?', ['Una Uno o una Nano', 'Un ESP32, obligatoriamente', 'Un ordenador con Linux', 'Un STM32 de gama alta'], 'Sin radio ni grandes cálculos, lo más sencillo vale.') },
    { title: 'Las preguntas que descartan', text: 'Antes de elegir: 1) ¿necesito WiFi o Bluetooth? → ESP32 (o Pico W). 2) ¿mis módulos y shields son de 5 V? → Uno o Nano. 3) ¿cuánta RAM necesito? La Uno solo tiene 2 KB; ESP32 y Pico, cientos. 4) ¿señales con tiempos de microsegundos o protocolos raros? → el PIO de la Pico. Con eso descartas casi todo.', q: mcq('Necesitas tener en RAM una imagen de 20 KB. ¿Qué placa descartas?', ['La Uno: solo tiene 2 KB de RAM', 'El ESP32', 'La Pico', 'Ninguna'], 'El ESP32 y la Pico tienen cientos de KB de RAM.') }
  ] },
  /* --- m12: conceptos estrechos (una destreza cada uno) --- */
  mc_setup: { name: 'setup() y loop()', alts: [
    { title: 'Preparar y repetir', text: 'Al arrancar (al encenderla, al pulsar reset o al terminar de subir un programa) la placa ejecuta <b>setup()</b> una sola vez: ahí se prepara todo, como pinMode. Después ejecuta <b>loop()</b> y, al llegar a su llave de cierre, vuelve a empezarla, sin fin. Lo que se hace una vez va en setup(); lo que se repite, en loop(), en el orden en que debe ocurrir.', q: mcq('Pones Serial.println("Hola") en setup(). ¿Cuántas veces sale «Hola» si la placa funciona una hora sin reiniciarse?', ['Una', 'Una por segundo', 'Sin parar', 'Ninguna'], 'setup() solo se ejecuta al arrancar.') },
    { title: 'Del IDE a la placa', text: 'El camino de tu programa: lo escribes, lo <b>compilas</b> (se traduce a instrucciones del chip; si hay un error, se para ahí), lo <b>subes</b> por USB y queda grabado en la Flash. Entonces la placa se reinicia, ejecuta setup() una vez y luego repite loop() mientras tenga corriente.', q: mcq('El IDE muestra un error al compilar. ¿Qué ejecuta ahora la placa?', ['El programa que tenía antes: el nuevo no ha llegado', 'El programa nuevo, con el error', 'Nada: se borra la Flash', 'Solo setup()'], 'Si la compilación falla, no se sube nada.') },
    { title: 'La forma de todo programa', text: 'Un programa de Arduino tiene dos bloques, cada uno entre sus llaves. En setup(), configurar (pinMode(13, OUTPUT)), una vez. En loop(), lo que se repite, en orden: encender, esperar, apagar, esperar. Al subirlo (tras compilar sin errores), la placa se reinicia, hace setup() y después loop() sin fin.', q: mcq('¿Dónde va pinMode(13, OUTPUT) en el programa de parpadeo?', ['En setup(): basta configurarlo una vez', 'En loop(), antes de cada digitalWrite', 'Fuera de las dos funciones', 'No hace falta'], 'Configurar es cosa de una vez: setup().') }
  ] },
  mc_delay: { name: 'delay(): esperar con el pin quieto', alts: [
    { title: 'Una foto fija', text: 'delay(ms) detiene el programa ese número de <b>milisegundos</b> (1000 ms = 1 s). Mientras espera, los pines se quedan como estaban: si acabas de encender el LED, sigue encendido todo el delay. Por eso el tiempo encendido es el delay que va tras HIGH, el apagado el que va tras LOW, y el ciclo completo, la suma de los dos.', q: mcq('HIGH; delay(300); LOW; delay(700); dentro de loop(). ¿Cómo parpadea el LED?', ['300 ms encendido y 700 ms apagado: un ciclo por segundo', '700 ms encendido y 300 ms apagado', '300 ms encendido y 300 ms apagado', 'Siempre encendido'], 'Cada delay mantiene el estado que se acaba de escribir.') },
    { title: 'El apagón invisible', text: 'Si tras digitalWrite(13, LOW) no hay ningún delay, loop() vuelve a empezar y enciende otra vez en unos microsegundos. El LED sí se apaga, pero tan poco que el ojo no lo ve: parece siempre encendido. Cada estado que quieras ver necesita su propio delay, que se mide en milisegundos: delay(500) es medio segundo.', q: mcq('loop() contiene solo: LOW; delay(800); HIGH; ¿Qué ves?', ['El LED parece siempre apagado', 'Parpadea 800 ms y 800 ms', 'Parece siempre encendido', 'Parpadea muy deprisa'], 'Tras HIGH, loop() vuelve enseguida a LOW: encendido solo microsegundos.') }
  ] },
  mc_syntax: { name: 'Errores de escritura al compilar', alts: [
    { title: 'El compilador es muy literal', text: 'El compilador no adivina: <b>digitalwrite</b> y <b>digitalWrite</b> son nombres distintos (distingue mayúsculas y minúsculas), y cada instrucción debe acabar en <b>punto y coma</b>. Si falta uno, se queja, a menudo señalando la línea siguiente. Hasta que no compila, nada llega a la placa.', q: mcq('¿Cuál de estas líneas compila?', ['pinMode(13, OUTPUT);', 'pinmode(13, OUTPUT);', 'pinMode(13, OUTPUT)', 'PinMode(13, OUTPUT);'], 'Nombre exacto, con sus mayúsculas, y punto y coma final.') },
    { title: 'Lee el mensaje', text: 'Los mensajes de error dan la pista: «\'digitalwrite\' was not declared in this scope» significa que ese nombre no existe tal cual (casi siempre, una mayúscula o una letra mal); «expected \';\' before…» significa que falta un punto y coma justo antes de donde señala. Arregla el primer error de la lista: muchos de los siguientes son consecuencia de él.', q: mcq('El IDE dice: expected \';\' before \'}\' token. ¿Qué haces?', ['Poner punto y coma a la instrucción anterior a esa llave', 'Borrar la llave', 'Reinstalar el IDE', 'Cambiar el cable USB'], 'Falta el ; al final de la instrucción anterior.') }
  ] },
  mc_vars: { name: 'Variables y constantes', alts: [
    { title: 'Una caja con etiqueta', text: 'Una variable es una caja con nombre: <b>int x = 5;</b> crea la caja x con un 5 dentro. El = no es una igualdad matemática, es «guarda»: en x = x + 3 primero se calcula la derecha con el valor actual (5 + 3) y luego el resultado sustituye al anterior. Con <b>const</b> delante, la caja queda sellada: sirve para poner nombre a un número fijo, como un pin.', q: mcq('int n = 2; n = n * 4; ¿Cuánto vale n?', ['8', '2', '4', '6'], 'Se calcula 2 × 4 con el valor actual y se guarda: 8.') },
    { title: 'Nombres para los números', text: 'const int LED = 13; no enciende nada ni crea ningún LED: solo dice «a partir de aquí, LED significa 13». El código se lee mejor y, si cambias el LED de pin, lo cambias en una sola línea. Las variables normales sí cambian con cada asignación: en x = x + 3 se calcula la derecha con el valor actual y se guarda en x.', q: mcq('Tras const int LED = 9;, ¿qué hace digitalWrite(LED, HIGH)?', ['Pone a HIGH el pin 9', 'Crea un LED nuevo', 'Da error: LED no es un número', 'Pone a HIGH el pin 0'], 'LED es solo un nombre para el 9.') }
  ] },
  mc_overflow: { name: 'Desbordamiento: el número da la vuelta', alts: [
    { title: 'El cuentakilómetros', text: 'Un cuentakilómetros de tres cifras pasa de 999 a 000. Un <b>byte</b> es un cuentakilómetros de 8 bits: después de 255 viene 0. Si intentas guardar 260, se queda 260 − 256 = 4. Hacia atrás igual: 0 − 1 da 255. No hay aviso ni error.', q: mcq('byte b = 250; b = b + 10; ¿Cuánto vale b?', ['4', '260', '255', '10'], '260 no cabe en un byte: 260 − 256 = 4.') },
    { title: 'Quita vueltas completas', text: 'Para saber qué guarda una variable desbordada, quita (o suma) vueltas completas hasta caer dentro de su rango. Un byte da vueltas de 256; un unsigned int de la Uno, de 65 536. 300 en un byte → 300 − 256 = 44. −20 en un byte → −20 + 256 = 236. Mueve el deslizador y mira la aguja.', tune: { viz: 'mc_wrap', params: { v: { label: 'Valor que intentas guardar', val: 300, min: 0, max: 600, step: 1, unit: '', dec: 0 }, bits: { val: 8, fixed: true } } }, q: mcq('byte x = 10; x = x - 30; ¿Cuánto vale x?', ['236', '−20', '0', '20'], 'Un byte no tiene negativos: −20 + 256 = 236.') },
    { title: 'Sin aviso', text: 'Lo traicionero del desbordamiento es que no da error: el programa sigue con un número equivocado (256 en un byte es 0; 65 536 en un unsigned int de la Uno, también 0). Antes de sumar, piensa el valor más grande que puede alcanzar la variable y comprueba que cabe en su tipo; si no, usa uno mayor o limita la cuenta.', q: mcq('Un contador byte de pulsaciones marca 3 tras 259 pulsaciones. ¿Qué ha pasado?', ['Ha pasado de 255 y ha dado la vuelta: 259 − 256 = 3', 'Se han perdido pulsaciones por rebotes', 'El byte se ha borrado', 'El pin está mal configurado'], 'Un byte no pasa de 255; luego vuelve a 0 sin avisar.') }
  ] },
  mc_bytes: { name: 'Cuánta memoria ocupan los datos', alts: [
    { title: 'Tamaño por cantidad', text: 'Memoria = número de elementos × bytes de cada uno. En la Uno: bool, byte y char, 1 byte; int, 2; long, unsigned long y float, 4. Un array de 20 int: 20 × 2 = 40 bytes. Varias variables se suman: un bool, dos int y un unsigned long son 1 + 4 + 4 = 9 bytes. Un texto ocupa sus letras más 1 (el \'\\0\' final).', q: mcq('float datos[50]; en una Uno. ¿Cuántos bytes?', ['200', '50', '100', '400'], '50 × 4 = 200 bytes.') },
    { title: 'Las dos trampas', text: 'Primera: un texto entre comillas lleva al final un carácter invisible, el \'\\0\', así que "Hola" ocupa 5 bytes. Segunda: int no mide lo mismo en todas las placas: 2 bytes en la Uno y 4 en el ESP32, la Pico o un STM32. Por lo demás, multiplica elementos por tamaño (float y long, 4; byte y char, 1) y suma.', q: mcq('¿Cuántos bytes ocupa char t[] = "Uno";?', ['4', '3', '6', '8'], '3 letras más el \'\\0\' final.') },
    { title: '¿Cabe o no cabe?', text: 'Calcula elementos × tamaño y compáralo con la memoria: la Uno tiene 2048 bytes de RAM y 1024 de EEPROM. 1500 float son 6000 bytes: no caben en su RAM. Al revés, para saber cuántos caben, divide: en 1 KB de EEPROM caben 1024 / 4 = 256 float. Recuerda que un texto ocupa sus letras más 1.', q: mcq('¿Cuántos int de la Uno caben en 100 bytes?', ['50', '100', '25', '200'], 'Cada int ocupa 2 bytes: 100 / 2 = 50.') }
  ] },
  mc_opertype: { name: 'El tipo de la cuenta lo deciden los números', alts: [
    { title: 'Que haya decimales', text: 'Una cuenta se hace con el tipo de los números que intervienen, <b>antes</b> de guardarse. Si todos son enteros, el resultado es entero aunque lo guardes en un float: float f = 7 / 2; guarda 3,0. Basta con que uno lleve decimales (7.0 en el código) para que la cuenta los tenga. Igual con los enteros grandes: en la Uno, 60 * 1000 se calcula en int y no cabe; 60 * 1000UL, sí.', q: mcq('¿Qué guarda float f = 1 / 4;?', ['0', '0,25', '4', '1'], '1 / 4 entre enteros es 0, y luego se convierte a float.') },
    { title: 'Los resultados intermedios también tienen tipo', text: 'En la Uno, 60 * 1000 se calcula con int, y 60 000 no cabe en un int (máximo 32 767): sale un número absurdo aunque lo guardes en un unsigned long. Se evita poniendo UL a uno de los números (60 * 1000UL), que obliga a hacer la cuenta en unsigned long. Lo mismo con los decimales: puntos * 10.0 / 40 los tiene porque 10.0 los tiene.', q: mcq('En una Uno, ¿qué expresión da bien 3 minutos en ms?', ['3 * 60 * 1000UL', '3 * 60 * 1000', '(byte)180000', '3 / 60 * 1000'], 'Con UL la multiplicación se hace en unsigned long y 180 000 cabe.') },
    { title: 'El orden importa', text: 'Con enteros, el orden de las operaciones cambia el resultado: puntos / 40 * 10.0 da 0 para cualquier puntuación menor que 40, porque la división entera se hace primero. Pon el decimal al principio o multiplica antes de dividir: puntos * 10.0 / 40. Y si el intermedio es grande (60 * 1000 en la Uno), fuerza el tipo con UL.', q: mcq('puntos vale 30. ¿Qué guarda nota?', ['0', '7,5', '10', '30'], '30 / 40 entre enteros es 0; 0 × 10,0 = 0.', { code: 'float nota = puntos / 40 * 10.0;' }) }
  ] },
  mc_bitops: { name: 'Operadores de bits', alts: [
    { title: 'Interruptores en fila', text: 'Un byte son 8 interruptores numerados del 0 (derecha) al 7. <b>1 &lt;&lt; k</b> es un número con solo el interruptor k encendido (vale 2ᵏ). <b>x | m</b> enciende los de m, <b>x &amp; ~m</b> apaga los de m y bitRead(x, k) lee el k. Para pasar a decimal, suma los pesos de los que estén a 1.', q: mcq('¿Cuánto vale (1 << 3) | (1 << 0)?', ['9', '4', '8', '3'], '8 + 1 = 9: bits 3 y 0 encendidos.') },
    { title: 'Con la tabla de pesos', text: 'Escribe los pesos encima de los bits: 128 64 32 16 8 4 2 1. Desplazar una posición a la izquierda es multiplicar por 2, así que 1 &lt;&lt; 5 = 32. Con | el bit queda a 1 aunque ya lo estuviera; con &amp; ~(1 &lt;&lt; k) queda a 0; para leer el bit k, mira la columna de peso 2ᵏ. Al final, suma los pesos de los unos.', q: mcq('x = 0b00001111; x &= ~(1 << 2); ¿Cuánto vale x?', ['11', '15', '4', '13'], 'Se apaga el bit 2 (peso 4): 15 − 4 = 11.') }
  ] },
  mc_if: { name: 'Condiciones: if, else y comparaciones', alts: [
    { title: '= frente a ==', text: 'Un igual (<b>=</b>) guarda: «x pasa a valer 5». Dos iguales (<b>==</b>) preguntan: «¿x vale 5?». if (x = 5) no compara: guarda 5 en x y, como 5 no es cero, la condición se cumple siempre. Para combinar: <b>&amp;&amp;</b> exige las dos condiciones; <b>||</b> se conforma con una. En una cadena de else if solo actúa la primera rama cierta.', q: mcq('¿Qué línea pregunta si n vale 10?', ['if (n == 10)', 'if (n = 10)', 'n = 10;', 'if (10)'], 'Comparar es ==.') },
    { title: 'Sigue la cadena', text: 'En una cadena if / else if / else se prueban las condiciones de arriba abajo y solo se ejecuta la <b>primera</b> que se cumple; las demás se saltan. Sustituye las variables por sus valores y evalúa cada condición: con &amp;&amp; deben cumplirse las dos; con ||, al menos una. Y recuerda que comparar es ==, no =.', q: mcq('t = 15. if (t > 30) A(); else if (t > 10) B(); else C(); ¿Qué se ejecuta?', ['B()', 'A()', 'C()', 'B() y C()'], '15 no es mayor que 30, pero sí que 10: B(), y el else se salta.') },
    { title: 'Dentro o fuera del rango', text: '<b>t &gt; 5 &amp;&amp; t &lt; 35</b> se cumple dentro del rango (las dos a la vez). <b>t &lt; 5 || t &gt; 35</b> se cumple fuera (basta una). Pruébalo con un valor de cada zona: dentro, en el borde y fuera. Y no olvides que == compara y = asigna, y que en una cadena de else if solo actúa la primera rama cierta.', q: mcq('¿Cuándo se cumple if (v < 100 || v > 900)?', ['Cuando v está fuera del rango de 100 a 900', 'Cuando v está entre 100 y 900', 'Nunca', 'Siempre'], 'Con || basta con que se cumpla una.') }
  ] },
  mc_scope: { name: 'Variables locales y globales', alts: [
    { title: 'Pizarra y pósit', text: 'Una variable <b>global</b> (creada fuera de todas las funciones) es la pizarra del aula: existe siempre y todas las funciones la ven. Una <b>local</b> (creada dentro de una función) es un pósit: se escribe al entrar en la función y se tira al salir. Por eso un contador local de loop() vuelve a empezar en cada vuelta, y uno global sigue sumando.', q: mcq('void loop() { int c = 0; c++; Serial.println(c); } ¿Qué imprime en la décima vuelta?', ['1', '10', '0', '9'], 'c se crea con 0 en cada vuelta.') },
    { title: 'Vuelta a vuelta', text: 'Haz la traza: si la variable se crea dentro de loop(), en cada vuelta nace de nuevo con su valor inicial; si se crea fuera, conserva lo que valía al acabar la vuelta anterior. Para que una variable de una función recuerde su valor entre llamadas, sácala fuera (global) o declárala <b>static</b>.', q: mcq('int c = 0; void loop() { c++; Serial.println(c); } ¿Qué imprime en la quinta vuelta?', ['5', '1', '0', '4'], 'c es global: conserva su valor y sube de uno en uno.') }
  ] },
  mc_digout: { name: 'Salidas digitales', alts: [
    { title: 'Un conmutador dentro del pin', text: 'Con <b>pinMode(pin, OUTPUT)</b> el pin pasa a ser salida. Después, digitalWrite(pin, HIGH) lo une por dentro a la alimentación (5 V en la Uno, 3,3 V en el ESP32) y LOW, a masa (GND, 0 V). El número que pones en las funciones es el del pin; la Uno trae además un LED soldado en el 13. Un LED necesita diferencia de tensión: pin → resistencia → LED → GND luce con HIGH; 5V → resistencia → LED → pin luce con LOW.', q: mcq('¿Qué falta para que digitalWrite(7, HIGH) encienda bien un LED en el pin 7?', ['pinMode(7, OUTPUT) en setup()', 'Un delay', 'Escribir 5 en vez de HIGH', 'Nada'], 'Sin configurarlo como salida, el pin no se comporta como tal (como mucho, el LED luce muy débil).') },
    { title: 'Hace falta diferencia de tensión', text: 'Un LED luce cuando hay tensión entre sus extremos. Montado pin → resistencia → LED → GND (el cátodo, a masa), se enciende con <b>HIGH</b>: 5 V contra 0 V. Montado 5V → resistencia → LED → pin, se enciende con <b>LOW</b>: el pin hace de masa; con HIGH los dos extremos están a 5 V y no pasa nada. Antes de todo, pinMode(pin, OUTPUT); HIGH son 5 V en la Uno y 3,3 V en el ESP32.', q: mcq('LED entre el pin 4 (ánodo, con su resistencia) y GND (cátodo). ¿Cómo se enciende?', ['Con digitalWrite(4, HIGH)', 'Con digitalWrite(4, LOW)', 'Conectando el cátodo a 5V', 'No se puede encender'], 'HIGH pone 5 V en el ánodo y el cátodo está a 0 V.') }
  ] },
  mc_ledres: { name: 'Resistencia de un LED en un pin', alts: [
    { title: 'La receta en tres pasos', text: '1) Resta a la tensión del pin (o de la fuente) la del LED: lo que sobra cae en la resistencia. 2) Divide entre la corriente que quieres, en amperios: <b>R = (V − Vled) / I</b>. 3) Elige el valor comercial superior. Al revés, si ya tienes la resistencia: <b>I = (V − Vled) / R</b>.', q: mcq('Pin de 5 V, LED verde de 2,1 V y 10 mA. ¿Qué resistencia comercial?', ['330 Ω', '220 Ω', '290 Ω', '510 kΩ'], '(5 − 2,1) / 0,01 = 290 Ω → 330 Ω.') },
    { title: 'Lo que le sobra al LED', text: 'El LED se queda con su tensión (unos 2 V un rojo, unos 3 V un azul) y la resistencia con el resto: R = (V − Vled) / I, o I = (V − Vled) / R. Con los 3,3 V del ESP32 y un LED rojo sobran solo 1,3 V, así que para la misma corriente la resistencia es más pequeña que con 5 V. Ojo con las unidades: 10 mA son 0,01 A.', q: mcq('Pin de 3,3 V, LED rojo de 2 V y 220 Ω. ¿Corriente?', ['Unos 6 mA', 'Unos 15 mA', 'Unos 24 mA', 'Unos 0,6 mA'], '(3,3 − 2) / 220 ≈ 0,0059 A ≈ 6 mA.') }
  ] },
  mc_pinlimit: { name: 'Cargas grandes: el pin solo da la orden', alts: [
    { title: 'Un grifo pequeño', text: 'Un pin de la Uno da cómodamente unos 20 mA (40 mA es el máximo absoluto) y el chip entero, unos 200 mA sumando todos sus pines. Basta para un LED, no para un relé ni un motor. Para cargas mayores, el pin manda la orden (incluso PWM) a un <b>transistor o MOSFET</b>, que conmuta la corriente de la carga desde su propia fuente; con motores y relés, más un diodo de rueda libre. Un MOSFET bien encendido apenas se calienta: P = I² · Rds(on).', q: mcq('Un relé pide 70 mA. ¿Cómo lo activas desde un pin?', ['Con un transistor (y un diodo de rueda libre en la bobina)', 'Directo al pin', 'Con dos pines en paralelo', 'Con una resistencia en serie'], '70 mA supera lo que da un pin.') },
    { title: 'Suma antes de conectar', text: 'Suma lo que piden las cargas: 12 LEDs a 20 mA son 240 mA, más que los unos 200 mA que aguanta el chip entero (y cada pin, unos 20 mA). Un motor de cientos de mA, ni hablar. La solución es la misma: un transistor o MOSFET hace de interruptor grande y el pin solo lo controla (también con PWM). Un MOSFET bien encendido disipa P = I² · Rds(on): con 0,5 A y 0,05 Ω, 12,5 mW.', q: mcq('Un MOSFET con Rds(on) = 0,2 Ω conmuta 0,5 A. ¿Cuánto disipa?', ['50 mW', '100 mW', '10 mW', '2,5 W'], '0,5² × 0,2 = 0,05 W = 50 mW.') }
  ] },
  mc_serialio: { name: 'Escribir y leer por Serial', alts: [
    { title: 'Un chivato en el programa', text: 'Serial.print() envía texto al ordenador por USB sin saltar de línea y Serial.println() salta al final. Entre comillas se imprime el texto tal cual; sin comillas, el valor de la variable. Úsalo como chivato: pon un println dentro del if sospechoso; si no aparece, la condición no se cumple, e imprime los valores que compara. También puede leer: Serial.read() saca los caracteres que envías, uno a uno.', q: mcq('int n = 4; Serial.print("n="); Serial.println(n); ¿Qué aparece?', ['n=4', 'n=n', 'n= y 4 en dos líneas', '4n='], 'print no salta de línea; sin comillas se imprime el valor.') },
    { title: 'También escucha', text: 'La placa puede leer lo que escribes en el monitor: <b>Serial.available()</b> dice cuántos caracteres esperan y <b>Serial.read()</b> saca el primero. Llegan en orden, uno a uno: si cada carácter da una orden, la última manda. Y para ver qué pasa dentro del programa, imprime con print (sin salto) o println (con salto) los valores que te interesan.', q: mcq('Con if (c == \'e\') enciende y if (c == \'a\') apaga, envías «aea». ¿Cómo queda el LED?', ['Apagado', 'Encendido', 'Parpadeando', 'Depende de los baudios'], 'Lee a (apaga), e (enciende) y a (apaga): manda el último.') }
  ] },
  mc_baud: { name: 'Baudios: cuánto tarda en salir el texto', alts: [
    { title: 'Bits por segundo', text: 'Los baudios son bits por segundo. Cada carácter viaja como <b>10 bits</b> (8 de datos, uno de inicio y uno de parada). Tiempo = caracteres × 10 / baudios. A 9600 baudios, 96 caracteres son 960 bits: 0,1 s = 100 ms.', q: mcq('A 9600 baudios, ¿cuánto tarda un mensaje de 48 caracteres?', ['50 ms', '5 ms', '0,5 s', '40 ms'], '48 × 10 / 9600 = 0,05 s.') },
    { title: 'Caracteres por segundo', text: 'Divide los baudios entre 10 y tendrás caracteres por segundo: 9600 → 960 caracteres/s; 115 200 → 11 520. Luego, longitud del mensaje / caracteres por segundo. El error típico es contar 8 bits por carácter y olvidar los bits de inicio y de parada.', q: mcq('A 115 200 baudios, ¿cuántos caracteres salen por segundo, aproximadamente?', ['11 520', '115 200', '14 400', '1152'], '115 200 / 10 = 11 520. Con 8 bits por carácter saldría 14 400, pero cada uno lleva 2 bits más.') }
  ] },
  mc_levels: { name: 'Niveles de tensión: 5 V y 3,3 V', alts: [
    { title: 'Dos idiomas de tensión', text: 'La Uno trabaja a 5 V: lee HIGH por encima de unos 3 V y LOW por debajo de 1,5 V; en medio, no está garantizado. El ESP32, la Pico y muchos sensores trabajan a 3,3 V y sus pines <b>no toleran 5 V</b>: una salida de 5 V puede dañarlos. Entre los dos mundos, adaptador de niveles o divisor. Ojo: que un módulo admita 5 V en VIN (porque lleva regulador) no significa que sus pines de datos los aguanten.', q: mcq('Un sensor de 3,3 V tiene su pin de datos conectado a una salida de la Uno. ¿Qué pones en medio?', ['Un adaptador de niveles o un divisor de tensión', 'Nada: es solo una señal', 'Un condensador', 'Un LED'], 'Los 5 V de la salida pueden dañar el pin de 3,3 V.') },
    { title: 'Alimentación y datos, por separado', text: 'Antes de conectar un módulo, comprueba dos tensiones. <b>Alimentación</b>: ¿lleva regulador? Entonces admite 5 V en VIN aunque el chip sea de 3,3 V. <b>Datos</b>: ¿sus pines aguantan 5 V? Si no, adapta niveles (el ESP32 no tolera 5 V). Y al leer: la Uno ve HIGH por encima de unos 3 V y LOW por debajo de 1,5 V; entre medias, la lectura es incierta.', q: mcq('Un pin de la Uno recibe 2,4 V. ¿Qué lee digitalRead()?', ['No está garantizado: es la zona indefinida', 'HIGH', 'LOW', 'Un error'], 'Entre 1,5 y 3 V el chip puede leer cualquiera de los dos.') }
  ] },
  mc_pullup: { name: 'Pulsador con pull-up', alts: [
    { title: 'Un muelle', text: 'Una entrada sin nada conectado (INPUT) <b>flota</b>: lee al azar con el ruido y puede gastar más. Una resistencia de <b>pull-up</b> es un muelle que la mantiene en HIGH; el pulsador, entre el pin y <b>GND</b>, la lleva a LOW al cerrarse. Por eso, con pull-up, <b>pulsado = LOW y suelto = HIGH</b>. INPUT_PULLUP activa una interna de 20–50 kΩ. (Con pull-down es al revés: pulsado = HIGH.)', q: mcq('Con INPUT_PULLUP y el pulsador a GND, ¿qué lee el pin con el botón suelto?', ['HIGH', 'LOW', 'Al azar', 'Depende del programa'], 'Suelto, la pull-up lo mantiene arriba.') },
    { title: 'Con números', text: 'Sin resistencia, la entrada flotaría y leería al azar. Con pull-up, al pulsar la resistencia queda entre 5 V y GND y pasa <b>I = V / R</b>: con 10 kΩ, 5 / 10 000 = 0,5 mA. Por eso son de varios kΩ: pequeñas gastarían mucho. Suelto no pasa corriente y el pin lee HIGH; pulsado lee LOW. Con una pull-down (resistencia a GND y pulsador a 5V) es al revés.', q: mcq('Pull-up de 4,7 kΩ a 5 V. ¿Corriente con el botón pulsado?', ['Unos 1,1 mA', 'Unos 23 mA', '0 mA', 'Unos 4,7 mA'], '5 / 4700 ≈ 0,00106 A ≈ 1,1 mA.') },
    { title: 'Lógica invertida en el código', text: 'Con pull-up, el código «al revés» es lo normal: if (digitalRead(2) == LOW) significa «si está pulsado»; para «mientras NO esté pulsado», compara con HIGH. El pulsador va del pin a GND. La pull-up evita que la entrada flote (sin ella leería al azar y gastaría más) y, al pulsar, solo deja pasar V / R: unos 0,5 mA con 10 kΩ.', q: mcq('Con INPUT_PULLUP, ¿qué condición enciende un LED solo mientras pulsas?', ['digitalRead(2) == LOW', 'digitalRead(2) == HIGH', 'digitalRead(2) = LOW', 'digitalRead(2) > 1'], 'Pulsado = LOW con pull-up.') }
  ] },
};
